(window.GIM_TS=window.GIM_TS||{})["Megillah.1"]={"from":24,"a":[["ה\u0003משל\u0004 של \u0003אחשורוש והמן למה הדבר דומה? לשני בני אדם, לאחד היה לו תל בתוך שדהו ולאחד היה לו חריץ\u0004 (תעלה) \u0003בתוך שדהו,\u0004 וכל אחד מהם סבל מן הבעיה שלו. \u0003בעל חריץ אמר: מי יתן לי תל זה בדמים\u0004 (בכסף) ואוכל למלאות באדמת התל את החריץ שבשדי, \u0003בעל התל אמר: מי יתן לי חריץ זה בדמים.\u0004","\u0003לימים\u0004 לאחר זמן \u0003נזדווגו\u0004 (נזדמנו) \u0003זה אצל זה, אמר לו בעל החריץ לבעל התל: מכור לי תילך! אמר לו: טול אותו בחנם, והלואי!\u0004 ואף כאן: אחשורוש עצמו רצה להשמיד את היהודים אלא שלא היה מי שיהיה מוכן לעשות את הדבר עבורו, ומשמצא את המן שהיה מעוניין ליטול זאת על עצמו שמח ביותר, ולכן לא ביקש כל תשלום.","\u0003\"ויסר המלך את טבעתו\"\u0004 (אסתר ג, י), \u0003אמר ר' אבא בר כהנא: גדולה הסרת טבעת\u0004 של אחשורוש שבה נחתמה גזירת המן \u0003יותר מארבעים ושמונה נביאים ושבע נביאות שנתנבאו להן לישראל, שכולן לא החזירום למוטב, ואילו הסרת\u0004 ה\u0003טבעת\u0004 של אחשורוש \u0003החזירתן למוטב,\u0004 שעל־ידיה עשו תשובה גדולה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעים ושמונה נביאים ושבע נביאות נתנבאו להם לישראל, ו\u0004כל אלה \u0003לא פחתו ולא הותירו על מה שכתוב בתורה\u0004 שלא שינו במצוות התורה לא לפחות ולא להוסיף, \u0003חוץ ממקרא מגילה\u0004 שהוסיפו במשך הדורות.","ושואלים: \u0003מאי דרוש\u0004 \u0005[מה דרשו]?\u0006 ועל מה סמכו כשהוסיפו מצוה זו? \u0003אמר ר' חייא בר אבין אמר ר' יהושע בן קרחה: ומה\u0004 כשיצאו ישראל ממצרים \u0003מעבדות לחירות אמרינן\u0004 \u0005[אומרים אנו]\u0006 בגלל גאולה זו \u0003שירה,\u0004 שירת הים ושירת הלל — כשיצאנו \u0003ממיתה לחיים\u0004 מידי המן \u0003לא כל שכן.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003הלל נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 בפורים! ומשיבים: \u0003לפי שאין אומרים הלל על נס ש\u0004נעשה \u0003בחוצה לארץ,\u0004 ושואלים: אם כך, \u0003יציאת מצרים\u0004 שהיא \u0003נס\u0004 שהיה \u0003בחוצה לארץ, היכי אמרינן\u0004 \u0005[איך אנו אומרים]\u0006 עליה \u0003שירה?\u0004","ומשיבים: \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003עד שלא נכנסו ישראל לארץ — הוכשרו כל הארצות לומר שירה,\u0004 שהיו כולן שוות, אולם \u0003משנכנסו ישראל לארץ,\u0004 נתקדשה ארץ ישראל קדושה יתירה, ו\u0003לא הוכשרו כל\u0004 שאר \u0003הארצות לומר\u0004 בשל נס שאירע בהם \u0003שירה.\u0004","\u0003רב נחמן אמר\u0004 טעם אחר: הסיבה שאין אומרים בפורים הלל, משום ש\u0003קרייתא\u0004 \u0005[קריאתה]\u0006 של המגילה, \u0003זו\u0004 היא עצמה אמירת \u0003הלילא\u0004 \u0005[הלל],\u0006 ובמקום לומר הלל קוראים את המגילה. \u0003רבא אמר\u0004 טעם אחר: \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 ביציאת מצרים אנו אומרים בהלל: \u0003\"הללו עבדי ה'\"\u0004 (תהלים קיג, א) כלומר: עבדי ה' \u0003ולא עבדי פרעה, אלא הכא\u0004 \u0005[כאן]\u0006 האם נאמר \u0003\"הללו עבדי ה'\" ולא עבדי אחשורוש?\u0004 הלא \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003עבדי אחשורוש אנן\u0004 \u0005[אנחנו]\u0006 שהרי ישראל נמצאים בגלות (ומהם תחת שלטון הפרסים) ולא נשתנה מצב זה ביסודו.","ושואלים: \u0003בין לרבא בין לרב נחמן קשיא\u0004 \u0005[קשה]\u0006 דבר זה, שכן \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003משנכנסו לארץ לא הוכשרו כל הארצות לומר שירה,\u0004 ומדבריהם נראה או שבעצם אומרים אנו שירה (בקריאת המגילה לשיטת רב נחמן), או שאין אומרים הלל מחמת סיבה נפרדת (לשיטת רבא), והלא ישנה הבעיה העקרונית שלא הוכשרו כל הארצות לומר שירה! ומשיבים: זה אינו קושי שאפשר לומר: \u0003כיון שגלו\u0004 מן הארץ \u0003חזרו\u0004 שאר ארצות \u0003להכשירן הראשון.\u0004","אמרנו שנתנבאו לישראל ארבעים ושמונה נביאים ושבע נביאות, ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר\u0006 מזה \u0005אין]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויהי איש אחד מן הרמתים צופים\"\u0004 (שמואל א' א, א), ופירשוהו: \u0003אחד ממאתים\u0004 (\"הר מאתיים\") \u0003צופים\u0004 (נביאים) \u0003שנתנבאו להם לישראל.\u0004 ואם כן, מדוע אמרו שהיו רק ארבעים ושמונה?","ומשיבים: \u0003מיהוה טובא הוו\u0004 \u0005[היה היו הרבה\u0006 נביאים\u0005],\u0006 \u0003כדתניא\u0004 \u0005[\u0006ו\u0005כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרבה נביאים עמדו להם לישראל,\u0004 ובסך הכל היה מספרם \u0003כפלים כיוצאי מצרים, אלא נבואה שהוצרכה לדורות — נכתבה, ושלא הוצרכה — לא נכתבה\u0004 ולכן אין הנביאים הללו נזכרים במקרא.","\u0003ר' שמואל בר נחמני אמר:\u0004 \"מן הרמתיים צופים\" פירושו: \u0003אדם הבא משתי רמות שצופות זו את זו. ר' חנין אמר: אדם הבא\u0004 (שמוצאו) \u0003מבני אדם שעומדים ברומו\u0004 (בגובהו) \u0003של עולם.\u0004 ושואלים: \u0003ומאן נינהו\u0004 \u0005[מי הם\u0006 אנשים \u0005אלה]?\u0006 ומשיבים: \u0003בני קרח, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובני קרח לא מתו\"\u0004 (במדבר כו, יא), ועל זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משום רבינו\u0004 (רבי): \u0003מקום\u0004 גבוה \u0003נתבצר להם\u0004 (נעשה להם) \u0003בגיהנם,\u0004 כשפתחה האדמה את פיה לבלוע את עדת קורח \u0003ועמדו עליו,\u0004 ונמצאו הם לבדם עומדים ברומו של עולם.","ושואלים: \u0003שבע נביאות מאן נינהו\u0004 \u0005[מי הן]?\u0006 ומשיבים: \u0003שרה, מרים, דבורה, חנה, אביגיל, חולדה ואסתר.\u0004 ומבררים ביחס לכל אחת ואחת כיצד יודעים שהיתה נביאה: \u0003שרה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004הרן \u0003אבי מלכה ואבי יסכה\"\u0004 (בראשית יא, כט) \u0003ואמר ר' יצחק: \"יסכה\" זו\u0004 באמת \u0003שרה, ולמה נקרא שמה \"יסכה\" — שסכתה\u0004 (ראתה) \u0003ברוח הקדש, שנאמר: \"כל אשר תאמר אליך שרה שמע בקלה\"\u0004 (בראשית כא, יב), שכן ברוח הקודש היא מדברת. \u0003דבר אחר: \"יסכה\" — שהכל סוכין\u0004 (מסתכלים) \u0003ביופיה.\u0004","\u0003מרים\u0004 שהיתה נביאה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותקח מרים הנביאה אחות אהרן\"\u0004 (שמות טו, כ). ושואלים: מדוע היא קרויה אחות אהרון, וכי רק אחותו היתה \u0003ולא אחות משה? אמר רב נחמן אמר רב: שהיתה מתנבאה כשהיא אחות אהרן,\u0004 כלומר, עוד לפני שנולד משה, \u0003ואומרת: עתידה אמי שתלד בן שיושיע את ישראל. ובשעה שנולד\u0004 משה \u0003נתמלא כל הבית כולו אורה, עמד אביה ונשקה על ראשה, אמר לה: בתי נתקיימה נבואתיך.\u0004","\u0003וכיון שהשליכוהו ליאור עמד אביה וטפחה\u0004 (הכה) \u0003על ראשה ואמר לה: בתי היכן נבואתיך?\u0004 שהרי אנו רואים שהילד הושלך ליאור! \u0003היינו דכתיב\u0004 \u0005[הוא שנאמר]:\u0006 \u0003\"ותתצב אחתו מרחק לדעה\u0004 מה ייעשה לו\u0003\"\u0004 (שמות ב, ד) וכוונתו: \u0003לדעת מה יהא בסוף נבואתה\u0004 שהרי היא ניבאה שהוא יהיה מושיע ישראל.","\u0003דבורה, דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש: \u0003\"ודבורה אשה נביאה אשת לפידות\"\u0004 (שופטים ד, ד). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אשת לפידות\"?\u0004 ומשיבים: \u0003שהיתה\u0004 מתנדבת ו\u0003עושה פתילות למקדש\u0004 ועל שם פתילות־לפידים אלה קראו לה \"אשת לפידות\".","נאמר בדבורה: \u0003\"והיא יושבת תחת תמר\"\u0004 (שופטים ד, ה), ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה],\u0006 מדוע ישבה דווקא \u0003תחת תומר\u0004 ולא במקום אחר? \u0003אמר ר' שמעון בן אבשלום: משום יחוד,\u0004 שכיוון שבאו אליה אנשים לדון לפניה, קבעה לעצמה מקום הגלוי לעין, ולא בחדר מסוגר, משום חשש יחוד עם גבר. \u0003דבר אחר: מה תמר זה אין לו אלא לב אחד\u0004 שעץ הדקל איננו מסתעף לענפים שונים אלא יש לו רק ענף אחד מרכזי בלבד — \u0003אף ישראל שבאותו הדור לא היה להם אלא לב אחד — לאביהם שבשמים.\u0004","\u0003חנה\u0004 שהיתה נביאה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותתפלל חנה ותאמר עלץ לבי בה' רמה קרני בה'\"\u0004 (שמואל א' ב, א), ודורשים את דבריה כך, נאמר: \u0003\"רמה קרני\", ולא\u0004 נאמר \u0003רמה פכי,\u0004 וכך היה למעשה, שכן \u0003דוד ושלמה שנמשחו\u0004 למלוכה \u0003בקרן\u0004 מלאה שמן — \u0003נמשכה מלכותן,\u0004 ואילו \u0003שאול ויהוא שנמשחו בפך\u0004 — \u0003לא נמשכה מלכותן.\u0004 הרי שחזתה את העתיד, ומכאן שנביאה היתה.","כיון שהוזכרה שירת חנה, מפרשים דברים נוספים שאמרה: \u0003\"אין קדוש כה' כי אין בלתך\"\u0004 (שמואל א' ב, ב), \u0003אמר רב יהודה בר מנשיא: אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"בלתך\" אלא לבלותך,\u0004 ופירושו: \u0003שלא כמדת הקדוש ברוך הוא מדת בשר ודם, מדת בשר ודם — מעשה ידיו מבלים אותו\u0004 וקיימים אחרי מותו, \u0003אבל הקדוש ברוך הוא — מבלה מעשה ידיו\u0004 והוא נשאר קיים לעולם.","ועוד נאמר: \u0003\"ואין צור כאלהינו\"\u0004 (שמואל א' ב, ב), ודורשים: \u0003אין צייר כאלהינו.\u0004 ובמה הוא עדיף משאר הציירים? \u0003אדם צר צורה על גבי הכותל\u0004 אולם \u0003אינו יכול להטיל בה רוח ונשמה,\u0004 וכן אינו יכול להכניס בצורה שעשה \u0003קרבים ובני מעים, אבל הקדוש ברוך הוא צר צורה\u0004 (צורת הולד) \u0003בתוך צורה\u0004 של אימו, ולא על מקום שטוח \u0003ומטיל בה\u0004 בתוך הוולד \u0003רוח ונשמה, קרבים ובני מעים.\u0004","\u0003אביגיל,\u0004 מנין שהיתה נביאה? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באביגיל: \u0003\"והיה היא רכבת על החמור וירדת בסתר ההר\"\u0004 (שמואל א' כה, כ), ואומרים: מה הלשון \u0003\"בסתר ההר\"? \"\u0004בסתר \u0003מן ההר\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר.","אלא יש לראות בכך רמז, \u0003אמר רבה בר שמואל: על עסקי דם\u0004 נדה \u0003הבא מן\u0004 בית \u0003הסתרים\u0004 פנתה אביגיל אליו, וכיצד עשתה? \u0003נטלה דם והראתה לו\u0004 ובקשה ממנו שיפסוק לה הלכה, אם דם זה דם נדה הוא או לא. \u0003אמר לה: וכי מראין דם בלילה?\u0004 הרי ידוע שבלילה אין חכמים בודקים כתמי דם מפני שלאור הנר קשה להבחין בין הצבעים, \u0003אמרה לו:\u0004 אם כן תזכור גם הלכה אחרת: \u0003וכי דנין דיני נפשות בלילה? אמר לה\u0004 דוד:"],["נבל בעלך \u0003מורד במלכות הוא,\u0004 שדוד ראה עצמו כמלך, ונבל הוא מסרב לפקודותיו \u0003ולא צריך למידייניה\u0004 \u0005[ואין צורך לדון אותו]\u0006 כדרך שדנים דין אחר. \u0003אמרה לו:\u0004 אינך יכול לעשות זאת כי \u0003עדיין שאול קיים\u0004 והוא מלך בפועל \u0003ולא יצאה טבעך\u0004 (מטבע שלך) \u0003בעולם,\u0004 כלומר עדיין אין אתה מלך מוכר לכל ולכן אינך רשאי לדון אדם כמורד במלכות. \u0003אמר לה: \"\u0004ו\u0003ברוך טעמך וברוכה את אשר כליתני היום הזה מבוא בדמים\"\u0004 (שמואל א' כה, לג).","ושואלים: \u0003דמים\u0004 הלוא \u0003תרתי\u0004 \u0005[שנים]\u0006 \u0003משמע\u0004 ומדוע לא אמר \"בדם\" שהוא לשון יחיד? \u0003אלא מלמד שגילתה את שוקה\u0004 ונתאוה לה \u0003והלך לאורה\u0004 (מן האש שלה) בשל תאוותו אליה, \u0003שלש פרסאות,\u0004 ו\u0003אמר לה: השמיעי לי\u0004 כלומר השמעי לי ותיעתרי לי לבוא עליך. ומכיון שהיתה נדה, הרי דמים תרתי משמע; דם נדה ושפיכות דמים! \u0003אמרה לו: \"\u0004ו\u0003לא תהיה זאת לך לפוקה\"\u0004 (שמואל א' כה, לא) ומדייקים: \u0003\"זאת\" — מכלל דאיכא אחריתי\u0004 \u0005[מכאן שיש אחרת]\u0006 שעשויה להיות לו למכשול, \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 המעשה האחר? ה\u0003מעשה\u0004 של \u0003בת שבע. ומסקנא הכי הואי\u0004 \u0005[והסיום,\u0006 בסוף דבר, \u0005כך היה]\u0006 שאכן נכשל בבת שבע. ומכאן שאביגיל היתה נביאה, שידעה מראש שכך יקרה.","אגב הזכרת ענין זה, מבארים עוד דברים שנאמרו בענין זה. בין הדברים שאמרה אביגיל לדוד, היה גם: \u0003\"והיתה נפש אדני צרורה בצרור החיים\"\u0004 (שמואל א' כה, כט), \u0003כי הוות מיפטרא מיניה\u0004 \u0005[כאשר נפרדה ממנו]\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003\"והטיב ה' לאדני וזכרת את אמתך\"\u0004 (שמואל א' כה, לא)","\u0003אמר רב נחמן: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפיתגם עממי: \u0003איתתא בהדי שותא פילכא\u0004 \u0005[האשה יחד עם השיחה\u0006 היא גם מחזיקה את \u0005הפלך],\u0006 כלומר, אשה אגב עבודה אחת דואגת גם להרויח דבר נוסף, שהרי כל מה שבאה לדוד, היה זה כדי להציל את נבל בעלה, ועם זאת רמזה לו, שאם ימות בעלה יזכור אותה וישאנה לאשה. ואכן כך עשה, שלאחר מות נבל נשא אותה דוד לאשה. \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהשתמש רב נחמן בפתגם אחר: \u0003שפיל ואזיל בר אווזא ועינוהי מיטייפי\u0004 \u0005[משפיל\u0006 את ראשו \u0005והולך הברווז,\u0006 אבל \u0005עיניו צופות]\u0006 מרחוק למצוא דבר מה, אף אביגיל נהגה כן.","\u0003חולדה\u0004 היתה נביאה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילך חלקיהו הכהן ואחיקם ועכבור\u0004 ושפן ועשיה אל חולדה הנביאה\u0003\"\u0004 (מלכים ב' כב, יד) בשליחות המלך יאשיה, ושואלים: \u0003ובמקום דקאי\u0004 \u0005[שעומד,\u0006 שנמצא\u0005]\u0006 \u0003ירמיה היכי מתנביא איהי\u0004 \u0005[איך נתנבאה היא]?\u0006 שמפני כבודו של ירמיהו הגדול ממנה ראוי היה לה שלא להתנבא! \u0003אמרי בי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: חולדה קרובת\u0004 משפחה של \u0003ירמיה היתה, ולא הוה\u0004 \u0005[היה]\u0006 \u0003מקפיד עליה,\u0004","ושואלים: בכל זאת \u0003ויאשיה גופיה\u0004 \u0005[עצמו]\u0006 \u0003היכי שביק\u0004 \u0005[איך עזב]\u0006 את \u0003ירמיה ומשדר לגבה\u0004 \u0005[ושלח אליה]?\u0006 \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא: מפני שהנשים רחמניות הן,\u0004 וקיוה שתאמר לו דברים רכים יותר.","\u0003ר' יוחנן אמר: ירמיה לא הוה התם\u0004 \u0005[היה שם]\u0006 מפני \u0003שהלך להחזיר\u0004 את \u0003עשרת השבטים\u0004 מגלותם. \u0003ומנלן דאהדור\u0004 \u0005[ומניין לנו שהחזירם]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי המוכר אל הממכר לא ישוב\"\u0004 (יחזקאל ז, יג), \u0003אפשר\u0004 ש\u0003יובל\u0004 כבר \u0003בטל,\u0004 לפי שהיובל נוהג רק כשכל שבטי ישראל במקומם, \u0003ונביא מתנבא עליו שיבטל? אלא מלמד שירמיה החזירן,\u0004","\u0003ויאשיהו בן אמון מלך עליהן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר מה הציון הלז אשר אני ראה ויאמרו אליו אנשי העיר הקבר איש האלהים אשר בא מיהודה ויקרא את הדברים האלה אשר עשית על המזבח בבית אל\"\u0004 (מלכים ב' כג, יז), \u0003וכי מה טיבו של יאשיהו על המזבח בבית אל\u0004 שהיא עיר בממלכת ישראל? \u0003אלא מלמד שיאשיהו מלך עליהן. רב נחמן אמר:\u0004 ראיה יש לדבר \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"גם יהודה שת קציר לך בשובי שבות עמי\"\u0004 (הושע ו, יא) משמע ששבו למקומם.","\u0003אסתר\u0004 מניין שהיתה נביאה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי ביום השלישי ותלבש אסתר מלכות\"\u0004 (אסתר ה, א) והרי \u0003\"\u0004ותלבש אסתר \u0003בגדי מלכות\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אלא\u0004 רמז הוא \u0003שלבשתה רוח הקדש, כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ותלבש\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ורוח לבשה את עמשי\"\u0004 (דברי הימים א' יב, יח) וכשם ששם הכוונה לרוח הקודש — אף כאן מלכות זו היא רוח הקודש.","אגב הזכרת הנביאות \u0003אמר רב נחמן: לא יאה\u0004 \u0005[יפה],\u0006 לא מתאימה \u0003יהירותא לנשי\u0004 \u0005[יהירות,\u0006 גאוה, \u0005לנשים].\u0006 וראיה לדבר: \u0003תרתי נשי יהירן הויין וסניין שמייהו\u0004 \u0005[שתי נשים גאוותניות היו ו\u0006היו \u0005שמותיהן מכוערים]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003שמה זיבורתא\u0004 \u0005[דבורה],\u0006 \u0003וחדא\u0004 \u0005[ואחת]\u0006 \u0003שמה כרכושתא\u0004 \u0005[חולדה],\u0006 ומנין שהיו יהירות? \u0003זיבורתא כתיב\u0004 \u0005[דבורה נאמר]\u0006 \u0003בה: \"ותשלח ותקרא לברק\"\u0004 (שופטים ד, ו) \u0003ואילו איהי\u0004 \u0005[היא\u0006 עצמה\u0005]\u0006 \u0003לא אזלה לגביה\u0004 \u0005[הלכה אליו].\u0006 \u0003כרכושתא כתיב\u0004 \u0005[חולדה נאמר]\u0006 \u0003בה: \"אמרו לאיש\u0004 אשר שלח אתכם אלי\u0003\"\u0004 (מלכים ב' כב, טו) \u0003ולא אמרה אמרו למלך.\u0004","כיון שהוזכרה חולדה הנביאה, \u0003אמר רב נחמן: חולדה מבני בניו של יהושע היתה,\u0004 ורמז לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"\u0004חולדה הנביאה אשת שלם בן תקוה \u0003בן חרחס\"\u0004 (מלכים ב' כב, יד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 ביהושע: \u0003\"\u0004ויקברו אותו... \u0003בתמנת חרס\"\u0004 (שופטים ב, ט) ללמד שיש קשר ביניהם.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב עינא סבא\u0004 \u0005[הזקן]\u0006 \u0003לרב נחמן:\u0004 הלא שנינו — \u0003שמונה נביאים והם כהנים יצאו מרחב הזונה, ואלו הן: נריה\u0004 ובנו \u0003ברוך, ושריה,\u0004 ו\u0003מחסיה\u0004 אביו, ו\u0003ירמיה\u0004 ואביו \u0003חלקיה, חנמאל\u0004 בן דודו של ירמיה, \u0003ושלום\u0004 אבי חנמאל. \u0003ר' יהודה אומר: אף חולדה הנביאה מבני בניה של רחב הזונה היתה.\u0004 וראיה לדבר: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בחולדה \u0003\"בן תקוה\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 ברחב \u0003\"את תקות חוט השני\"\u0004 (יהושע ב, יח).","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עינא סבא,\u0004 \u0005[הזקן]\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר לו: \u0003פתיא אוכמא\u0004 \u0005[סיר שחור]\u0006 כלומר, עמית בתורה שיגע והשחיר פניו עליה, \u0003מיני ומינך\u0004 \u0005[ממני וממך]\u0006 \u0003תסתיים שמעתא\u0004 \u0005[השמועה]\u0006 שאנחנו יכולים לצרף את שתי השמועות ולומר: \u0003דאיגיירא ונסבה\u0004 \u0005[שהתגיירה\u0006 רחב \u0005ונשאה]\u0006 \u0003יהושע\u0004 והיתה חולדה איפוא גם מזרעו של יהושע וגם משל רחב. ותוהים: \u0003ומי הוו ליה זרעא\u0004 \u0005[האם היה לו זרע]\u0006 \u0003ליהושע? והכתיב\u0004 \u0005[והרי נאמר]\u0006 ברשימת היחס של שבט אפרים: \u0003\"... נון בנו יהושע בנו\"\u0004 (דברי הימים א' ז, כז) ואינו מונה הלאה, משמע שלא היו לו בנים! ומשיבים: אכן, \u0003בני\u0004 \u0005[בנים]\u0006 \u0003לא הוו ליה\u0004 \u0005[היו לו],\u0006 ואולם \u0003בנתן הוו ליה\u0004 \u0005[בנות היו לו].\u0006"],["ושואלים: \u0003בשלמא אינהו\u0004 \u0005[נניח הם]\u0006 — \u0003מיפרשי\u0004 \u0005[מפורשים]\u0006 שנביאים היו, כלומר — ירמיה הנביא, ברוך תלמידו, שהיה מבני הנביאים, חנמאל בן דודו, שבא אליו בדבר ה' (ירמיהו פרק לב), וגם שריה, תלמיד ירמיה. \u0003אלא אבהתייהו\u0004 \u0005[אבותיהם]\u0006 חלקיה, נריה, שלום, מחסיה \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שהיו נביאים?","ומשיבים: \u0003כ\u0004דברי \u0003עולא,\u0004 ש\u0003אמר עולא: כל מקום ששמו ושם אביו\u0004 של אדם נזכרים \u0003ב\u0004עניין של \u0003נביאות — בידוע שהוא נביא בן נביא,\u0004 ולכן נזכר גם שם אביו. ואם נזכר רק \u0003שמו ולא שם אביו — בידוע שהוא נביא ולא בן נביא,\u0004 וכן אם נזכר \u0003שמו ושם עירו מפורש — בידוע שהוא מאותה העיר,\u0004 ואם מוזכר רק \u0003שמו ולא שם עירו — בידוע שהוא מירושלים.\u0004","ובעניין זה \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003כל שמעשיו ומעשה אבותיו סתומים,\u0004 ולא נתבאר במקרא מה היה טיבו, אבל \u0003פרט לך הכתוב באחד מהם לשבח, כגון \"דבר ה' אשר היה אל צפניה בן כושי בן גדליה\"\u0004 (צפניה א, א) — \u0003בידוע שהוא צדיק בן צדיק.\u0004 ולהיפך, \u0003וכל שפרט לך הכתוב באחד מהן לגנאי כגון: \"ויהי בחדש השביעי בא ישמעאל בן נתניה בן אלישמע\"\u0004 (ירמיהו מא, א) שהרג את גדליה, \u0003בידוע שהוא רשע בן רשע.\u0004","\u0003אמר רב נחמן: מלאכי\u0004 הנביא — \u0003זה מרדכי, ולמה נקרא שמו מלאכי?\u0004 לרמז \u0003שהיה משנה למלך. מיתיבי\u0004 \u0005[ומקשים]\u0006 על כך ממה ששנינו: \u0003ברוך בן נריה ושריה בן מחסיה ודניאל ומרדכי בלשן, וחגי, זכריה ומלאכי — כולן נתנבאו בשנת שתים לדריוש,\u0004 וכיון שנמנה מרדכי לחוד ומלאכי לחוד — משמע ששניים היו, ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו הדברים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' יהושע בן קרחה: מלאכי — זה עזרא, וחכמים אומרים: מלאכי שמו, אמר רב נחמן: מסתברא כמאן דאמר\u0004 \u0005[מסתבר כ\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003מלאכי זה עזרא,\u0004 מפני שאנחנו מוצאים דמיון ביניהם, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בנביאות מלאכי: \"בגדה יהודה ותועבה נעשתה בישראל ובירושלים כי חלל יהודה קדש ה' אשר אהב ובעל בת אל נכר\"\u0004 (מלאכי ב, יא)","\u0003ומאן אפריש\u0004 \u0005[ומי\u0006 הוא זה \u0005שהפריש]\u0006 \u0003נשים גויות\u0004 הנשואות ליהודים — \u0003עזרא, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויען שכניה בן יחיאל מבני עילם ויאמר לעזרא: אנחנו מעלנו באלהינו ונשב נשים נכריות\"\u0004 (עזרא י, ב) על כן נראה שמלאכי הוא כינוי לעזרא.","ולסיכום בענין הנביאות שנזכרו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבע נשים יפיפיות היו בעולם: שרה ואביגיל רחב ואסתר, ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]:\u0006 \u0003אסתר ירקרוקת היתה\u0004 ורק חן היה לה — \u0003מפיק\u0004 \u0005[מוציא]\u0006 את \u0003אסתר ומעייל\u0004 \u0005[ומכניס]\u0006 את \u0003ושתי\u0004 במקומה, שהיתה יפהפיה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003רחב בשמה זינתה\u0004 כלומר הזכרת שמה בלבד היתה גורם להתאוות לה, \u0003יעל — בקולה, אביגיל — בזכירתה,\u0004 שנזכרים בה, \u0003מיכל בת שאול\u0004 — \u0003בראייתה,\u0004 כשרואים אותה. כיוצא בזה, \u0003אמר ר' יצחק: כל האומר \"רחב\" \"רחב\" — מיד ניקרי\u0004 \u0005[\u0006הוא \u0005רואה קרי]\u0006 מרוב תאווה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: אנא אמינא\u0004 \u0005[אני אומר]\u0006 \u0003\"רחב, רחב\" ולא איכפת לי,\u0004 שלא קורה לי דבר! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי קאמינא\u0004 \u0005[כאשר אמרתי]\u0006 \u0003ביודעה ובמכירה\u0004 התכוונתי, שרק אז הזכרת שמה בלבד פועלת כל כך.","ושוב לפירוש הפסוקים במגילה, נאמר: \u0003\"ומרדכי ידע את כל אשר נעשה\u0004 ויקרע מרדכי את בגדיו וילבש שק ואפר ויצא בתוך העיר ויזעק זעקה גדולה ומרה\u0003\"\u0004 (אסתר ד, א) ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר\u0004 בצעקתו זו? \u0003רב אמר,\u0004 שמרדכי אמר: \u0003גבה המן מאחשורוש,\u0004 שראה שהמן נעשה חזק יותר מאחשורוש עצמו, והכל ברשותו, \u0003ושמואל אמר: גבר מלכא עילאה ממלכא תתאה\u0004 \u0005[גבר מלך עליון על מלך תחתון]\u0006 והיא בלשון נקיה, שרוצה לומר ההיפך, שנראה שגבר אחשורוש מלך תחתון על המלך העליון (הקדוש ברוך הוא) שרוצה את טובתם של ישראל.","נאמר: \u0003\"ותתחלחל המלכה\"\u0004 (אסתר ד, ד), ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ותתחלחל\"? אמר רב:\u0004 כוונתו ש\u0003פירסה נדה\u0004 מן הבהלה, מלשון חללים, שנפתחו חללי גופה, \u0003ור' ירמיה אמר\u0004 בדומה לזה: \u0003שהוצרכה לנקביה.\u0004","נאמר: \u0003\"ותקרא אסתר להתך\"\u0004 (אסתר ד, ה), \u0003אמר רב: התך זה דניאל, ולמה נקרא שמו התך — שחתכוהו מגדולתו,\u0004 שהורידוהו מגדולתו בזמן אחשורוש, שקודם היה שר גדול ולבסוף נעשה רק כמשרת אצל אסתר. \u0003ושמואל אמר\u0004 גם הוא שדורשים התך = חתך, אבל במובן הפוך: \u0003שכל דברי מלכות נחתכין על פיו.\u0004","נאמר: \u0003\"לדעת מה זה ועל מה זה\"\u0004 (אסתר ד, ה), \u0003אמר ר' יצחק, שלחה לו\u0004 אסתר למרדכי: \u0003שמא עברו ישראל על חמשה חומשי תורה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בהן: \"מזה ומזה הם כתבים\"\u0004 (שמות לב, טו).","נאמר: \u0003\"ויגידו למרדכי את דברי אסתר\"\u0004 (אסתר ד, יב), \u0003ואילו איהו\u0004 \u0005[הוא]\u0006 התך עצמו \u0003לא אזל לגביה\u0004 \u0005[הלך אליו].\u0006 ומסבירים: \u0003מכאן\u0004 למדנו דרך ארץ \u0003שאין משיבים על הקלקלה.\u0004 שאם שומעים מאדם שמועה רעה, אין זו מידת דרך ארץ לשוב ולספרה, וראוי לאדם לשתוק. ולכן מסר זאת ביד שליחים אחרים.","אמרה לו אסתר: \u0003\"לך כנוס את כל היהודים\u0004 הנמצאים בשושן וצומו עלי ואל תאכלו ואל תשתו לילה ויום גם אני ונערותי אצום כן ובכן אבוא אל המלך \u0003אשר לא כדת\"\u0004 (אסתר ד, טז), \u0003אמר ר' אבא: שלא כדת היה,\u0004 שלא כמו בכל יום, \u0003שבכל יום ויום עד עכשיו\u0004 כשאני באה אל אחשורוש הרי זה \u0003באונס, ועכשיו\u0004 אני באה \u0003ברצון.\u0004 ועוד אמרה אסתר: \u0003\"וכאשר אבדתי אבדתי\"\u0004 (אסתר ד, טז), והכוונה בזה: \u0003כשם שאבדתי מבית אבא\u0004 שהובאתי לכאן, \u0003כך אובד ממך\u0004 שהרי אני הולכת אל הגוי ברצון ואז אהיה אסורה לך.","\u0003\"ויעבר מרדכי\"\u0004 (אסתר ד, יז). \u0003אמר רב:\u0004 לומר \u0003שהעביר יום ראשון של פסח בתענית,\u0004 ומפרש \"ויעבור\" מלשון עבירה. \u0003ושמואל אמר:\u0004 ש\u0003עבר ערקומא דמיא\u0004 \u0005[נחל מים]\u0006 כדי להודיע על הענין לכול.","נאמר: \u0003\"ויהי ביום השלישי ותלבש אסתר מלכות\"\u0004 (אסתר ה, א), ותוהים: \u0003\"\u0004ותלבש אסתר \u0003בגדי מלכות\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ר' אלעזר אמר ר' חנינא: מלמד שלבשתה רוח הקדש. כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ותלבש\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ורוח לבשה את עמשי\"\u0004 (דברי הימים א' יב, יט). וכיון שהבאנו דברים שאמר ר' אלעזר בשם ר' חנינא, מובאים עוד דברים שאמר בשמו.","\u0003ואמר ר' אלעזר אמר ר' חנינא: לעולם אל תהי ברכת הדיוט\u0004 (אדם פשוט) \u0003קלה\u0004 ובלתי חשובה \u0003בעיניך, שהרי שני גדולי הדור ברכום שני הדיוטות ונתקיימה בהם\u0004 הברכה, \u0003ואלו הן: דוד ודניאל; דוד\u0004 — \u0003דברכיה\u0004 \u0005[שבירך אותו]\u0006 \u0003ארונה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ארונה אל המלך\u0004 ה' אלהיך ירצך\u0003\"\u0004 (ה' אלוהיך יברכך) (שמואל ב' כד, כג), ונתקיימה בו. \u0003דניאל\u0004 — \u0003דברכיה\u0004 \u0005[שבירך אותו]\u0006 \u0003דריוש דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלהך די אנת פלח לה בתדירא הוא ישיזבנך\"\u0004 \u0005[אלוהיך שאתה עובד אותו תמיד הוא יצילך]\u0006 (דניאל ו, יז), וכך אכן אירע לו, שניצל מגוב האריות.","\u0003ואמר ר' אלעזר אמר ר' חנינא: אל תהי קללת הדיוט קלה בעיניך, שהרי אבימלך קלל את שרה,\u0004 שאמר לה: \u0003\"הנה הוא לך כסות עינים\"\u0004 (בראשית כ, טז) ובלשון זו נרמזת כסות עינים, עיוורון, \u0003ו\u0004אכן \u0003נתקיים\u0004 הדבר \u0003בזרעה,\u0004 שנאמר: \u0003\"ויהי כי זקן יצחק ותכהין עיניו\"\u0004 (בראשית כז, א) והרי זו כסות עיניים.","\u0003ואמר ר' אלעזר אמר ר' חנינא: בא וראה שלא כמדת הקדוש ברוך הוא מדת בשר ודם; מדת בשר ודם,\u0004 תחילה \u0003אדם שופת קדרה\u0004 (מניח אותה על האש) \u0003ואחר כך נותן לתוכה מים, אבל הקדוש ברוך הוא\u0004 קודם \u0003נותן מים ואחר כך שופת הקדרה, לקיים מה שנאמר: \"לקול תתו המון מים בשמים\"\u0004 (ירמיה י, יג) שהוא מפרש: קודם הוא נותן המון מים, ואחר כך הוא יוצר את השמים לשים בהם את המים.","\u0003ואמר ר' אלעזר אמר ר' חנינא: כל האומר דבר בשם אומרו מביא גאולה לעולם.\u0004 וראיה לדבר ממה \u0003שנאמר: \"ותאמר אסתר למלך בשם מרדכי\"\u0004 (אסתר ב, כב) את מעשה בגתן ותרש, והביא הדבר גאולה לעולם.","ועוד \u0003אמר ר' אלעזר אמר ר' חנינא:\u0004 אם \u0003צדיק אבד\u0004 — הרי \u0003לדורו אבד,\u0004 שהאבידה היא לדור שהצדיק נעדר ממנו, ולא לצדיק עצמו. \u0003משל לאדם שאבדה לו מרגלית,\u0004 למרגלית לא איכפת, כי \u0003כל מקום שהיא\u0004 נמצאת בו \u0003מרגלית שמה — לא אבדה אלא לבעלה.\u0004","במגילת אסתר, נאמר שהמן אמר: \u0003\"וכל זה איננו שוה לי\"\u0004 (אסתר ה, יג), \u0003אמר ר' אלעזר אמר ר' חנינא: בשעה שראה המן את מרדכי יושב בשער המלך, אמר: \"כל זה איננו שוה לי\".\u0004 ומסבירים: שדבר זה הוא \u0003כ\u0004דברי \u0003רב חסדא,\u0004 ש\u0003אמר רב חסדא: זה בא בפרוזבולי\u0004 בעושר וכבוד \u0003וזה בא\u0004"],["\u0003בפרוזבוטי\u0004 בעניות, בשטר עניות, משום שמרדכי ידע את מוצאו של המן, שהיה נמוך ביותר. \u0003אמר רב פפא: וקרו ליה עבדא דמזדבן בטלמי\u0004 \u0005[וקוראים לו עבד שנמכר בלחם].\u0006","נאמר: \u0003\"וכל זה איננו שוה לי\" — מלמד שכל גנזיו של אותו רשע\u0004 היו \u0003חקוקין\u0004 (מצויירים) \u0003על לבו ובשעה ש\u0004היה \u0003רואה את מרדכי יושב בשער המלך, אמר: כל זה\u0004 שנמצא כאן על לבי \u0003איננו שוה לי.\u0004","\u0003ואמר ר' אלעזר אמר ר' חנינא: עתיד הקדוש ברוך הוא להיות עטרה בראש כל צדיק וצדיק, שנאמר: \"ביום ההוא יהיה ה' צבאות לעטרת צבי\u0004 ולצפירת תפארה לשאר עמו\u0003\"\u0004 (ישעיהו כח, ה), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לעטרת צבי ולצפירת תפארה\" — לעושין צביונו\u0004 (רצונו) \u0003ולמצפין\u0004 (\"צפירת\") \u0003תפארתו. יכול\u0004 תהא זו בשורה \u0003לכל — תלמוד לומר: \"לשאר עמו\" — למי שמשים עצמו כשירים\u0004 כדבר טפל וקטן, ומי שמחשיב עצמו אינו זוכה לכך.","ובהמשך \u0003\"ולרוח משפט\u0004 ליושב על המשפט ולגבורה משיבי מלחמה שערה\u0003\"\u0004 (ישעיהו כח, ו) — \u0003זה\u0004 המשפט שעושה אדם \u0003הדן את יצרו\u0004 שלו וכופהו לשוב בתשובה. \u0003ו\"ליושב על המשפט\" — זה הדן אמת לאמתו\u0004 אצל האחרים. \u0003\"ולגבורה\" — זה המתגבר על יצרו. \"משיבי מלחמה\" —\u0004 אלה \u0003שנושאין ונותנין\u0004 בהלכה \u0003במלחמתה של תורה. \"שערה\" — אלו תלמידי חכמים שמשכימין ומעריבין בבתי כנסיות ובבתי מדרשות,\u0004 שמתוך שהם באים ראשונים ויוצאים אחרונים, הרי הם נעשים כשוערים.","ובהמשך מפרש מקראות אלה, \u0003אמרה מדת הדין לפני הקדוש ברוך הוא: רבונו של עולם, מה נשתנו אלו\u0004 ישראל שאתה עושה להם ניסים, \u0003מאלו,\u0004 מאומות העולם? \u0003אמר לה הקדוש ברוך הוא: ישראל עסקו בתורה, אומות העולם לא עסקו בתורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 מידת הדין לקדוש ברוך הוא: \u0003\"\u0004ו\u0003גם אלה ביין שגו ובשכר תעו\u0004 כהן ונביא שגו בשכר נבלעו מן היין תעו מן השכר שגו ברואה \u0003פקו פליליה\"\u0004 (ישעיהו כח, ז), ו\u0003אין \"פקו\" אלא גיהנם, שנאמר: \"ולא תהיה זאת לך לפוקה\"\u0004 (שמואל א' כה, לא), \u0003ואין \"פליליה\" אלא דיינין, שנאמר: \"ונתן בפללים\"\u0004 (שמות כא, כב) שגם ישראל חטאו וראויים לעונש.","ושוב לפירוש המגילה, נאמר באסתר: \u0003\"ותעמד בחצר בית המלך הפנימית\"\u0004 (אסתר ה, א), \u0003אמר ר' לוי: כיון שהגיעה לבית הצלמים\u0004 שהיה בפנים, \u0003נסתלקה הימנה שכינה.\u0004 מיד \u0003אמרה: \"אלי אלי למה עזבתני\"\u0004 (תהלים כב, ב)?! \u0003שמא\u0004 נסתלקה ממני שכינה, משום ש\u0003אתה דן על שוגג כמזיד ועל אונס כרצון,\u0004","\u0003או שמא\u0004 נסתלקה ממני שכינה \u0003על שקראתיו\u0004 את המן בתפילתי \u0003\"כלב\", שנאמר: \"הצילה מחרב נפשי מיד כלב יחידתי\"\u0004 (תהלים כב, כא) \u0003חזרה וקראתו\u0004 בתפילתה \u0003\"אריה\", שנאמר: \"הושיעני מפי אריה\"\u0004 (תהלים כב, כב).","נאמר: \u0003\"ויהי כראות המלך את אסתר המלכה\u0004 עומדת בחצר נשאה חן בעיניו...\u0003\"\u0004 (אסתר ה, ב), \u0003אמר ר' יוחנן: שלשה מלאכי השרת נזדמנו לה באותה שעה, אחד שהגביה את צוארה\u0004 שתעמוד ישר ולא תתבייש, וזה מרומז בפסוק \"נשאה חן\", \u0003ואחד שמשך חוט של חסד\u0004 ויופי \u0003עליה, ואחד שמתח את השרביט\u0004 של המלך,","\u0003וכמה\u0004 מתחו? \u0003אמר ר' ירמיה: שתי אמות היה\u0004 השרביט \u0003והעמידו על שתים עשרה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהעמידו \u0003על שש עשרה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003על עשרים וארבע. במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 העמידו \u0003על ששים\u0004 אמה, \u0003וכן אתה מוצא\u0004 שירבוב כזה \u0003באמתה\u0004 (ידה) \u0003של בת פרעה\u0004 ששלחה את ידה לקחת את משה, \u0003וכן אתה מוצא בשיני רשעים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שני רשעים שברת\"\u0004 (תהלים ג, ח), \u0003ואמר ריש לקיש: אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שברת\" אלא \"שריבבת\"\u0004 (ראה ברכות נד,ב). \u0003רבה בר עופרן אמר משום ר' אלעזר ששמע מרבו ורבו מרבו:\u0004 השתרבב השרביט \u0003מאתים\u0004 אמה.","נאמר: \u0003\"ויאמר לה המלך (לאסתר המלכה) מה בקשתך... עד חצי המלכות ותעש\"\u0004 (אסתר ה, ג-ו) ומעירים: רק \u0003חצי המלכות, ולא כל המלכות?!\u0004 מדוע אמר לה בלשון זו? אלא הכוונה \u0003ולא דבר שחוצץ למלכות,\u0004 שיש דבר שהמלכות בשום אופן לא תסכים \u0003ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 — \u0003בנין בית המקדש,\u0004 שבדבר זה לא ימלא בקשתה.","נאמר שבקשה אסתר: \u0003\"יבא המלך והמן\u0004 היום \u0003אל המשתה\"\u0004 (אסתר ה, ד). \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מה ראתה אסתר שזימנה את המן\u0004 אל המשתה? \u0003ר' אליעזר אומר: פחים טמנה לו, שנאמר: \"יהי שלחנם לפניהם לפח\"\u0004 (תהלים סט, כג) וסמכה על כך שתוכל להכשיל את המן במשתה.","\u0003ר' יהושע אומר: מבית אביה למדה\u0004 לעשות כן, ששמעה בביתה שמזכירים את מה \u0003שנאמר: \"אם רעב שנאך האכילהו לחם\"\u0004 (משלי כה, כא). \u0003ר' מאיר אומר:\u0004 זימנה אותו \u0003כדי\u0004 שיהיה כל הזמן סמוך לה \u0003שלא יטול עצה וימרוד\u0004 במשך הזמן, כשיראה שאחשורוש כועס עליו.","\u0003ר' יהודה אומר:\u0004 זימנה את המן \u0003כדי שלא יכירו בה שהיא יהודית,\u0004 שאם היא מרחקת אותו היה המן חושד בה. \u0003ר' נחמיה אומר: כדי שלא יאמרו ישראל: אחות יש לנו בבית המלך, ויסיחו דעתן מן\u0004 בקשת \u0003הרחמים\u0004 מה'. \u0003ר' יוסי אומר:\u0004 עשתה זאת \u0003כדי שיהא מצוי לה בכל עת,\u0004 שאולי בתוך כך תהא לה הזדמנות להכשילו באיזשהו דבר לפני המלך. \u0003ר' שמעון בן מנסיא אומר: אולי ירגיש המקום\u0004 (הקדוש ברוך הוא) שהכל תומכים בהמן ואין איש עוזר לישראל \u0003ויעשה לנו נס.\u0004","\u0003ר' יהושע בן קרחה אומר:\u0004 נתכוונה כך — \u0003אסביר לו פנים\u0004 כדי שיחשוד בנו המלך שאנחנו מיודדים \u0003כדי שיהרג הוא והיא\u0004 יחד, ואולי בשל מות המן תתבטל הגזירה. \u0003רבן גמליאל אומר: מלך הפכפכן היה\u0004 וקיותה אסתר שאם יראה אחשורוש את המן פעמים רבות סופו שישנה דעתו עליו. \u0003אמר רבן גמליאל: עדיין צריכים אנו למודעי,\u0004 לדבריו של ר' אלעזר המודעי, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר המודעי אומר: קנאתו במלך קנאתו בשרים,\u0004 כלומר, גרמה שיתקנאו בו המלך והשרים, ובכך תביא למפלתו.","\u0003רבה אמר:\u0004 הסיבה שבגללה הזמינה את המן לסעודה היתה, שרצתה לקיים מה שנאמר: \u0003\"לפני שבר גאון\"\u0004 (משלי טז, יח), שלפני שבירת הרשעים, יש להביאם לידי גאוה. \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 עשתה כן כדי לקיים את דברי הכתוב: \u0003\"בחמם אשית את משתיהם\u0004 והשכרתים למען יעלוזו וישנו שנת עולם\u0003\"\u0004 (ירמיה נא, לט). מסופר: \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רבה בר אבוה לאליהו\u0004 הנביא ושאל: \u0003כמאן חזיא\u0004 \u0005[כמי,\u0006 כדעת מי \u0005ראתה]\u0006 \u0003אסתר ועבדא הכי\u0004 \u0005[ועשתה כך]?\u0006 מה היה טעמה באמת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ככולהו תנאי וככולהו אמוראי\u0004 \u0005[כ\u0006דעת \u0005כל התנאים וכ\u0006דעת \u0005כל האמוראים],\u0006 כלומר, שחשבה אסתר על כל הנימוקים שאמרנו.","נאמר: \u0003\"ויספר להם המן את כבוד עשרו ורב בניו\"\u0004 (אסתר ה, יא) ושואלים: \u0003וכמה\u0004 הם \u0003רב בניו? אמר רב: שלשים\u0004 היו, \u0003עשרה\u0004 מהם \u0003מתו, ועשרה נתלו\u0004 כמפורש במגילה, \u0003ועשרה\u0004 נותרו בחיים והם \u0003מחזרין על הפתחין.\u0004","\u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]:\u0006 \u0003אותן שמחזרין על הפתחין שבעים הויא\u0004 \u0005[היו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שבעים בלחם נשכרו\"\u0004 (שמואל א' ב, ה), \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"שבעים\" אלא \"שבעים\".\u0004","\u0003ורמי בר אבא אמר: כולן\u0004 כל בניו \u0003מאתים ושמונה הוו\u0004 \u0005[היו],\u0006 \u0003שנאמר: \"ורוב בניו\",\u0004 והוא מאתים ושמונה לפי חשבון גימטריה. ושואלים: \u0003\"ורוב\" בגימטריא מאתן וארביסר הוו\u0004 \u0005[מאתים וארבעה עשר הם]!\u0006 \u0003אמר רב נחמן בר יצחק: \"ורב\" כתיב\u0004 \u0005[נאמר]\u0006 חסר, וזהו בדיוק מאתים ושמונה.","\u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"בלילה ההוא נדדה שנת המלך\"\u0004 (אסתר ו, א), \u0003אמר ר' תנחום: נדדה שנת מלכו של עולם\u0004 הקדוש ברוך הוא. \u0003ורבנן אמרי: נדדו עליונים, נדדו תחתונים,\u0004 כלומר, גם שינה של מלך עולם וגם שינה של המלך אחשורוש. \u0003רבא אמר: שנת המלך אחשורוש ממש,\u0004","והסיבה לכך היתה זו: \u0003נפלה ליה מילתא בדעתיה\u0004 \u0005[נפל לו דבר בדעתו]\u0006 ו\u0003אמר: מאי דקמן דזמינתיה\u0004 \u0005[מה הוא זה שלפנינו שהזמינה]\u0006 \u0003אסתר להמן? דלמא\u0004 \u0005[שמא]\u0006 \u0003עצה קא שקלי עילויה דההוא גברא למקטליה\u0004 \u0005[הם מטכסים על אותו אדם,\u0006 עלי, \u0005להרוג אותו].\u0006 \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 לעצמו: \u0003אי הכי\u0004 \u0005[אם\u0006 אכן היה \u0005כך]\u0006 האם \u0003לא הוה גברא דרחים לי\u0004 \u0005[היה אדם שאוהב אותי]\u0006 \u0003דהוה מודע לי\u0004 \u0005[שהיה מודיע לי]\u0006 שיש קנוניה כזאת? \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 לעצמו: \u0003דלמא איכא איניש דעבד בי טיבותא ולא פרעתיה, משום הכי מימנעי אינשי ולא מגלו לי\u0004 \u0005[שמא יש אדם שעשה לי טובה ולא פרעתי לו\u0006 כגמולו, \u0005ומשום כך נמנעים אנשים ואינם מגלים לי]\u0006 סוד, לפי שיודעים הם שאין להם רווח בדבר, \u0003מיד — \"ויאמר להביא את ספר הזכרנות דברי הימים\"\u0004 (אסתר ו, א).","נאמר: \u0003\"ויהיו נקראים\u0004 לפני המלך\u0003\"\u0004 (אסתר ו, א), ומסבירים: \u0003מלמד ש\u0004היו \u0003נקראים מאיליהן.\u0004 נאמר בהמשך: \u0003\"וימצא כתוב\"\u0004 (אסתר ו, ב) ושואלים: \u0003\"כתב\" מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, ומדוע נאמר בלשון הווה? ומסבירים: \u0003מלמד\u0004"],["\u0003ששמשי\u0004 סופר המלך שהיה שונא ישראל (ראה עזרא ד, יז) \u0003מוחק ו\u0004המלאך \u0003גבריאל כותב.\u0004 ונמצא שהיה הדבר כתוב אכן בהווה. \u0003אמר ר' אסי, דרש ר' שילא איש כפר תמרתא\u0004 בעניין זה: \u0003ומה כתב שלמטה\u0004 שנכתב בספר בעולם הזה \u0003ש\u0004הוא \u0003לזכותן של ישראל — אינו נמחק, כתב שלמעלה לא כל שכן\u0004 שאינו נמחק.","נאמר שם שאמרו לאחשורוש: \u0003\"לא נעשה עמו דבר\"\u0004 (אסתר ו, ג), \u0003אמר רבא: לא מפני ש\u0004היו \u0003אוהבים את מרדכי\u0004 אמרו כן, \u0003אלא מפני ששונאים\u0004 היו \u0003את המן.\u0004","נאמר: \u0003\"\u0004על העץ אשר \u0003הכין לו\"\u0004 (אסתר ו, ד), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 כוונת הכתוב לומר ש\u0003לו\u0004 לעצמו \u0003הכין.\u0004","נאמר, שאמר המלך: \"ועשה כן למרדכי היהודי היושב בשער המלך\" (אסתר ו, י), ומפרשים, כשאמר לו \u0003\"ועשה כן למרדכי\", אמר ליה\u0004 \u0005[לו]\u0006 המן שרצה להתחמק: \u0003מנו\u0004 \u0005[מי הוא]\u0006 \u0003מרדכי? אמר ליה\u0004 \u0005[לו]\u0006 אחשורוש להמן: \u0003\"היהודי\". אמר ליה\u0004 \u0005[לו]\u0006 המן: \u0003טובא\u0004 \u0005[הרבה]\u0006 \u0003מרדכי איכא ביהודאי\u0004 \u0005[יש\u0006 בין \u0005היהודים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחשורוש: כוונתי לזה \u0003\"היושב בשער המלך\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 המן: מדוע להעניק לו כבוד גדול כזה? \u0003סגי ליה בחד דיסקרתא, אי נמי בחד נהרא\u0004 \u0005[די לו\u0006 אם תיתן לו \u0005כפר אחד\u0006 לאחוזה, \u0005או גם כן נהר אחד]\u0006 לגבות ממנו מכס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחשורוש: \u0003הא נמי הב ליה\u0004 \u0005[זה גם כן תן לו],\u0006 \u0003\"אל תפל דבר מכל אשר דברת\"\u0004 אתה עצמך, וכמו כן עשה גם מה שאמרתי לך אני.","\u0003\"ויקח המן את הלבוש ואת הסוס\"\u0004 (אסתר ו, יא), \u0003אזל אשכחיה דיתבי רבנן קמיה ומחוי להו\u0004 \u0005[הלך ומצא אותו,\u0006 את מרדכי \u0005שיושבים חכמים לפניו ו\u0006היה \u0005מראה להם,\u0006 מלמד\u0005]\u0006 \u0003הלכות קמיצה לרבנן\u0004 \u0005[לחכמים],\u0006 \u0003כיון דחזייה\u0004 \u0005[שראה אותו]\u0006 \u0003מרדכי דאפיק לקבליה וסוסיה מיחד בידיה\u0004 \u0005[ש\u0006הוא \u0005יוצא למולו וסוסו אחוז בידו],\u0006 \u0003מירתת\u0004 \u0005[פחד]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 מרדכי \u0003לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003האי רשיעא למיקטל נפשי קא אתי זילו מקמיה די\u0004 \u0005[רשע זה, להרוג את נפשי הוא בא, לכו ממנו כדי]\u0006 ש\u0003לא תכוו בגחלתו,\u0004 שלא תינזקו גם אתם. \u0003בההיא שעתא\u0004 \u0005[באותה שעה]\u0006 \u0003נתעטף מרדכי\u0004 בטליתו \u0003וקם ליה לצלותא\u0004 \u0005[ונעמד לו לתפילה],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003המן\u0004 למקום \u0003ויתיב ליה קמייהו ואוריך עד דסליק מרדכי לצלותיה\u0004 \u0005[וישב לפניהם והמתין עד שסיים מרדכי את תפילתו],\u0006","ובינתיים \u0003אמר להו\u0004 \u0005[להם]\u0006 המן לחכמים \u0003במאי עסקיתו\u0004 \u0005[במה אתם עוסקים]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003בזמן שבית המקדש\u0004 היה \u0003קיים מאן\u0004 \u0005[מי]\u0006 שהיה \u0003מנדב מנחה, מייתי מלי קומציה דסולתא\u0004 \u0005[\u0006היה \u0005מביא מלוא קומצו סולת]\u0006 \u0003ומתכפר ליה\u0004 \u0005[לו].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אתא מלי קומצי קמחא דידכו ודחי עשרה אלפי ככרי כספא דידי\u0004 \u0005[בא מלוא קומץ קמח שלכם ודחה את עשרת אלפים ככרי כסף שלי],\u0006 וכשסיים מרדכי את תפילתו \u0003אמר ליה\u0004 \u0005[לו]\u0006 להמן: \u0003רשע, עבד שקנה נכסים,\u0004 ה\u0003עבד למי\u0004 שייך \u0003ונכסים למי\u0004 שייכים? הלא אני קניתי אותך כעבד, ואיזה כסף הוא שלך?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 המן למרדכי: \u0003קום\u0004 \u0005[עמוד]\u0006 \u0003לבוש הני מאני\u0004 \u0005[בגדים אלה]\u0006 \u0003ורכוב האי סוסיא, דבעי לך מלכא\u0004 \u0005[ורכב על הסוס הזה, שהמלך רוצה אותך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא יכילנא עד דעיילנא לבי בני ואשקול למזייא, דלאו אורח ארעא לאשתמושי במאני דמלכא הכי\u0004 \u0005[אין אני יכול\u0006 לעשות זאת \u0005עד שאכנס לבית המרחץ ואספר את שערותי, שאין זו דרך ארץ להשתמש בבגדי המלך כך]\u0006 כמו שאני עכשיו.","בינתיים \u0003שדרה\u0004 \u0005[שלחה]\u0006 \u0003אסתר\u0004 שליחים \u0003ואסרתינהו לכולהו בי בני ולכולהו אומני\u0004 \u0005[וסגרה את כל בתי המרחץ ואת כל האומנים\u0006 מקיזי הדם והספרים\u0005],\u0006 וכיון שראה המן שאין מי שיעשה זאת, \u0003עייליה איהו לבי בני ואסחיה ואזיל ואייתי זוזא מביתיה וקא שקיל ביה מזייה\u0004 \u0005[הכניסו הוא,\u0006 המן, למרדכי \u0005לבית המרחץ ורחץ אותו והלך והביא מספרים מביתו וקצץ את שערותיו].\u0006 \u0003בהדי דקא שקיל ליה אינגד ואיתנח\u0004 \u0005[בזמן שגזז\u0006 את שערותיו \u0005נפגע, ונאנח]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מרדכי: \u0003אמאי קא מיתנחת\u0004 \u0005[מדוע אתה נאנח]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גברא דהוה חשיב ליה למלכא מכולהו רברבנוהי, השתא לישוייה בלאני\u0004 \u0005[אדם שהיה חשוב למלך\u0006 יותר \u0005מכל שריו, עכשיו יעשו אותו בלן]\u0006 \u0003וספר? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רשע, ולאו\u0004 \u0005[והאם לא]\u0006 \u0003ספר של כפר קרצום היית\u0004 בנעוריך ואם כן מדוע אתה נאנח? הלא חזרת לימי נעוריך ולמלאכתך הקודמת. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003המן, ספר של כפר קרצום היה, עשרים ושתים שנה.\u0004","\u0003בתר דשקלינהו למזייה, לבשינהו למאניה\u0004 \u0005[אחרי שנטל את שערותיו, לבש\u0006 מרדכי \u0005את בגדיו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המן: \u0003סק\u0004 \u0005[עלה]\u0006 \u0003ורכב. אמר ליה\u0004 \u0005[לו]\u0006 מרדכי: \u0003לא יכילנא, דכחישא חילאי מימי תעניתא\u0004 \u0005[אין אני יכול, שכחש כוחי מימי התענית\u0006 שהתעניתי\u0005]\u0006, \u0003גחין וסליק\u0004 \u0005[גחן\u0006 המן לפניו \u0005ועלה]\u0006 עליו מרדכי. \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003בעט ביה\u0004 \u0005[בו]\u0006 מרדכי בהמן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 המן: האם \u0003לא כתיב לכו\u0004 \u0005[נאמר לכם,\u0006 אצלכם\u0005]:\u0006 \u0003\"בנפל אויבך אל תשמח\"\u0004 (משלי כד, יז)? \u0003אמר ליה\u0004 \u0005[לו]\u0006 מרדכי: אכן נאמר, ואולם \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בישראל, אבל בדידכו כתיב\u0004 \u0005[בכם נאמר]:\u0006 \u0003\"ואתה על במותימו תדרך\"\u0004 (דברים לג, כט).","\u0003\"ויקרא לפניו: ככה יעשה לאיש אשר המלך חפץ ביקרו\"\u0004 (אסתר ו, יא), \u0003כי הוה נקיט ואזיל בשבילא דבי\u0004 \u0005[כאשר היה מושך והולך בשביל\u0006 ליד \u0005ביתו]\u0006 של \u0003המן, חזיתיה ברתיה דקיימא אאיגרא\u0004 \u0005[ראתה אותו בתו\u0006 של המן \u0005שהיתה עומדת על הגג],\u0006 \u0003סברה\u0004 \u0005[חשבה\u0006 בלבה\u0005]\u0006 כי \u0003האי דרכיב\u0004 \u0005[זה שרוכב]\u0006 על הסוס — \u0003אבוה\u0004 \u0005[אביה]\u0006 הוא, \u0003והאי דמסגי קמיה\u0004 \u0005[וזה שהולך לפניו]\u0006 — \u0003מרדכי\u0004 הוא, \u0003שקלה עציצא\u0004 \u0005[לקחה עביט]\u0006 מלא מ\u0003בית הכסא ושדיתיה ארישא דאבוה\u0004 \u0005[וזרקה אותו על ראשו של אביה]\u0006 שחשבה שהוא מרדכי. \u0003דלי עיניה וחזת דאבוה\u0004 \u0005[הרים\u0006 המן את \u0005עיניו וראתה שאביה]\u0006 \u0003הוא, נפלה\u0004 מחמת צער וכעס \u0003מאיגרא לארעא\u0004 \u0005[מהגג לארץ]\u0006 \u0003ומתה.\u0004","\u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"וישב מרדכי אל שער המלך\"\u0004 (אסתר ו, יב), \u0003אמר רב ששת: ששב\u0004 אל \u0003שקו ו\u0004אל \u0003תעניתו,\u0004 להתענות על צרת ישראל, \u0003\"והמן נדחף אל ביתו אבל וחפוי ראש\"\u0004 (אסתר ו, יב), \u0003\"אבל\" — על בתו\u0004 שמתה, \u0003\"וחפוי ראש\" — על שאירע לו\u0004 שנמלא ראשו לכלוך.","נאמר: \u0003\"ויספר המן לזרש אשתו ולכל אהביו\"\u0004 (אסתר ו, יג), ומעירים: \u0003קרי ליה\u0004 \u0005[קורא להם]\u0006 \u0003\"אהביו\", וקרי להו\u0004 \u0005[וקורא להם]\u0006 בהמשך הפסוק \u0003\"חכמיו\". אמר ר' יוחנן: כל האומר דבר חכמה אפילו\u0004 הוא \u0003באומות העולם — נקרא חכם.\u0004 ואיזה דבר חכמה אמרו לו?","\u0003\"אם מזרע היהודים מרדכי\"\u0004 (אסתר ו, יג), \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משאר שבטים קאתי\u0004 \u0005[הוא בא],\u0006 \u0003יכלת ליה\u0004 \u0005[תוכל לו\u0006 עדיין\u0005]\u0006, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משבט יהודה ובנימין ואפרים ומנשה\u0004 הוא בא — \u0003לא יכלת ליה\u0004 \u0005[תוכל לו]\u0006 עוד. וראיה לדבר: \u0003יהודה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בו: \u0003\"ידך בערף איביך\"\u0004 (בראשית מט, ח), שהוא מנצח והולך את \u0003אינך דכתיב בהו\u0004 \u0005[האחרים\u0006 שמנינו \u0005שנאמר בהם]:\u0006 \u0003\"לפני אפרים ובנימן ומנשה עוררה את גבורתך\"\u0004 (תהלים פ, ג).","נאמר: \u0003\"כי נפול תפול לפניו\"\u0004 (אסתר ו, יג), \u0003דרש ר' יהודה בר אלעאי: שתי נפילות הללו,\u0004 \"נפול\" ו\"תפול\" \u0003למה? אמרו לו\u0004 להמן חכמיו: \u0003אומה זו,\u0004 ישראל, \u0003משולה\u0004 בכתובים \u0003לעפר ומשולה לכוכבים,\u0004 ללמד: \u0003כשהן יורדין\u0004 — \u0003יורדין עד עפר, וכשהן עולין\u0004 — \u0003עולין עד לכוכבים,\u0004 ולכן כשמרדכי בעליה לא תוכל לו עוד.","נאמר עוד: \u0003\"וסריסי המלך הגיעו ויבהלו\u0004 להביא את המן\u0003\"\u0004 (אסתר ו, יד) — \u0003מלמד שהביאוהו בבהלה\u0004 ולא הספיק לרחוץ עצמו מטינופו.","במשתה אמרה אסתר לאחשורוש: \u0003\"כי נמכרנו אני ועמי\u0004 להשמיד להרוג ולאבד ואילו לעבדים ולשפחות נמכרנו החרשתי \u0003כי אין הצר שוה בנזק המלך\"\u0004 (אסתר ז, ד). \u0003אמרה לו: צר\u0004 (אויב) \u0003זה, אינו שוה\u0004 (חושב ודואג) \u0003בנזק של\u0004 ה\u0003מלך\u0004 שהוא גורם לו תמיד. ראשית \u0003איקני\u0004 \u0005[קינא]\u0006 \u0003בה בושתי וקטלה\u0004 \u0005[והרג אותה]\u0006 וכפי שכבר הוסבר שממוכן זה המן, \u0003השתא איקני בדידי ומבעי למקטלי\u0004 \u0005[עכשיו הוא מקנא בי ורוצה להרוג אותי].\u0006","נאמר: \u0003\"ויאמר המלך אחשורוש ויאמר לאסתר המלכה\"\u0004 (אסתר ז, ב), ושואלים: \u0003\"ויאמר\" \"ויאמר\"\u0004 פעמיים \u0003למה לי? אמר ר' אבהו: בתחלה\u0004 דיבר איתה \u0003על ידי תורגמן,\u0004 כיון שנחשבה בעיניו לאשה פשוטה מן ההדיוטות, \u0003כיון\u0004 ש\u0003אמרה ליה\u0004 \u0005[לו]\u0006 ש\u0003מבית שאול קאתינא\u0004 \u0005[אני באה],\u0006 \u0003מיד: \"ויאמר לאסתר המלכה\"\u0004 בעצמו, שאם היא מזרע מלוכה, הריהי אשה הראויה למעמדו.","בהמשך נאמר: \u0003\"ותאמר אסתר איש צר ואויב המן הרע הזה\"\u0004 (אסתר ז, ו), \u0003אמר ר' אלעזר: מלמד שהיתה מחווה\u0004 (מראה) \u0003כלפי אחשורוש\u0004 שהוא איש צר ואויב \u0003ובא מלאך וסטר ידה כלפי המן.\u0004","נאמר: \u0003\"והמלך קם בחמתו\u0004 ממשתה היין אל גינת הביתן\u0003\"\u0004 (אסתר ז, ז), ומיד לאחר מכן נאמר: \u0003\"והמלך שב מגנת הביתן\"\u0004 (אסתר ז, ח), ומעירים: \u0003מקיש\u0004 (משווה) הכתוב \u0003שיבה לקימה, מה קימה —\u0004 היתה \u0003בחימה, אף שיבה\u0004 היתה \u0003בחימה.\u0004 ומדוע שב בחימה — \u0003דאזל ואשכח\u0004 \u0005[שהלך ומצא]\u0006 את \u0003מלאכי השרת דאידמו ליה כגברי, וקא עקרי לאילני דבוסתני\u0004 \u0005[שנידמו לו כאנשים והם עוקרים את אילנות הגן],\u0006 \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי עובדייכו\u0004 \u0005[מה מעשיכם]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003דפקדינן\u0004 \u0005[שפקד עלינו]\u0006 \u0003המן\u0004 לעשות זאת,","וכיון ש\u0003אתא לביתיה\u0004 \u0005[\u0006ש\u0005נכנס לביתו]\u0006 ראה \u0003\"והמן נפל על המטה\"\u0004 (אסתר ז, ח). ושואלים: מדוע אמר \u0003\"נפל\"\u0004 שפירושו נופל עכשיו — \u0003\"נפל\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! \u0003אמר ר' אלעזר: מלמד שבא מלאך והפילו עליה,\u0004 והיה נופל והולך בכל פעם למרות שרצה לקום. \u0003אמר\u0004 אחשורוש: \u0003ויי מביתא ויי מברא\u0004 \u0005[אוי\u0006 לי \u0005מן הבית ואוי\u0006 לי \u0005מבחוץ].\u0006 \u0003\"ויאמר המלך: הגם לכבוש את המלכה עמי בבית\"\u0004 (אסתר ז, ח)","\u0003\"ויאמר חרבונה\u0004 אחד מן הסריסים לפני המלך גם הנה העץ אשר עשה המן למרדכי אשר דיבר טוב על המלך עומד בבית המן גבוה חמישים אמה\u0003\"\u0004 (אסתר ז, ט), \u0003אמר ר' אלעזר: אף חרבונה\u0004 ה\u0003רשע באותה עצה היה,\u0004 שרצה גם הוא שיהרגו את מרדכי, \u0003כיון שראה שלא נתקיימה עצתו, מיד ברח\u0004 והצטרף למחנה מרדכי, \u0003והיינו דכתיב\u0004 \u0005[והוא שנאמר]:\u0006 \u0003\"וישלך עליו ולא יחמל מידו ברוח יברח\"\u0004 (איוב כז, כב), כלומר, כשה' משליך פורענות על הרשע מיד בורחים ממנו חבריו.","נאמר: \u0003\"וחמת המלך שככה\",\u0004 ושואלים: \u0003שתי שכיכות הללו\u0004 (\"שככה\" ולא \"שכה\") \u0003למה? אחת — של מלכו־של־עולם, ואחת — של אחשורוש, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שחמתו בערה בו בשל שתי סיבות: \u0003אחת של אסתר ואחת של ושתי\u0004 ועכשיו שככו שתיהן. ולגבי המשך הכתובים מקדימים מדרש אחר.","נאמר ביוסף: \u0003\"לכלם נתן לאיש חלפות שמלת ולבנימן נתן\u0004 שלוש מאות כסף ו\u0003חמש חלפת\u0004 שמלות\u0003\"\u0004 (בראשית מה, כב) ויש לשאול: \u0003אפשר דבר שנצטער בו אותו צדיק,\u0004 יוסף, שדבר זה עצמו שאביו הבדיל אותו לטובה משאר הבנים, גרם שישנאו אותו אחיו של יוסף —"],["\u0003יכשל בו\u0004 הוא עצמו? וכפי ש\u0003אמר רבא בר מחסיא אמר רב חמא בר גוריא, אמר רב: בשביל משקל שני סלעים\u0004 של \u0003מילת שהוסיף יעקב ליוסף\u0004 יותר \u0003משאר אחיו\u0004 שעשה לו כתונת פסים \u0003נתגלגל הדבר וירדו אבותינו למצרים.\u0004 וכיצד עשה יוסף מעשה־העדפה כזה לגבי בנימין? \u0003אמר ר' בנימין בר יפת: רמז רמז לו\u0004 על ידי כך, \u0003שעתיד בן לצאת ממנו, שיצא מלפני המלך בחמשה לבושי מלכות, שנאמר: \"ומרדכי יצא\u0004 מלפני המלך \u0003בלבוש מלכות, תכלת,\u0004 וחור, ועטרת זהב גדולה, ותכריך בוץ וארגמן\u0003\"\u0004 (אסתר ח, טו).","ועוד מפרשים במעשה יוסף ואחיו, נאמר ביוסף: \u0003\"ויפל על צוארי בנימן אחיו\u0004 ויבך\u0003\"\u0004 (בראשית מה, יד), ותוהים על הלשון: \u0003כמה צוארין הוו ליה\u0004 \u0005[היו לו]\u0006 \u0003לבנימין?\u0004 מדוע לא נאמר \"על צוארו\"? \u0003אמר ר' אלעזר\u0004 רמז הוא; כי \u0003בכה על שני מקדשים\u0004 (מקדש ראשון ומקדש שני) \u0003שעתידין להיות בחלקו של בנימין ועתידין ליחרב, \"ובנימן בכה על צואריו\"\u0004 (בראשית מה, יד) — \u0003בכה על משכן שילה, שעתיד להיות בחלקו של יוסף ועתיד ליחרב.\u0004","נאמר שם: \u0003\"והנה עיניכם ראות ועיני אחי בנימין\"\u0004 (בראשית מה, יב), \u0003אמר ר' אלעזר:\u0004 פירושו, שכך \u0003אמר להם: כשם\u0004 שודאי \u0003שאין בלבי על בנימין אחי, ש\u0004הרי \u0003לא היה במכירתי — כך אין בלבי עליכם.\u0004 נאמר: \u0003\"כי פי המדבר אליכם\"\u0004 (בראשית מה, יב), כלומר: \u0003כפי\u0004 — \u0003כן לבי.\u0004","נאמר: \u0003\"ולאביו שלח כזאת עשרה חמרים נשאים מטוב מצרים\"\u0004 (בראשית מה, כג), ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"מטוב מצרים\"\u0004 שלא נתפרש? \u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: שלח לו יין ישן, שדעת זקנים נוחה הימנו.\u0004","לאחר מות יעקב נאמר: \u0003\"וילכו גם אחיו ויפלו לפניו\"\u0004 (בראשית נ, יח), \u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: היינו דאמרי אינשי\u0004 \u0005[הוא שאומרים אנשים]\u0006 בפיתגם עממי: \u0003תעלא בעידניה סגיד ליה\u0004 \u0005[שועל, בזמנו, השתחווה לו],\u0006 שאם מגיע זמן שהשועל נעשה מלך, צריך להשתחוות בפניו ולהיכנע לו.","ותוהים על הקשר בין המשל והנמשל: \u0003תעלא\u0004 \u0005[שועל]\u0006 אתה קורא לו ליוסף? \u0003מאי בצירותיה מאחווה\u0004 \u0005[מה פחיתותו מאחיו]\u0006 שאתה קורא אותו שועל לגביהם? \u0003אלא, אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר],\u0006 לא על פסוק זה אלא על פסוק אחר, שנאמר: \u0003\"וישתחו ישראל על ראש המטה\"\u0004 (בראשית מז, לא), ועל כך \u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: תעלא בעידניה סגיד ליה\u0004 \u0005[שועל, בזמנו השתחווה לו].\u0006 שהוצרך האב להשתחוות לבנו שעלה לגדולה.","נאמר ביוסף \u0003\"וינחם אותם וידבר על לבם\"\u0004 (בראשית נ, כא), \u0003אמר ר' בנימין בר יפת אמר ר' אלעזר: מלמד שאמר להם דברים שמתקבלים על הלב,\u0004 וכך אמר: \u0003ומה עשרה נרות לא יכלו לכבות נר אחד\u0004 שאתם כולכם לא יכולתם לעשות לי דבר, \u0003נר אחד היאך יכול לכבות עשרה נרות?\u0004","ושוב לפירוש המגילה: \u0003\"ליהודים היתה אורה ושמחה וששן ויקר\"\u0004 (אסתר ח, טז), \u0003אמר רב יהודה: \"אורה\" — זו תורה,\u0004 שחזרו לעסוק בתורה. \u0003וכן הוא אומר: \"כי נר מצוה ותורה אור\"\u0004 (משלי ו, כג). \u0003\"שמחה\" — זה יום טוב,\u0004 שחזרו לקיים ימים טובים. \u0003וכן הוא אומר: \"ושמחת בחגך\"\u0004 (דברים טז, יד). \u0003\"ששן\" — זו מילה,\u0004 שחזרו למול את בניהם. \u0003וכן הוא אומר: \"שש אנכי על אמרתך\"\u0004 (תהלים קיט, קסב), שדרשו חכמים ששמח דוד על מצות מילה.","\u0003\"ויקר\"\u0004 (=כבוד) — \u0003אלו תפלין, וכן הוא אומר: \"וראו כל עמי הארץ כי שם ה' נקרא עליך ויראו ממך\"\u0004 (דברים כח, י) \u0003ותניא, ר' אליעזר הגדול אומר: אלו תפלין שבראש,\u0004 שעל מצוות אלה גזר המן שלא יקיימום וחזרו לקיימם לאחר נס פורים.","נאמר: \u0003\"ואת פרשנדתא... עשרת בני המן\"\u0004 (אסתר ט, ז-י) \u0003אמר רב אדא דמן יפו\u0004 (מיפו): את שמות \u0003עשרת בני המן, ו\u0004גם את המלה \u0003\"עשרת\" צריך למימרינהו\u0004 \u0005[צריך לומר אותם]\u0006 בזמן שקוראים את המגילה \u0003בנשימה אחת, מאי טעמא\u0004 \u0005[מה טעם]?\u0006 — \u0003כולהו בהדי הדדי נפקו נשמתייהו\u0004 \u0005[\u0006ש\u0005כולם בבת אחת יצאה נשמתם].\u0006 \u0003אמר ר' יוחנן:\u0004 ה\u0003וי\"ו\u0004 של \u0003\"ויזתא\"\u0004 היא וי\"ו ארוכה ו\u0003צריך למימתחא בזקיפא כמורדיא דלברות\u0004 \u0005[למתוח אותה בעמידה כמו תורן של ספינה].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003כולהו בחד זקיפא אזדקיפו\u0004 \u0005[כולם בעמוד אחד ניתלו].\u0006","\u0003אמר ר' חנינא בר פפא, דרש רב שילא איש כפר תמרתא: כל השירות כולן\u0004 שבמקרא \u0003נכתבות\u0004 בצורת \u0003אריח על גבי לבינה ולבינה על גבי אריח\u0004 כלומר שתי שורות קצרות וביניהן רווח, ומתחת לרווח — שורה ארוכה,","\u0003חוץ משירה זו\u0004 של רשימת בני המן \u0003ו\u0004כן רשימת \u0003מלכי כנען\u0004 שנפלו בידי יהושע, שכותבים אותה \u0003אריח על גבי אריח ולבינה על גבי לבינה,\u0004 שורה קצרה תחת שורה קצרה וארוכה תחת ארוכה. \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003שלא תהא תקומה למפלתן\u0004 שכשם שקיר שבונים אותו בצורה כזאת לא יעמוד — כך אלה לא תהיה להם עוד תקומה.","\u0003\"ויאמר המלך לאסתר המלכה בשושן הבירה הרגו היהודים\u0004 ואבד חמש מאות איש ואת עשרת בני המן בשאר מדינות המלך מה עשו ומה שאלתך וינתן לך\u0003\"\u0004 (אסתר ט, יב), \u0003אמר ר' אבהו: מלמד שבא מלאך וסטרו על פיו\u0004 ולא גמר את תחילת דבריו, שנראה שרצה להתלונן על מעשה היהודים, וסיים בדברים אחרים.","נאמר: \u0003\"ובבאה לפני המלך אמר עם הספר\"\u0004 (אסתר ט, כה), ותוהים: מדוע נאמר לשון \u0003\"אמר\"?\u0004 הלא \u0003\"אמרה\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]\u0006 שאסתר היא ששינתה את הגזירה! \u0003אמר ר' יוחנן: אמרה לו\u0004 לאחשורוש: \u0003יאמר בפה\u0004 גם בפקודה שבעל פה \u0003מה שכתוב בספר.\u0004","על מה שנאמר: \u0003\"דברי שלום ואמת\"\u0004 (אסתר ט, ל), \u0003אמר ר' תנחום, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אסי: מלמד שצריכה\u0004 המגילה \u0003שרטוט\u0004 שישרטטו שורות על הקלף \u0003כאמיתה של תורה,\u0004 כפי שעושים בספרי תורה.","נאמר: \u0003\"\u0004...דברי הצומות וזעקתם. \u0003ומאמר אסתר קים\"\u0004 (אסתר ט, לא-לב), ותוהים: וכי \u0003\"מאמר אסתר\" — אין\u0004 \u0005[כן],\u0006 \u0003\"דברי הצומות\" — לא?!\u0004 האם הצומות לא סייעו בנס? \u0003אמר ר' יוחנן: \"דברי הצומות... ומאמר אסתר קים את ימי הפרים האלה\".\u0004 וצריך להבין את שני הפסוקים כענין אחד.","נאמר \u0003\"כי מרדכי היהודי משנה למלך אחשורוש וגדול ליהודים ורצוי לרב אחיו\"\u0004 (אסתר י, ג) ומעירים: \u0003\"לרוב אחיו\" — ולא לכל אחיו, מלמד שפירשו ממנו מקצת סנהדרין,\u0004 מפני שהתעסק בעיקר בצרכי ציבור ולא יכול לעסוק כל כך בתורה, וחשבו שטעות עשה בדבר, שהיה צריך להישאר בסנהדרין.","\u0003אמר רב יוסף: גדול תלמוד תורה יותר מהצלת נפשות, דמעיקרא\u0004 \u0005[שמתחילה]\u0006 \u0003חשיב ליה\u0004 \u0005[מנה אותו]\u0006 את \u0003מרדכי בתר\u0004 \u0005[אחר]\u0006 \u0003ארבעה, ולבסוף בתר\u0004 \u0005[אחר]\u0006 \u0003חמשה. מעיקרא כתיב\u0004 \u0005[בתחילה נאמר]\u0006 כך: \u0003\"אשר באו עם זרבבל, ישוע, נחמיה, שריה, רעליה, מרדכי, בלשן\"\u0004 (עזרא ב, ב) \u0003ולבסוף\u0004 ברשימה מאוחרת יותר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"הבאים עם זרבבל, ישוע, נחמיה, עזריה, רעמיה, נחמני, מרדכי, בלשן\"\u0004 (נחמיה ז, ז) שכתבוהו מאוחר יותר ברשימה מפני שלא עסק בתורה אלא בעיקר בענייני השלטון.","\u0003אמר רב ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב שמואל בר מרתא: גדול תלמוד תורה\u0004 וחשוב \u0003יותר מבנין בית המקדש,\u0004 וראיה לדבר: \u0003שכל זמן שברוך בן נריה\u0004 היה \u0003קיים\u0004 ויושב בבבל \u0003לא הניחו עזרא\u0004 שהיה תלמידו \u0003ועלה\u0004 מבבל.","\u0003אמר רבה אמר רב יצחק בר שמואל בר מרתא: גדול תלמוד תורה יותר מכבוד אב ואם,\u0004 וראיה לדבר: \u0003שכל אותן שנים שהיה יעקב אבינו בבית עבר\u0004 ולמד שם תורה \u0003לא נענש\u0004 על שביטל מכיבוד אב ואם, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006"],["\u0003למה נמנו שנותיו של ישמעאל\u0004 שהיה רשע בתורה, ומה צורך לנו לדעת אותן? \u0003כדי ליחס בהן\u0004 ועל ידן את \u0003שנותיו של יעקב. דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואלה שני חיי ישמעאל מאת שנה ושלשים שנה ושבע שנים\"\u0004 (בראשית כה, יז). ועתה נבדוק: \u0003כמה קשיש\u0004 (זקן) \u0003ישמעאל מיצחק? ארביסר שנין\u0004 \u0005[ארבע עשרה שנים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואברם בן שמנים שנה ושש שנים בלדת הגר את ישמעאל לאברם\"\u0004 (בראשית טז, טז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואברהם בן מאת שנה בהולד לו את יצחק בנו\"\u0004 (בראשית כא, ה), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויצחק בן ששים שנה בלדת אתם\"\u0004 (בראשית כה, כו), ולפי זה \u0003בר\u0004 \u0005[בן]\u0006 \u0003כמה הוה\u0004 \u0005[היה]\u0006 \u0003ישמעאל כדאתיליד\u0004 \u0005[כשנולד]\u0006 \u0003יעקב? בר\u0004 \u0005[בן]\u0006 \u0003שבעים וארבעה, כמה פיישן משניה\u0004 \u0005[כמה נותרו\u0006 עוד \u0005משנותיו]\u0006 עד מותו — \u0003שתין ותלת\u0004 \u0005[שישים ושלוש],\u0006 שהרי היה ישמעאל במותו בן מאה שלושים ושבע שנים (ראה בראשית כה, יז)\u0005.\u0006","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה יעקב אבינו בשעה שנתברך מאביו בן ששים ושלש שנה,\u0004 שהרי \u0003ובו בפרק\u0004 (באותו זמן) \u0003מת ישמעאל.\u0004 וכיצד אנו למדים שהיה זה באותו זמן? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירא עשו כי ברך וגו' וילך עשו אל ישמעאל ויקח את מחלת בת ישמעאל\u0004 בן אברהם \u0003אחות נביות\"\u0004 (בראשית כח, ו-ט), והרי \u0003ממשמע שנאמר \"בת ישמעאל\", איני יודע שהיא אחות נביות?\u0004 ומדוע אומר זאת הכתוב במפורש? \u0003מלמד שקידשה ישמעאל\u0004 לעשיו \u0003ו\u0004בינתיים \u0003מת, והשיאה נביות אחיה,\u0004 ולכן הוא מייחסה אף לנביות אחיה. ועל ידי כך אנו יודעים בן כמה היה יעקב כשיצא מבית אביו.","ואם נחשב \u0003שתין ותלת וארביסר\u0004 \u0005[שישים ושלוש וארבע עשרה]\u0006 \u0003עד דמתיליד\u0004 \u0005[שנולד]\u0006 \u0003יוסף, הא\u0004 \u0005[הרי]\u0006 \u0003שבעין ושבעה, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויוסף בן שלשים שנה בעמדו לפני פרעה\"\u0004 (בראשית מא, מו), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מאה ושבע\u0004 שנים ליעקב, ונוסיף \u0003שב דשבעא ותרתי דכפנא\u0004 \u0005[שבע\u0006 שני \u0005השובע ושתיים של רעב] —\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מאה ושיתסר\u0004 \u0005[ושש עשרה]\u0006 שנה, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר פרעה אל יעקב כמה ימי שני חייך. ויאמר יעקב אל פרעה ימי שני מגורי שלשים ומאת שנה\"\u0004 (בראשית מז, ח-ט), והרי לפי חשבוננו \u0003מאה ושיתסר\u0004 \u0005[ושש עשרה]\u0006 \u0003הויין\u0004 \u0005[היו],\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003ארבע עשרה שנין דהוה\u0004 \u0005[\u0006ה\u0005שנים שהיה]\u0006 יעקב \u0003בבית עבר לא חשיב להו\u0004 \u0005[אינו מונה אותן].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה יעקב בבית עבר מוטמן\u0004 (חבוי) \u0003ארבע עשרה שנה.\u0004 כי \u0003עבר מת לאחר שירד יעקב אבינו לארם נהרים שתי שנים\u0004 אם מחשבים את שנות הדורות הראשונים עד יעקב, והרי \u0003יצא משם ובא לו\u0004 מיד \u0003לארם נהרים, נמצא כשעמד\u0004 יעקב \u0003על הבאר\u0004 — \u0003בן שבעים ושבע שנה\u0004 היה.","","","\u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003לא מיענש\u0004 \u0005[נענש]\u0006 על ביטול כיבוד אב ואם — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נמצא יוסף שפירש מאביו,\u0004 היה מובדל ממנו \u0003עשרים ושתים שנה, כשם שפירש יעקב אבינו מאביו\u0004 והלא לפי החשבון שעשינו, השנים שפירש \u0003יעקב\u0004 מאביו \u0003תלתין ושיתא הויין\u0004 \u0005[שלושים ושש היו]!\u0006 \u0003אלא: ארביסר דהוה\u0004 \u0005[ארבע עשרה\u0006 שנה \u0005שהיה]\u0006 \u0003בבית עבר לא חשיב להו\u0004 \u0005[מנה אותן].\u0006","ומקשים: הלא \u0003סוף סוף\u0004 השנים שהיה ב\u0003בית לבן עשרין שנין הויין\u0004 \u0005[עשרים שנים היו]\u0006 ולא עשרים ושתים! \u0003אלא משום דאשתהי באורחא תרתין שנין\u0004 \u0005[שהשתהה בדרך\u0006 חזרה מארם נהרים עוד \u0005שתי שנים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יצא מארם נהרים ובא לו לסכות, ועשה שם שמונה עשר חודש, שנאמר: \"ויעקב נסע סכתה ויבן לו בית ולמקנהו עשה סכת\"\u0004 (בראשית לג, יז), לומר שתחילה עשה סוכות בעונת הקיץ ואחר כך בנה בחורף בית, ואחר כך שוב עשה סוכות, והרי אלה שמונה עשר חודש, \u0003ובבית אל עשה ששה חדשים, והקריב זבחים\u0004 אחרי שנתיים ימים. ולפי זה חשבון השנים מכוון מכל צד.","","\u0003הקורא את המגילה למפרע\u0004 (בשינוי הסדר, שהקדים את המאוחר) — \u0003לא יצא\u0004 ידי חובתו. \u0003קראה\u0004 את המגילה ב\u0003על פה,\u0004 או ש\u0003קראה תרגום בכל לשון — לא יצא. אבל קורין אותה\u0004 את המגילה \u0003ללועזות\u0004 המדברים בשפה זרה \u0003בלעז, והלועז ששמע\u0004 את קריאת המגילה \u0003אשורית\u0004 כלומר בלשון הקודש — \u0003יצא.\u0004 \u0003קראה\u0004 הקורא ל\u0003סירוגין\u0004 או כשהיה \u0003מתנמנם — יצא\u0004 ידי חובה. \u0003היה כותבה\u0004 או \u0003דורשה,\u0004 שמעיין בה לצורך דרשה, או \u0003מגיהה\u0004 ובתוך כך קורא אותה, \u0003אם כוון לבו\u0004 לצאת בכך ידי חובה \u0003— יצא, ואם לאו\u0004 \u0005[לא] —\u0006 \u0003לא יצא.\u0004","","\u0003היתה\u0004 המגילה \u0003כתובה בסם\u0004 או \u0003בסיקרא\u0004 או \u0003בקומוס\u0004 או \u0003בקנקנתום,\u0004 שבכל אלה אפשר לכתוב אלא שאינם דיו ממש, או שהיתה כתובה \u0003על הנייר\u0004 או \u0003על דפתרא\u0004 (עור בלתי מעובד) — \u0003לא יצא\u0004 ידי חובה \u0003עד שתהא כתובה אשורית\u0004 (בלשון ובכתב עברי) \u0003על הספר\u0004 (מגילת קלף), \u0003ובדיו.\u0004 על ההלכה במשנה שהקורא למפרע לא יצא, שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים האלו]?\u0006 \u0003אמר רבא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004להיות עושים את שני הימים האלה \u0003ככתבם וכזמנם\"\u0004 (אסתר ט, כז), ואנחנו לומדים בדרך היקש: \u0003מה זמנם למפרע לא,\u0004 שהרי אי אפשר להפוך את הזמן למפרע שיהיה חמישה עשר באדר לפני ארבעה עשר בו, \u0003אף כתבם למפרע — לא.\u0004","","ותוהים: \u0003מידי\u0004 \u0005[וכי]\u0006 לשון \u0003קריאה כתיבה הכא\u0004 \u0005[נאמרה כאן]?\u0006 הלא רק לשון \u0003\"עשייה\" כתיבה\u0004 \u0005[נאמרה]\u0006 כאן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"להיות עשים את שני הימים\u0004 האלה ככתבם וכזמנם\u0003\"\u0004 (אסתר ט, כז)! \u0003אלא\u0004 הראיה היא \u0003מהכא\u0004 \u0005[מכאן]\u0006 שנאמר: \u0003\"והימים האלה נזכרים ונעשים\"\u0004 (אסתר ט, כח), \u0003איתקש\u0004 \u0005[הוקשה,\u0006 הושוותה\u0005]\u0006 \u0003זכירה לעשייה, מה עשיה למפרע לא,\u0004 כפי שלמדנו מ\"ככתבם וכזמנם\", \u0003אף זכירה למפרע\u0004 — \u0003לא.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003וכן\u0004 הדין \u0003בהלל, וכן בקריאת שמע, ובתפלה,\u0004 שאינו יוצא ידי חובה אם קורא למפרע.","ושואלים: \u0003הלל מנלן\u0004 \u0005[מניין לנו]\u0006 שאין לקראו למפרע? \u0003רבה אמר: דכתיב\u0004 \u0005[שנאמר]\u0006 בהלל עצמו: \u0003\"ממזרח שמש עד מבואו\"\u0004 (תהלים קיג, ג), וכשם שאי אפשר להפוך את הזריחה לשקיעה — כך אין הופכים את סדר ההלל. \u0003רב יוסף אמר\u0004 שהדבר נלמד ממה שנאמר: \u0003\"זה היום עשה ה'\"\u0004 (תהלים קיח, כד), לומר כשם שהיום הולך כסדרו, כך ההלל צריך להיאמר כסדרו.","\u0003רב אויא אמר:\u0004 יש ללמוד זאת מהכתוב \u0003\"יהי שם ה' מברך\"\u0004 (תהלים קיג, ב), שהסדר צריך להיות בלתי משתנה כמו שם ה'. \u0003רב נחמן בר יצחק ואיתימא\u0004 \u0005[ויש אומרים]\u0006 ש\u0003רב אחא בר יעקב אמר: מהכא\u0004 \u0005[מכאן]\u0006 אתה למד זאת: \u0003\"מעתה ועד עולם\"\u0004 (תהלים קיג, ב). כמו הזמן שאין אפשרות להופכו. \u0003קריאת שמע\u0004 מניין לנו שאינו יוצא כשאינה נקראת כסדרה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קריאת שמע\u0004 קוראין אותה \u0003ככתבה\u0004 כלומר בעברית, אלו \u0003דברי רבי, וחכמים אומרים:\u0004 קוראים אותה \u0003בכל לשון.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 דבריו של \u0003רבי? אמר קרא\u0004 \u0005[הכתוב]:\u0006",""],["\u0003\"והיו\u0004 הדברים\u0003\"\u0004 (דברים ו, ו) לומר \u0003בהויתן\u0004 (כמו שהם) בלשון הקודש \u0003יהו\u0004 (יהיו) תמיד. ושואלים: \u0003ורבנן, מאי טעמייהו\u0004 \u0005[וחכמים, מה טעמם]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"שמע\"\u0004 (דברים ו, ד), כלומר: הבן \u0003בכל לשון שאתה שומע.\u0004","ושואלים: \u0003ורבי נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"שמע\"!\u0004 ומשיבים: הפסוק \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 כדי ללמוד ממנו דבר אחר: \u0003השמע לאזניך מה שאתה מוציא מפיך,\u0004 שלא די שיאמר קריאת שמע בלבו, אלא צריך להשמיע בקול שישמעו אזניו. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים על כך? ומשיבים: הם \u0003סברי כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 כי \u0003הקורא את שמע ולא השמיע לאזנו — יצא.\u0004","ושואלים: \u0003ורבנן נמי הכתיב\u0004 \u0005[ו\u0006לדעת \u0005חכמים גם כן הרי נאמר]\u0006 \u0003\"והיו\",\u0004 ומה הם למדים מכאן? ומשיבים: \"והיו\" \u0003ההוא\u0004 שנאמר, \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמד \u0003שלא יקרא למפרע.\u0004 ושואלים: \u0003ורבי,\u0004 עניין זה \u0003שלא יקרא למפרע מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: מכיון שלא נאמר \u0003\"דברים\"\u0004 אלא \u0003\"הדברים\"\u0004 ללמדנו כי צריך שיקרא אותם בסדרם זה ולא בשינוי. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים על כך? ומשיבים: הדיוק של \u0003\"דברים\" \"הדברים\" לא משמע להו\u0004 \u0005[נשמע להם],\u0006 שאינו נראה להם כראיה.","ומציעים: \u0003לימא קסבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003רבי: כל התורה כולה, בכל לשון נאמרה,\u0004 כלומר, כל התורה יכולה להיקרא בכל לשון? \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שכל התורה כולה דווקא \u0003בלשון הקודש נאמרה\u0004 ואינה נאמרת בכל לשון אחרת — אם כן \u0003למה לי למכתב\u0004 \u0005[לכתוב]\u0006 \u0003\"והיו\"\u0004 בקריאת שמע, תיחשב פרשה זו ככל שאר התורה!","ודוחים, אין מכאן ראיה, כי \u0003אצטריך\u0004 \u0005[צריך\u0006 הדבר\u0005]\u0006 להיאמר במיוחד, כי \u0003סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כי \u0003\"שמע\"\u0004 פירושו: הבן, \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 ובגלל לימוד מיוחד זה יותר הדבר אף בניגוד לשאר כל התורה, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה\u0006 כאן \u0005התורה]\u0006 \u0003\"והיו\",\u0004 ללמדנו שבכל זאת צריך לומר את הדברים כהווייתם.","ושואלים מצד אחר: \u0003לימא קסברי רבנן\u0004 \u0005[האם לומר שסברו חכמים]:\u0006 \u0003כל התורה בלשון הקודש\u0004 דווקא \u0003נאמרה? דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר כי \u0003בכל לשון נאמרה — למה לי למכתב\u0004 \u0005[לכתוב]\u0006 \u0003\"שמע\"?\u0004 שהרי אם כל התורה נאמרת בכל לשון — גם זו כך!","ודוחים: \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005],\u0006 כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003\"והיו\"\u0004 פירושו \u0003כרבי\u0004 — שיאמרו דווקא בלשון הכתובה בתורה, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"שמע\".\u0004","ושואלים: \u0003תפלה מנא לן\u0004 \u0005[מניין לנו]\u0006 שאין לשנות בה את הסדר? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שמעון הפקולי הסדיר שמונה עשרה ברכות לפני רבן גמליאל על הסדר ביבנה,\u0004 ומכאן למדים שיש סדר משמעותי בברכות אלה, שאין לשנותו. \u0003אמר ר' יוחנן ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 ש\u0005בברייתא שנה]\u0006 זאת: \u0003מאה ועשרים זקנים ובהם כמה נביאים\u0004 אנשי כנסת הגדולה, הם \u0003תיקנו שמונה עשרה ברכות על הסדר\u0004 בתחילה, ולכן אין לשנות סדרן. ומכאן להסברת סדר הברכות בתפילת שמונה עשרה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאומרים\u0004 ברכת \u0003\"אבות\"? שנאמר: \"הבו לה' בני אלים\"\u0004 (תהלים כט, א), כלומר הזכירו לה' את אילי ארץ החשובים — אבותינו. \u0003ומנין שאומרים\u0004 ברכת \u0003\"גבורות\" שנאמר: \"הבו לה' כבוד ועז\"\u0004 (תהלים כט, א) ומשמעות \"עוז\" הוא גבורה. \u0003ומנין שאומרים\u0004 ברכת \u0003\"קדושות\"? שנאמר: \"הבו לה' כבוד שמו השתחוו לה' בהדרת קדש\"\u0004 (תהלים כט, ב) הרי כאן: \"אבות\", \"גבורות\", ו\"קדושות\", לפי הסדר.","\u0003ומה ראו לומר\u0004 ברכת \u0003\"בינה\"\u0004 (\"חונן לאדם דעת\") \u0003אחר \"קדושה\"? שנאמר: \"והקדישו את קדוש יעקב ואת אלהי ישראל יעריצו\"\u0004 (ישעיהו כט, כג), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]:\u0006 \u0003\"וידעו תעי רוח בינה\"\u0004 (ישעיהו כט, כד). \u0003ומה ראו לומר\u0004 ברכת ה\u0003\"תשובה\" אחר\u0004 ברכת ה\u0003\"בינה\"? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולבבו יבין ושב ורפא לו\"\u0004 (ישעיהו ו, י) ושואלים:","\u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה לומד מפסוק זה — \u0003לימא\u0004 \u0005[שיאמר]\u0006 אם כן ברכת \u0003\"רפואה\" בתרה\u0004 \u0005[אחר]\u0006 ברכת \u0003\"תשובה\",\u0004 ומדוע אין אומרים אותה בסמוך? ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול הדבר \u0005להעלות על דעתך],\u0006 משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישב אל ה' וירחמהו ואל אלהינו כי ירבה לסלוח\"\u0004 (ישעיהו נה, ז), ללמד שאחרי התשובה צריכה להיות הסליחה וכך גם סדר הברכות.","ושואלים: \u0003ומאי חזית דסמכת אהא\u0004 \u0005[ומה ראית לסמוך על\u0006 פסוק \u0005זה]\u0006 \u0003סמוך אהא\u0004 \u0005[על\u0006 פסוק \u0005זה]\u0006 וסדר רפואה אחר תשובה! ומשיבים: \u0003כתב קרא אחרינא\u0004 \u0005[נאמר פסוק אחר]:\u0006 \u0003\"הסלח לכל עונכי הרפא לכל תחלואיכי. הגואל משחת חייכי\"\u0004 (תהלים קג, ג-ד), שאף ממנו מוכח שברכת ה\"סליחה\" קודמת לברכת ה\"רפואה\". \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שברכות \u0003\"גאולה\" ו\"רפואה\" בתר\u0004 \u0005[אחר]\u0006 ברכת ה\u0003\"סליחה\" היא, והכתיב\u0004 \u0005[והרי\u0006 בכל זאת \u0005נאמר]:\u0006 \u0003\"ושב ורפא לו\",\u0004 ולכאורה היו צריכות להיות אחר ברכת ה\"תשובה\"! ומשיבים: צריכים להבין כי הפסוק \u0003ההוא לאו\u0004 \u0005[לא]\u0006 ב\u0003רפואה\u0004 של \u0003תחלואים\u0004 הוא מדבר, \u0003אלא רפואה\u0004 של \u0003סליחה היא.\u0004 ולכן קבעו ברכת הסליחה אחרי ברכת התשובה.","ושואלים: \u0003ומה ראו לומר\u0004 ברכת \u0003\"גאולה\"\u0004 כברכה \u0003שביעית\u0004 במספר? \u0003אמר רבא: מתוך\u0004 שמסורת בידינו \u0003שעתידין\u0004 ישראל \u0003ליגאל\u0004 בשנה \u0003השביעית\u0004 (השמיטה) \u0003לפיכך קבעוה בשביעית.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003ב\u0004שנה ה\u0003ששית\u0004 לשנות השמיטה של ימות המשיח ישמעו \u0003קולות, ב\u0004שנה ה\u0003שביעית\u0004 יהיו \u0003מלחמות,\u0004 ו\u0003במוצאי שביעית\u0004 משיח \u0003בן דוד בא,\u0004 הרי שלא תהיה הגאולה בשביעית אלא לאחריה! ומשיבים: בכל זאת \u0003מלחמה\u0004 זו \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אתחלתא\u0004 \u0005[התחלת]\u0006 ה\u0003גאולה היא\u0004 ולכן שייך לומר שהגאולה בשביעית.","\u0003ומה ראו לומר\u0004 ברכת \u0003\"רפואה\" בשמינית? אמר ר' אחא: מתוך שנתנה מילה בשמינית\u0004 (ביום השמיני) והיא \u0003צריכה רפואה, לפיכך קבעוה\u0004 את ברכת \"רפואה\" \u0003בשמינית.\u0004","\u0003ומה ראו לומר\u0004 את \u0003ברכת ה\"שנים\"\u0004 בתור ברכה \u0003תשיעית? אמר ר' אלכסנדרי:\u0004 ברכה זו אמרו \u0003כנגד מפקיעי שערים,\u0004 שיש להתפלל שיירד הגשם, ולא יפקיעו את שער התבואה בגלל מחסור בה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שבר זרוע רשע\"\u0004 (תהלים י, טו) ומזמור זה מדבר ברשעים העושים תחבולות וגוזלים עניים, \u0003ודוד כי\u0004 \u0005[כאשר]\u0006 \u0003אמרה,\u0004 את הבקשה הזו — במזמור \u0003תשיעי אמרה,\u0004 שכן אנו מונים את המזמור הראשון והשני כאחד, ונמצא שהוא במזמור תשיעי.","ושואלים: \u0003ומה ראו לומר\u0004 ברכת \u0003\"קיבוץ גליות\" לאחר ברכת ה\"שנים\"? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואתם הרי ישראל ענפכם תתנו ופריכם תשאו לעמי ישראל כי קרבו לבוא\"\u0004 (יחזקאל לו, ח), הרי שקיבוץ גלויות בא לאחר ברכת האדמה. \u0003וכיון שנתקבצו גליות\u0004 אז \u0003נעשה\u0004 גם \u0003דין ברשעים\u0004 שאינם מאמינים בדת משה שהיא מן השמים, \u0003שנאמר: \"ואשיבה ידי עליך ואצרף כבר סיגיך\"\u0004 (ישעיה א, כה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך: \u0003\"ואשיבה שפטיך כבראשונה\"\u0004 (ישעיה א, כו) ולכן הסמיכו ברכת \"השיבה שופטינו\" לברכת \"קיבוץ גלויות\".","\u0003וכיון שנעשה דין מן הרשעים כלו הפושעים מינים, וכולל זדים\u0004 העוברים במזיד \u0003עמהם\u0004 (עם המינים) \u0003שנאמר: \"ושבר פשעים וחטאים יחדו\u0004 ועוזבי ה' \u0003יכלו\"\u0004 (ישעיה א, כח).","\u0003וכיון שכלו המינים מתרוממת\u0004 אז \u0003קרן צדיקים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל קרני רשעים אגדע תרוממנה קרנות צדיק\"\u0004 (תהלים עה, יא), שהדבר תלוי זה בזה. \u0003וכולל גירי הצדק עם הצדיקים, שנאמר: \"מפני שיבה תקום והדרת פני זקן\"\u0004 (ויקרא יט, לב), שפירוש \"זקן\" — זה שקנה חכמה, \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]:\u0006 \u0003\"וכי יגור אתכם גר\"\u0004 (ויקרא יט, לג).","\u0003והיכן מתרוממת קרנם\u0004 של צדיקים? \u0003בירושלים, שנאמר: \"שאלו שלום ירושלים ישליו אהביך\"\u0004 (תהלים קכב, ו) לכן סמכו את ברכת \"בונה ירושלים\" לברכת \"על הצדיקים\".","\u0003וכיון שנבנית ירושלים — בא דוד\u0004 המשיח, \u0003שנאמר:\u0004"],["\u0003\"אחר ישבו בני ישראל ובקשו את ה' אלהיהם ואת דויד מלכם\"\u0004 (הושע ג, ה), וזוהי ברכת \"את צמח דוד\" הנאמרת אחר \"בונה ירושלים\". \u0003וכיון שבא דוד\u0004 — \u0003באתה\u0004 \u0005[באה]\u0006 הגיעה והתקבלה ה\u0003תפלה, שנאמר: \"והביאותים אל הר קדשי ושמחתים בבית תפלתי\"\u0004 (ישעיהו נו, ז), ולכן נאמרת ברכת \"שמע קולנו\" לאחריה.","\u0003וכיון שבאת תפלה — באת\u0004 ומתקבלת ה\u0003עבודה\u0004 במקדש, \u0003שנאמר: \"עולתיהם וזבחיהם לרצון על מזבחי\"\u0004 (ישעיהו נו, ז), וזוהי ברכת \"ותחזינה עינינו\". \u0003וכיון שבאת \"עבודה\"\u0004 — \u0003באתה\u0004 איתה גם ה\u0003תודה, שנאמר: \"זבח תודה יכבדנני\"\u0004 (תהלים נ, כג) שאחר עבודת הזבח (\"זובח\") באה תודה.","\u0003ומה ראו לומר ברכת כהנים\u0004 בתפילה ל\u0003אחר\u0004 ברכת \u0003\"הודאה\"? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישא אהרן את ידו אל העם ויברכם וירד מעשת החטאת והעלה והשלמים\"\u0004 (ויקרא ט, כב), ואף הודאה היא בכלל עבודה.","ושואלים: \u0003אימא\u0004 \u0005[אמור]\u0006 לפי סדר המקרא, שהיה הדבר \u0003קודם עבודה?\u0004 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירד מעשת החטאת\". מי כתיב\u0004 \u0005[האם כתוב]\u0006 \u0003\"לעשות\"\u0004 שהיא לשון המורה על העתיד, הלא \u0003\"מעשת\" כתיב\u0004 \u0005[כתוב]\u0006 ומשמעה לאחר שכבר עשה.","ושואלים: אם כן \u0003ולימרה\u0004 \u0005[ושיאמר אותה]\u0006 את ברכת הכהנים מיד \u0003אחר\u0004 ברכת \u0003העבודה!\u0004 ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זבח תודה\"\u0004 (תהלים נ, כג) משמע: התודה באה אחר הזבח.","ושואלים: \u0003ומאי חזית דסמכת אהאי\u0004 \u0005[ומה ראית שסמכת על\u0006 פסוק \u0005זה],\u0006 \u0003סמוך אהאי\u0004 \u0005[על\u0006 פסוק \u0005זה]!\u0006 ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר\u0006 לומר\u0005]\u0006 ש\u0003עבודה והודאה חדא מילתא היא\u0004 \u0005[דבר אחד הוא].\u0006 ותוכנם העיקרי אחד.","\u0003ומה ראו לומר\u0004 ברכת \u0003\"שים שלום\" אחר ברכת כהנים? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמו את שמי על בני ישראל ואני אברכם\"\u0004 (במדבר ו, כז), שבראשית \"ושמו את שמי על בני ישראל\" ורק אחר כך \"ואני אברכם\", וה\u0003ברכה\u0004 של \u0003הקדוש ברוך הוא — שלום, שנאמר: \"ה' יברך את עמו בשלום\"\u0004 (תהלים כט, יא). עד כאן ההסבר לסדר הברכות.","ושואלים על תחילתה של ברייתא זו: \u0003וכי מאחר\u0004 ש\u0003מאה ועשרים זקנים ומהם כמה נביאים תקנו תפלה על הסדר,\u0004 אם כן \u0003שמעון הפקולי מאי\u0004 \u0005[מה]\u0006 \u0003הסדיר?\u0004 הלא הכל היה כבר מסודר! ומשיבים: \u0003שכחום, וחזר וסדרום.\u0004","ומעירים: \u0003מכאן ואילך,\u0004 כלומר, יותר מזה \u0003אסור לספר בשבחו של הקדוש ברוך הוא\u0004 ולהוסיף ברכות אחרות. לפי ש\u0003אמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מי ימלל גבורות ה' ישמיע כל תהלתו\"\u0004 (תהלים קו, ב), \u0003למי נאה למלל גבורות ה' — למי שיכול להשמיע כל תהלתו.\u0004 וכיון שאין אדם יכול לעשות זאת, צריך להסתפק במה שקבעו חכמים.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: המספר בשבחו של הקדוש ברוך הוא יותר מדאי — נעקר מן העולם,\u0004 שנראה כאילו הוא גומר לומר כל שבחו של ה', \u0003שנאמר: \"היספר לו כי אדבר, אם אמר איש כי יבלע\"\u0004 (איוב לז, כ), שהאומר יותר מדי — סופו שיבולע לו.","\u0003דרש ר' יהודה איש כפר גבוריא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003איש כפר גבור חיל: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"לך דמיה תהלה\"\u0004 (תהלים סה, ב), \u0003סמא דכולה\u0004 \u0005[התרופה לכל] —\u0006 \u0003משתוקא\u0004 \u0005[שתיקה].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 בפתגם עממי: \u0003מלה — בסלע, משתוקא\u0004 \u0005[שתיקה] —\u0006 \u0003בתרין\u0004 \u0005[בשנים].\u0006 כלומר, גם אם מלה שווה מטבע של סלע, שתיקה שווה שנים.","נאמר במשנה שאם \u0003קראה\u0004 את המגילה ב\u0003על פה\u0004 — \u0003לא יצא.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דין זה? \u0003אמר רבא: אתיא\u0004 \u0005[בא]\u0006 נלמד הדבר בגזירה שווה של פעלים: \u0003'זכירה' 'זכירה', כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"והימים האלה נזכרים\"\u0004 (אסתר ט, כח) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"כתב זאת זכרון בספר\u0004 ושים באזני יהושע כי מחה אמחה את זכר עמלק\u0003\"\u0004 (שמות יז, יד), \u0003מה להלן\u0004 בספר שמות אין זכירה אלא \u0003בספר,\u0004 שהרי כך כתוב בתורה, \u0003אף כאן\u0004 במגילה אין זכירה אלא \u0003בספר.\u0004","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 למד אתה \u0003דהאי\u0004 \u0005[שזו]\u0006 ה\u0003זכירה\u0004 שבספר שמות \u0003קריאה היא, דלמא\u0004 \u0005[שמא]\u0006 \u0003עיון בעלמא\u0004 \u0005[סתם]\u0006 בדברים הוא כדי להזכר בהם! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, שהרי שנינו בברייתא, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זכור\u0004 את אשר עשה לך עמלק\u0003\"\u0004 (דברים כה, יז), \u0003יכול\u0004 די שתהיה זו זכירה \u0003בלב? כשהוא אומר \"לא תשכח\"\u0004 (דברים כה, יט) \u0003הרי שכחת הלב אמור,\u0004 וכיון שזכירה שבלב כבר נאמרה \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 את מה שנאמר \u0003\"זכור\"\u0004 כמצוות עשה בפועל — שצריך להגיד \u0003בפה.\u0004","נאמר במשנה שאם \u0003קראה תרגום\u0004 — \u0003לא יצא וכו'.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אילימא דכתיבה\u0004 \u0005[אם תאמר ש\u0006היא \u0005כתובה]\u0006 \u0003מקרא,\u0004 בלשון הקודש \u0003וקרי לה\u0004 \u0005[ו\u0006הוא \u0005קורא אותה]\u0006 \u0003תרגום,\u0004 אם כן \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003על פה!\u0004 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא מדובר \u0003דכתיבה\u0004 \u0005[ש\u0006היא \u0005כתובה]\u0006 \u0003תרגום וקרי לה\u0004 \u0005[ו\u0006הוא \u0005קורא אותה]\u0006 אותה \u0003תרגום.\u0004","שנינו במשנה: \u0003אבל קורין אותה\u0004 את המגילה \u0003ללועזות בלעז,\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 זה עתה במשנה: \u0003קראה בכל לשון\u0004 — \u0003לא יצא!\u0004 ומשיבים: \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 מדובר כאן \u0003בלעז יווני,\u0004 שיש לו דין מיוחד,","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אילימא דכתיבה\u0004 \u0005[אם תאמר\u0006 \u0005ש\u0006היא \u0005כתובה]\u0006 \u0003אשורית\u0004 (בעברית), \u0003וקרי לה\u0004 \u0005[וקורא אותה]\u0006 בלשון ה\u0003יוונית — היינו\u0004 \u0005[הרי זו]\u0006 קריאה \u0003על פה,\u0004 והרי אמרנו כבר שלא יצא! \u0003אמר ר' אחא אמר ר' אלעזר:\u0004 הכוונה \u0003ש\u0004היא \u0003כתובה בלעז יונית.\u0004","אגב כך מביאים עוד מאמר ממסורת זו. \u0003ואמר ר' אחא אמר ר' אלעזר: מנין שקראו הקדוש ברוך הוא ליעקב \"אל\"? שנאמר: \"\u0004ויצב שם מזבח \u0003ויקרא לו אל אלהי ישראל\"\u0004 (בראשית לג, כ). \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר כי \u0003למזבח קרא ליה\u0004 \u0005[לו]\u0006 \u0003יעקב \"אל\"\u0004 ולא הקדוש ברוך הוא הוא שכינה אותו כך, אם כן — \u0003\"ויקרא לו יעקב\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו]\u0006 לומר, \u0003אלא ויקרא לו ליעקב \"אל\", ומי קראו \"אל\" — אלהי ישראל.\u0004","ולענייננו: \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 לרב ושמואל האומרים כי ללעז יווני יש דין מיוחד, ממה ששנינו בברייתא: \u0003קראה\u0004 את המגילה \u0003גיפטית\u0004 (מצרית), \u0003עברית, עילמית, מדית, יוונית — לא יצא,\u0004 הרי מכאן שאין יוצאים בקריאת המגילה בלעז יווני!","ומתרצים: צריך לומר כך; \u0003הא\u0004 \u0005[זו]\u0006 של רב ושמואל \u0003לא דמיא\u0004 \u0005[אינה דומה]\u0006 \u0003אלא להא\u0004 \u0005[לזו]\u0006 ששנויה בברייתא אחרת: קרא את המגילה \u0003גפטית לגיפטים, עברית לעברים, עילמית לעילמים, יוונית ליוונים — יצא.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאם קורא לאדם המדבר בשפה לועזית את המגילה באותה לשון בה הוא מדבר, שהוא יוצא בכך ידי חובה, אם כן \u0003רב שמואל אמאי מוקמי לה למתניתין\u0004 \u0005[מדוע מעמידים\u0006 הם \u0005את המשנה]\u0006 \u0003בלעז יוונית\u0004 דווקא? \u0003לוקמה\u0004 \u0005[שיעמידו אותה]\u0006 \u0003בכל לעז\u0004 שהוא ובקריאה לדוברים באותה שפה! \u0003אלא, מתניתין\u0004 \u0005[משנתנו]\u0006 צריכים להבין אותה \u0003כברייתא\u0004 שאין יוצאים בקריאת המגילה בלעז לאדם שאינו מבין. \u0003וכי איתמר\u0004 \u0005[מה שנאמר]\u0006 בשם \u0003רב ושמואל בעלמא איתמר\u0004 \u0005[בכלל נאמר],\u0006 לא כפירוש למשנתנו אלא כהלכה לעצמה. וכך יש לגרוס: \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לעז יווני לכל כשר,\u0004 גם לאלה שאינם יוונים.","ומקשים, \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 בברייתא: \u0003יוונית ליוונים,\u0004 ונדייק: ליוונים — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לכולי עלמא\u0004 \u0005[לכל העולם\u0006 לאחרים\u0005]\u0006 — \u0003לא!\u0004 ומשיבים: \u0003אינהו דאמור\u0004 \u0005[הם שאמרו]\u0006 דבריהם — \u0003כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 אמרו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003רבן שמעון בן גמליאל אומר: אף ספרים\u0004 (ספרי תורה) \u0003לא התירו\u0004 חכמים \u0003שיכתבו\u0004 פרט לעברית \u0003אלא\u0004 רק ב\u0003יוונית,\u0004 ומכאן שהשפה היוונית דינה כעברית לכל דבר.","ומקשים: אם כן, \u0003ולימרו\u0004 \u0005[ושיאמרו]\u0006 במפורש: \u0003הלכה כרבן שמעון בן גמליאל,\u0004 ומדוע הוצרכו לומר זאת בסגנון כאילו היתה זו הלכה חדשה? ומשיבים: \u0003אי אמרי\u0004 \u0005[אם\u0006 היו \u0005אומרים]\u0006 \u0003הלכה כרבן שמעון בן גמליאל, הוה אמינא\u0004 \u0005[היינו אומרים]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא ב\u0003שאר ספרים\u0004 של קודש, \u0003אבל מגילה דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"ככתבם\", אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 ייצאו ידי חובה בקריאתה יוונית — על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בדבריהם שאפילו במגילה יצא.","שנינו במשנה: \u0003והלועז ששמע אשורית יצא.\u0004 ותוהים: \u0003והא לא ידע מאי קאמרי\u0004 \u0005[הרי איננו יודע מה שהם אומרים]\u0006 שהרי איננו מבין עברית, וכיצד יצא ידי חובתו בעברית? ומשיבים: \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 הדבר ביחס ל\u0003נשים ועמי הארץ\u0004 שאף הם אינם מבינים עברית כראוי, ובכל זאת יוצאים ידי חובתם בקריאתה.","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבינא,\u0004 על השאלה ששאלנו כיצד יוצא אדם כשאינו מבין את לשון המגילה: \u0003אטו אנן\u0004 \u0005[וכי אנו]\u0006 אף החכמים, האם הביטוי \u0003\"האחשתרנים בני הרמכים\"\u0004 (אסתר ח, י) הכתוב במגילה \u0003מי ידעינן\u0004 \u0005[האם אנו יודעים,\u0006 מבינים\u0005]\u0006 מה הוא? \u0003אלא\u0004 העיקר הוא שיש \u0003מצות קריאה ופרסומי ניסא\u0004 \u0005[ופירסום הנס]\u0006 בכלל, ו\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 כאשר קוראים ללועזים בעברית — \u0003מצות קריאה ופרסומי ניסא\u0004 \u0005[ופרסום הנס]\u0006 יש בדבר, ודי בכך.","שנינו במשנה: \u0003קראה לסירוגין יצא.\u0004 מספרים: \u0003לא הוו ידעי רבנן מאי\u0004 \u0005[היו יודעים חכמים מהו]\u0006 פירוש המלה \u0003\"סירוגין\", שמעוה לאמתא דבי\u0004 \u0005[שמעו אותה,\u0006 את \u0005השפחה של בית]\u0006 \u0003רבי,\u0004 שכיון שהיתה בביתו שמעה בודאי לשון עברית טהורה \u0003דקאמרה להו לרבנן דהוי עיילי פסקי פסקי לבי\u0004 \u0005[שאמרה להם לחכמים שהיו נכנסים מעט מעט\u0006 ולא בבת אחת \u0005לבית]\u0006 \u0003רבי: עד מתי אתם נכנסים סירוגין סירוגין?\u0004 ואז הבינו ש\"סירוגין\" פירושו בהפסקות.","כיוצא בזה מספרים: \u0003לא הוו ידעי רבנן מאי\u0004 \u0005[לא היו יודעים חכמים מה\u0006 פירוש\u0005]\u0006 המלה \u0003\"חלוגלוגות\"\u0004 המוזכרת במשניות ובברייתות. \u0003שמעוה לאמתא דבי\u0004 \u0005[שמעו אותה,\u0006 את \u0005השפחה של בית]\u0006 \u0003רבי\u0004 ש\u0003אמרה ליה לההוא גברא\u0004 \u0005[לו, לאדם אחד]\u0006 \u0003דהוה קא מבדר\u0004 \u0005[שהיה מפזר]\u0006 \u0003פרפחיני: עד מתי אתה מפזר חלוגלוגך?\u0004 והבינו ש\"חלוגלוגות\" הם הקרויים בארמית פרפחיני.","וכן \u0003לא הוו ידעי רבנן\u0004 \u0005[היו יודעים חכמים]\u0006 בפסוק \u0003\"סלסלה ותרוממך\"\u0004 (משלי ד, ח) מה פירוש סילסול, \u0003שמעוה לאמתא דבי\u0004 \u0005[שמעו אותה,\u0006 את \u0005השפחה של בית]\u0006 \u0003רבי דהוות אמרה לההוא גברא דהוה מהפך במזייה\u0004 \u0005[שהיתה אומרת לאיש אחד שהיה מהפך בשערותיו]\u0006 ו\u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003עד מתי אתה מסלסל בשערותיך?\u0004","בדומה לזה מביאים עוד דוגמאות של פירוש מילים שנודעו לחכמים מפי הדיוטות; \u0003לא הוו ידעי רבנן\u0004 \u0005[היו יודעים חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הפסוק: \u0003\"השלך על ה' יהבך\"\u0004 (תהלים נה, כג), שלא ידעו מה הוא \"יהבך\". \u0003אמר רבה בר בר חנה: זימנא חדא הוה אזילנא בהדי ההוא טייעא וקא דרינא טונא\u0004 \u0005[פעם אחת הייתי מהלך עם ערבי אחד ונשאתי משא]\u0006 \u0003ואמר לי: שקול יהביך ושדי אגמלאי\u0004 \u0005[קח את יהבך,\u0006 משאך, \u0005והטל על גמלי],\u0006 והבינו ש\"יהב\" פירושו משא.","וכן \u0003לא הוו ידעי רבנן\u0004 \u0005[לא היו יודעים חכמים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וטאטאתיה במטאטא השמד\"\u0004 (ישעיה יד, כג), שלא הבינו מה פירוש המלה \"מטאטא\", \u0003שמעוה לאמתא דבי\u0004 \u0005[שמעו אותה,\u0006 את \u0005השפחה של בית]\u0006 \u0003רבי דהוות אמרה\u0004 \u0005[שהיתה אומרת]\u0006 \u0003לחברתה: שקולי טאטיתא וטאטי ביתא\u0004 \u0005[קחי מטאטא וטאטאי את הבית],\u0006 והבינו מה פירוש המלה \"מטאטא\".","ולעצם ההלכה בענין קריאה לסירוגין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003קראה סירוגין — יצא,\u0004"],["\u0003סירוסין\u0004 שהופך ומשנה את סדר המגילה — \u0003לא יצא. ר' מונא אומר משום\u0004 (בשמו של) \u0003ר' יהודה: אף ב\u0004קריאה \u0003סירוגין, אם שהה\u0004 והפסיק זמן רב \u0003כדי\u0004 שיוכל \u0003לגמור\u0004 בזמן זה \u0003את כולה — חוזר לראש. אמר רב יוסף: הלכה כר' מונא\u0004 בהלכה זו \u0003שאמר משום ר' יהודה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 מה שאמר ר' מונא \u0003כדי לגמור את כולה,\u0004 מה פירושו? האם הכוונה \u0003מהיכא דקאי לסיפא\u0004 \u0005[מהמקום ש\u0006הוא \u0005עומד\u0006 בו באותה שעה עד \u0005לסופה]?\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא \u0003מרישא לסיפא\u0004 \u0005[מראש לסוף]\u0006 המגילה כולה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה היא \u0003מרישא לסיפא\u0004 \u0005[מתחילה לסוף],\u0006 ש\u0003אם כן\u0004 שאתה אומר ממקום שהוא עומד בו, הלא \u0003נתת דבריך לשיעורין,\u0004 שבכל מקום שמפסיק יש שיעור אחר להפסקה, ואין חכמים קובעים שיעור שאינו קבוע.","\u0003אמר ר' אבא אמר ר' ירמיה בר אבא אמר רב: הלכה כר' מונא. ושמואל אמר: אין הלכה כר' מונא.\u0004 ומעירים: \u0003בסורא מתנו הכי\u0004 \u0005[\u0006היו \u0005שונים כך]\u0006 כלשון שאמרנו, ואילו \u0003בפומבדיתא מתנו הכי\u0004 \u0005[\u0006היו \u0005שונים כך]\u0006 בגירסה שונה במקצת, \u0003אמר רב כהנא אמר רב: הלכה כר' מונא ושמואל אמר: אין הלכה כר' מונא. רב ביבי מתני איפכא\u0004 \u0005[\u0006היה \u0005שונה להיפך],\u0006 \u0003רב אמר: אין הלכה כר' מונא, ושמואל אמר: הלכה כר' מונא.\u0004","\u0003אמר רב יוסף: נקוט\u0004 \u0005[החזק]\u0006 את הגירסה של \u0003רב ביבי בידך,\u0004 שמסתבר שהיא הנכונה, שאנו יודעים כי הכלל הוא ש\u0003שמואל הוא דחייש ליחידאה\u0004 \u0005[שחושש ל\u0006דעת \u0005יחיד\u0006 המחמיר\u0005]\u0006 אף כשרבים חולקים עליו ומקילים. וראיה לדבר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בנושא אחר: \u0003שומרת יבם,\u0004 כלומר, אשה שמת בעלה בלא בנים והיא מחכה (\"שומרת\") שהיבם (ואם אפשר הגדול באחים) ייבם אותה וישאנה או יחלוץ לה, \u0003ו\u0004בינתים \u0003קידש אחיו\u0004 של אותו יבם \u0003את אחותה\u0004 של האשה הזאת, \u0003משום\u0004 (בשמו של) \u0003ר' יהודה בן בתירה אמרו: אומרים לו\u0004 לאח הזה: \u0003המתן\u0004 ואל תישא את האחות \u0003עד שיעשה אחיך הגדול מעשה\u0004 ויפטור אותך מכל זיקה אל היבמה, שבין אם יחלוץ לה ובין אם יקחנה לו לאשה נותק בכך כל קשר של זיקה אל המשפחה ובכלל זה אל האח המקדש. שכל עוד לא נעשה מעשה הרי היבמה קשורה (\"זקוקה\") לכל אחד מהאחים, ועל ידי כך היא נחשבת כמעין אשתו ויש חשש לגבי חלות הקידושין באחותה, ואסור לו מדברי סופרים לישא את אחותה שהיא כעין אחות אשתו. ואולם חכמים חולקים על דעה זו וסוברים כי אין לאף אחד מן האחים פרט לגדול שבהם כל זיקה אליה ולכך אינה כלל כעין אשתו לשום ענין וממילא אינו אסור באחותה.","\u0003אמר שמואל: הלכה כר' יהודה בן בתירה,\u0004 ומכאן למדנו שהוא חושש לדעת היחיד המחמיר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003השמיט בה\u0004 ה\u0003סופר\u0004 (במגילה) \u0003אותיות או פסוקין\u0004 שלמים \u0003וקראן הקורא כמתורגמן המתרגם\u0004 בעל פה — \u0003יצא.\u0004 כלומר, אם היה קורא בעל פה מלה אחת או פסוק אחד — אינו נפסל.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 שנינו, אם \u0003היו בה\u0004 במגילה \u0003אותיות מטושטשות או מקורעות, אם רשומן\u0004 עדיין \u0003ניכר\u0004 בספר — \u0003כשרה, ואם לאו\u0004 \u0005[לא]\u0006 \u0003— פסולה,\u0004 משמע שאפילו חסרון אותיות אחדות פוסל את המגילה! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שאם היו בה אותיות מקורעות או מטושטשות פסולה, הרי זה דווקא אם היה זה \u0003בכולה\u0004 בכל המגילה, \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שאם חסר פסוק או שניים כשרה — הוא דווקא כשאינו אלא \u0003במקצתה,\u0004 ובאופן כזה החיסרון אינו מעכב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003השמיט בה הקורא פסוק אחד\u0004 — \u0003לא יאמר: אקרא את כולה\u0004 כסדרה \u0003ואחר כך\u0004 אחזור ו\u0003אקרא אותו פסוק\u0004 שהשמטתי, \u0003אלא\u0004 חוזר מיד ו\u0003קורא מאותו פסוק\u0004 שהשמיט \u0003ואילך.\u0004 וכן, אם \u0003נכנס\u0004 אדם \u0003לבית הכנסת ומצא צבור שקראו חציה\u0004 של המגילה — \u0003לא יאמר: אקרא חציה\u0004 השני \u0003עם הצבור, ואחר כך\u0004 אשלים ו\u0003אקרא חציה\u0004 הראשון לבדי או עם ציבור אחר, \u0003אלא קורא אותה מתחילתה ועד סופה.\u0004","שנינו במשנה: שהקורא את המגילה \u0003מתנמנם\u0004 — \u0003יצא.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הוא]\u0006 \u0003מתנמנם? אמר רב אשי: נים\u0004 \u0005[ישן]\u0006 \u0003ולא נים\u0004 \u0005[ישן],\u0006 \u0003תיר\u0004 \u0005[ער]\u0006 \u0003ולא תיר\u0004 \u0005[ער],\u0006 \u0003דקרו ליה ועני, ולא ידע לאהדורי סברא, וכי מדכרו ליה מידכר\u0004 \u0005[ש\u0006אם \u0005קוראים לו\u0006 הוא \u0005עונה,\u0006 אך \u0005אינו יודע להשיב\u0006 דבר הדורש \u0005מחשבה, וכאשר מזכירים לו\u0006 דבר שאירע הוא \u0005נזכר]\u0006 זה הוא מתנמנם.","שנינו במשנה: אם \u0003היה\u0004 קורא את המגילה תוך כדי שהיה \u0003כותבה\u0004 או \u0003דורשה\u0004 או \u0003מגיהה — אם כוון לבו\u0004 כדי לצאת ידי חובה \u0003יצא.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי דקא\u0004 \u0005[אם\u0006 מדובר \u0005שהוא]\u0006 \u0003מסדר פסוקא פסוקא\u0004 \u0005[פסוק פסוק]\u0006 בעל פה וקוראו \u0003ו\u0004אחר כך \u0003כתב לה\u0004 \u0005[כותב\u0006 הוא \u0005אותה],\u0006 אם כן \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003כוון לבו מאי הוי\u0004 \u0005[מה היה\u0006 בכך\u0005]?\u0006 הלא קורא \u0003על פה הוא! אלא\u0004 צריך לומר \u0003דכתב פסוקא פסוקא וקרי ליה\u0004 \u0005[ש\u0006הוא \u0005כותב פסוק פסוק\u0006 במגילה ואחר כך \u0005קורא אותו],\u0006","אבל גם אז \u0003ומי יצא\u0004 \u0005[והאם\u0006 כך הוא \u0005יוצא]\u0006 ידי חובה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' חלבו אמר רב חמא בר גוריא אמר רב: הלכה כדברי האומר\u0004 שקוראים את המגילה \u0003כולה. ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שקוראים רק מ\u0003\"איש יהודי\"\u0004 (אסתר ב, ה) ואילך, בכל זאת \u0003צריכה שתהיה כתובה כולה,\u0004 וכיצד אפשר לומר שיוצא בקריאת מגילה שלא נכתבה עוד?","\u0003אלא\u0004 צריך לומר כך: \u0003דמנחה\u0004 \u0005[שמונחת]\u0006 \u0003מגילה\u0004 שלימה \u0003קמיה\u0004 \u0005[לפניו]\u0006 \u0003וקרי לה מינה פסוקא פסוקא וכתב לה\u0004 \u0005[וקורא\u0006 הוא \u0005ממנה פסוק פסוק וכותב אותה].\u0006 ומציעים: \u0003לימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 שפירוש זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004מה שאמר \u0003רבה בר בר חנה,\u0004 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: אסור לכתוב\u0004 אפילו \u0003אות אחת\u0004 בכתבי הקודש \u0003שלא מן הכתב,\u0004 ומכאן ראיה שכך עושים. ודוחים: אין זו ראיה, \u0003דלמא דאתרמי ליה אתרמויי\u0004 \u0005[שמא\u0006 מדובר \u0005ש\u0006רק \u0005הזדמנה לו הזדמנות]\u0006 ואולי אכן מותר לכתוב את כולה בעל פה, ובברייתא מדובר כשהזדמן שהעתיק ממגילה כתובה.","ואגב כך דנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה, \u0003אמר רבה בר בר חנה אמר ר' יוחנן: אסור לכתוב אות אחת שלא מן הכתב, מיתיבי\u0004 \u0005[\u0006ו\u0005מקשים]\u0006 על כך: \u0003אמר ר' שמעון בן אלעזר: מעשה בר' מאיר שהלך לעבר שנה בעסיא\u0004 (באסיה הקטנה) שמפני הגזירות לא יכלו לעבר בארץ ישראל, ועשה זאת במקום אחר. \u0003ולא היתה שם מגילה וכתבה מלבו\u0004 (בעל פה) — \u0003וקראה!\u0004","\u0003אמר ר' אבהו: שאני\u0004 \u0005[שונה]\u0006 \u0003ר' מאיר דמיקיים ביה\u0004 \u0005[שהתקיים בו]\u0006 מה שנאמר: \u0003\"ועפעפיך יישרו נגדך\"\u0004 (משלי ד, כה), ועל פסוק זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא לר' ירמיה מדפתי: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ועפעפיך יישרו נגדך\"? אמר לו: אלה דברי תורה\u0004 שקשה מאוד לזכרם על בוריים \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"התעיף עיניך בו ואיננו\"\u0004 (משלי כג, ה) \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003מיושרין הן אצל ר' מאיר\u0004 שהוא ידע את הכל בשלימות בעל פה.","מסופר: \u0003רב חסדא אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב חננאל דהוה כתב\u0004 \u0005[שהיה כותב]\u0006 \u0003ספרים\u0004 (ספרי תורה) \u0003שלא מן הכתב\u0004 שכן ידע את כולה בעל פה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ראויה כל התורה כולה להכתב על פיך, אלא כך אמרו חכמים: אסור לכתוב\u0004 אפילו \u0003אות אחת שלא מן הכתב.\u0004 ושואלים: \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003כל התורה כולה ראויה שתיכתב על פיך — מכלל דמיושרין הן אצלו,\u0004 שהיה רב חסדא בטוח שרב חננאל ידע את הכל בעל פה במלוא הבקיאות, ואם כן \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' מאיר כתב\u0004 שלא מן הכתב? ומשיבים: \u0003שעת הדחק שאני\u0004 \u0005[שונה],\u0006 שכיון שלא היתה שם מגילה כלל אפשר היה לסמוך על בקיאותו, אבל לכתחילה אין עושים כן.","מסופר, כי \u0003אביי שרא\u0004 \u0005[התיר]\u0006 \u0003לדבי בר חבו\u0004 \u0005[לבית בן חבו]\u0006 שהיתה אומנותם בייצור תפילין ומזוזות \u0003למיכתב\u0004 \u0005[לכתוב]\u0006 \u0003תפלין ומזוזות שלא מן הכתב.\u0004 ושואלים: דעתו זו \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 ומסבירים: \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' ירמיה אומר משום רבינו\u0004 (הוא רבי יהודה הנשיא): \u0003תפלין ומזוזות נכתבות שלא מן הכתב, ואין צריכות שרטוט\u0004 שורות על הקלף לפני כתיבתן.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 כך היא: \u0003תפלין אין צריכין שרטוט\u0004 לפני הכתיבה, אולם \u0003מזוזות צריכין שרטוט. אידי ואידי\u0004 \u0005[אלו ואלו]\u0006 יכולות שתהיינה \u0003נכתבות שלא מן הכתב. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מיגרס גריסין\u0004 \u0005[גרוסות\u0006 הן\u0005]\u0006 בפי הכל, והסופרים יודעים אותן יפה, ולכן מותר לכותבן אפילו בעל פה.","נאמר במשנה שאם \u0003היתה כתובה בסם,\u0004 בסיקרא וגו' — לא יצא ידי חובה. ומסבירים את המילים: \u0003\"סם\"\u0004 הוא הקרוי בארמית \u0003סמא\u0004 (ארסן, זרניך), \u0003\"סקרא\" — אמר רבה בר בר חנה: סקרתא שמה\u0004 בארמית, מין צבע אדום, \u0003\"קומוס\"\u0004 — הוא הקרוא \u0003קומא\u0004 (שרף היוצא מן העץ)."],["\u0003\"קנקנתום\" —\u0004 הוא הקרוי \u0003חרתא דאושכפי\u0004 \u0005[צבע שחור של סנדלים]\u0006 \u0003\"דיפתרא\"\u0004 הוא עור \u0003דמליח וקמיח ולא עפיץ\u0004 \u0005[ש\u0006עיבד אותו ב\u0005מלח ו\u0006ב\u0005קמח ולא\u0006 ב\u0005עפצים],\u0006 \u0003\"נייר\"\u0004 — הוא בארמית \u0003מחקא,\u0004 נייר העשוי מגומא.","שנינו במשנה שהמגילה אינה כשרה \u0003עד שתהא כתובה אשורית,\u0004 ומסבירים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ככתבם וכזמנם\"\u0004 (אסתר ט, כז) — משמע ככתבו של עם ישראל.","נאמר במשנה שמגילה נכתבת \u0003\"על הספר ובדיו\",\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דין זה? ומשיבים: \u0003אתיא\u0004 \u0005[בא]\u0006 נלמד בגזירה שווה של המילים \u0003\"כתיבה\" \"כתיבה\", כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 במגילה: \u0003\"ותכתב אסתר המלכה\u0004 בת אביחיל ומרדכי היהודי את כל תוקף לקיים את אגרת הפורים הזאת\u0003\"\u0004 (אסתר ט, כט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ויאמר להם ברוך מפיו יקרא אלי את כל הדברים האלה ואני כתב על הספר בדיו\"\u0004 (ירמיהו לו, יח), משמע שכתיבה שלימה היא על הספר ובדיו דווקא.","\u0003בן עיר שהלך לכרך\u0004 שקוראים בו מגילה בחמישה עשר באדר, ולהיפך: \u0003בן כרך שהלך לעיר\u0004 שקוראים בה בארבעה עשר, \u0003אם עתיד לחזור למקומו\u0004 בפורים — \u0003קורא כמקומו, ואם לאו\u0004 \u0005[לא],\u0006 שאיננו עתיד לחזור למקומו בפורים \u0003קורא עמהן\u0004 עם בני המקום שהוא נמצא בו.","\u0003ומהיכן קורא אדם את המגילה ויוצא בה ידי חובתו? ר' מאיר אומר:\u0004 קורא את \u0003כולה. ר' יהודה אומר:\u0004 קורא רק \u0003מ\"איש יהודי\"\u0004 (אסתר ב, ה). \u0003ר' יוסי אומר:\u0004 קורא \u0003מ\"אחר הדברים האלה\"\u0004 (אסתר ג, א).","\u0003אמר רבא:\u0004 מה שאמרנו שהעתיד לחזור קורא כמקומו, \u0003לא שנו\u0004 כן \u0003אלא שעתיד לחזור בלילי ארבעה עשר, אבל\u0004 אם \u0003אין עתיד לחזור בלילי ארבעה עשר\u0004 אף שבכלל דעתו לחזור למקומו — \u0003קורא עמהן. אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את הלכתי זו? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"על כן היהודים הפרזים הישבים בערי הפרזות\u0004 עושים את יום ארבעה עשר...\u0003\"\u0004 (אסתר ט, יט), \u0003מכדי כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"היהודים הפרזים\",\u0004 ואם כן \u0003למה לי למיכתב\u0004 \u0005[לו לכתוב]\u0006 עוד \u0003\"הישבים בערי הפרזות\"?\u0004 אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 שה\u0003פרוז בן יומו,\u0004 כלומר, מי שהוא עתה יושב בעיר פרוזה אף על פי שמקומו הקבוע הוא בעיר שאינה כזו \u0003נקרא\u0004 גם הוא \u0003פרוז.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיה לגבי אדם שהוא בדרך כלל מוקף ולעת עתה הוא \u0003פרוז,\u0004 אולם זה שהוא בדרך כלל פרוז ורק עתה הוא \u0003מוקף מנא לן\u0004 \u0005[מנין לנו]\u0006 שכן דינו? ומשיבים: \u0003סברא הוא, מ\u0004כיון שה\u0003פרוז בן יומו קרוי פרוז,\u0004 כך גם \u0003מוקף בן יומו קרוי מוקף.\u0004","\u0003ואמר רבא: בן כפר,\u0004 שלמדנו במשנה הראשונה במסכת שזמן קריאתו הוא ביום שני או חמישי לפני פורים \u0003שהלך לעיר, בין כך ובין כך,\u0004 בין שעתיד לחזור ובין שאינו עתיד לחזור — \u0003קורא עמהן,\u0004 עם בני העיר. אף שכבר הקדים וקרא במקומו ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא משנה תמיד ממנהג מקומו? ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 בן הכפר \u0003כבני העיר בעי למקרי\u0004 \u0005[\u0006היה \u0005צריך לקרוא],\u0006 אלא \u0003ורבנן הוא דאקילו\u0004 \u0005[וחכמים הם שהקלו]\u0006 \u0003על\u0004 בני \u0003הכפרים\u0004 להקדים קריאתם \u0003כדי שיספקו מים ומזון לאחיהם שבכרכין,\u0004 אולם \u0003הני מילי כי איתיה בדוכתיה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005כאשר ישנו\u0006 בן הכפר \u0005במקומו],\u0006 \u0003אבל כי איתיה\u0004 \u0005[כאשר\u0006 הוא \u0005נמצא]\u0006 \u0003בעיר\u0004 — \u0003כבני\u0004 ה\u0003עיר בעי למקרי\u0004 \u0005[צריך\u0006 הוא \u0005לקרוא]\u0006 ולא כבני הכפר, וחוזר לעיקר דינו, ככתוב במגילה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003בן כרך שהלך לעיר\u0004 — \u0003בין כך ובין כך קורא כמקומו,\u0004 ותחילה יש לתקן את הגרסה: \u0003בן כרך סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 שתמיד קורא כמקומו?! הלא \u0003באם עתיד לחזור תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 כבמשנתנו, וברור איפוא שיש לתקן את הברייתא, \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 צריך לגרוס \u0003בן כפר,\u0004 ואם כן משמע מברייתא זו שהוא קורא כמקומו, ולא כדברי רבא!","ודוחים: \u0003ולאו תרוצי מתרצת\u0004 \u0005[ו\u0006כי \u0005לא מיישב\u0006 ומתקן \u0005אתה]\u0006 את הברייתא? שהרי על כורחך חייב אתה לשנות את גירסתה, וכיוון שכך תקן עוד, ו\u0003תני\u0004 \u0005[שנה]\u0006 בה: \u0003קורא עמהם,\u0004 ואז תהא הברייתא כדברי רבא.","נאמר במשנה שנחלקו חכמים \u0003מהיכן קורא אדם את המגילה. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחאי אומר:\u0004 שמתחילים לקרוא \u0003מ\"בלילה ההוא\"\u0004 (אסתר ו, א).","\u0003אמר ר' יוחנן: וכולן,\u0004 כל התנאים הללו \u0003מקרא אחד דרשו,\u0004 אלא שהוציאו ממנו מסקנות שונות, שכן נאמר: \u0003\"ותכתב אסתר המלכה\u0004 בת אביחיל \u0003ומרדכי היהודי את כל תקף\"\u0004 (אסתר ט, כט) והחכמים נחלקו בהבנת הביטוי \"כל תוקף\" \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שקוראים את המגילה \u0003כולה\u0004 מפרש ש\"כל תוקף\" הוא \u0003תוקפו של אחשורוש\u0004 ולכן צריכים לקרוא מתחילתה, שמשם מסופר דבר תוקפו של אחשורוש.","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מ\"איש יהודי\",\u0004 מפרש שהוא \u0003תוקפו של מרדכי. ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שקוראים \u0003מ\"אחר הדברים האלה\",\u0004 מפרש שהוא \u0003תוקפו של המן, ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 \u0003מ\"בלילה ההוא\" — תוקפו של נס,\u0004 ומכיון שתחילת הנס באותו לילה בו נדדה שנתו של אחשורוש, על כן יש להתחיל לקוראה משם.","\u0003רב הונא אמר: מהכא\u0004 \u0005[מכאן],\u0006 על פסוק זה מתבססת המחלוקת, נאמר: \u0003\"ומה ראו על ככה ומה הגיע אליהם\"\u0004 (אסתר ט, כו),","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שקוראים את המגילה \u0003כולה,\u0004 מפרש את הכתוב כך: \u0003מה ראה אחשורוש שנשתמש בכלים של בית המקדש\u0004 — \u0003\"על ככה\",\u0004 והוא \u0003משום דחשיב שבעין שנין\u0004 \u0005[שחישב שבעים שנה]\u0006 לגלות בבל \u0003ולא איפרוק\u0004 \u0005[נגאלו]\u0006 ישראל, ובשל כך חשב שאין להם תקומה. \u0003\"ומה הגיע אליהם\"? דקטל\u0004 \u0005[שהרג]\u0006 את \u0003ושתי,\u0004 ומכיון שהמגילה נכתבה ונקראת כדי להודיע לדורות הבאים על כל מהלך הדברים שהביאו לכל זה ועל אחריתם של המעורבים בו ודברים אלה מפורשים בחלקם בתחילתה של המגילה, לכך יש לקרוא את כולה.","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מ\"איש יהודי\"\u0004 כך יש להבין: \u0003\"מה ראה\" מרדכי דאיקני\u0004 \u0005[שהתקנא,\u0006 שגרם שתבער הקנאה\u0005]\u0006 \u0003בהמן\u0004 וגרם לו שנאה זו? \u0003\"על ככה\",\u0004 משום \u0003דשוי נפשיה\u0004 \u0005[שעשה\u0006 המן את \u0005עצמו]\u0006 כ\u0003עבודה זרה, \"ומה הגיע אליהם\" — דאתרחיש ניסא\u0004 \u0005[שאירע הנס].\u0006 ולכך יש לקוראה לדעה זו מ\"איש יהודי\".","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שקוראים \u0003מ\"אחר הדברים האלה\",\u0004 כך הבין: \u0003מה ראה המן שנתקנא בכל היהודים — \"על ככה\" — משום\u0004 ש\u0003\"מרדכי לא יכרע ולא ישתחוה\"\u0004 (אסתר ג, ב), \u0003\"ומה הגיע אליהם\"\u0004 (אסתר ט, כו) — \u0003\"ותלו אתו ואת בניו על העץ\"\u0004 (אסתר ט, כה), ולכך יש לדבריו לקרוא מהמקום בו מוזכר המן לראשונה.","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מ\"בלילה ההוא\",\u0004 כך הוא מפרש: \u0003מה ראה אחשורוש להביא את ספר הזכרונות?\u0004 הסיבה היא \u0003\"על ככה\" — דזמינתיה\u0004 \u0005[שהזמינה אותו]\u0006 \u0003אסתר\u0004 את \u0003המן בהדיה\u0004 \u0005[אתו],\u0006 \u0003\"ומה הגיע אליהם\" — דאתרחיש ניסא\u0004 \u0005[שאירע הנס],\u0006 ולכך יש להתחיל לקרוא מהמקום בו מוזכרת התחלת הנס.","\u0003אמר ר' חלבו אמר רב חמא בר גוריא אמר רב: הלכה כדברי האומר\u0004 שקוראים את המגילה \u0003כולה.\u0004 ועוד: \u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שקוראים רק \u0003מ\"איש יהודי\"\u0004 — בכל זאת \u0003צריכה שתהא\u0004 המגילה \u0003כתובה כולה.\u0004","\u0003ואמר\u0004 עוד \u0003ר' חלבו אמר רב חמא בר גוריא אמר רב\u0004 בענין מגילה: \u0003מגילה נקראת \"ספר\"\u0004 (אסתר ט, לב) \u0003ונקראת \"אגרת\"\u0004 (אסתר ט, כט) ללמדנו: \u0003נקראת \"ספר\" — שאם תפרה\u0004 (חיבר את יריעות הקלף שלה) \u0003בחוטי פשתן — פסולה,\u0004 כשם שספר תורה שנתפר כך פסול. \u0003ונקראת \"אגרת\" — שאם הטיל בה\u0004 בתפריה \u0003שלשה חוטי גידין\u0004 שבהם תופרים ספרי תורה, אולם אינו אלא תפירה חלקית כשל אגרת — \u0003כשרה,\u0004 ואין צריך לתפור את היריעה בשלימות כבספר תורה. \u0003אמר רב נחמן: ובלבד שיהו משולשין,\u0004 כלומר, שהתפרים יהיו במרחק שוה זה מזה.","\u0003אמר רב יהודה אמר שמואל: הקורא במגילה הכתובה בין הכתובים\u0004 האחרים — \u0003לא יצא,\u0004 שצריך שתהיה מגילה בפני עצמה, כדי שיהא ניכר שהוא קורא אגרת מיוחדת זו. \u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 איסור זה \u0003אלא\u0004 כשהיריעה שעליה כתובה המגילה \u0003לא מחסרא ומייתרא פורתא\u0004 \u0005[חסרה,\u0006 קצרה \u0005או יתירה,\u0006 ארוכה \u0005מעט]\u0006 מהיריעות של שאר הכתובים ואיננה ניכרת ביניהם, \u0003אבל מחסרא ומייתרא פורתא\u0004 \u0005[חסרה או יתירה מעט]\u0006 בגודל \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור ורשאי לקרות בה, לפי שהדבר ניכר.","מסופר: \u0003לוי בר שמואל הוה קא קרי קמיה\u0004 \u0005[היה קורא לפני]\u0006 \u0003רב יהודה במגילה\u0004"],["\u0003הכתובה בין הכתובים. אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003הרי אמרו: הקורא במגילה הכתובה בין הכתובים לא יצא.\u0004","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הקורא במגילה הכתובה בין הכתובים לא יצא.\u0004 אבל \u0003ומחו לה אמוחא\u0004 \u0005[והכו אותה\u0006 את ההלכה הזו \u0005על ראשה],\u0006 כלומר, אחרי שאמרו אותה מיד סייגו אותה סייג גדול שמוציא ממנה רוב תוקפה: \u0003בצבור שנו,\u0004 שהיחיד רשאי לקרוא גם כשהיא עם שאר כתובים, ורק כשקוראים אותה בציבור אל יקרא בה אלא אם היא כתובה בנפרד.","ובדומה לזה, \u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: שיור התפר\u0004 כלומר ההלכה שאין תופרים את היריעות בספר התורה עד קצה הדף אלא משאירים משהו — \u0003הלכה למשה מסיני, ומחו לה אמוחא\u0004 \u0005[והכו אותה\u0006 את ההלכה הזו \u0005על ראשה],\u0006 כלומר, מיד סייגו את ההלכה, והסבירו שאין בכך טעם שבקדושה \u0003ולא אמרו\u0004 שיש לעשות כן \u0003אלא כדי שלא יקרע\u0004 הדף שאם יזדמן שימשכו את הספר בחזקה ייפרם התפר בין הדפים, ולא הדף עצמו.","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: אלמלי\u0004 (אילו) \u0003נשתייר במערה שעמד בה משה\u0004 (\"ושמתיך בנקרת הצור\". שמות לג, כב) \u0003ואליהו\u0004 (\"ויבוא שם אל המערה... והנה ה' עובר\". מלכים א' יט, ט-יא) בשעה שנתגלתה להם שכינה אפילו \u0003כמלא נקב\u0004 של \u0003מחט סדקית\u0004 (מחט קטנה המיועדת לתפירת בגדים), \u0003לא היו יכולים לעמוד\u0004 ולהישאר חיים \u0003מפני האורה, שנאמר: \"כי לא יראני האדם וחי\"\u0004 (שמות לג, כ).","\u0003ואמר ר' חייא בר אבא אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו\u0006 \u0005שנאמר]:\u0006 \u0003\"\u0004ויתן ה' אלי את שני לוחות האבנים כתובים באצבע אלהים \u0003ועליהם ככל הדברים אשר דבר ה' עמכם בהר\"\u0004 (דברים ט, י) — \u0003מלמד שהראהו הקדוש ברוך הוא למשה\u0004 בהר גם \u0003דקדוקי תורה ודקדוקי סופרים\u0004 שעתידים לדקדק ולעיין בה \u0003ו\u0004גם \u0003מה שהסופרים עתידים לחדש, ומאי ניהו\u0004 \u0005[ומה הוא]\u0006 הדבר שהסופרים (חכמים) עתידים לחדש? הוא \u0003מקרא מגילה.\u0004","\u0003הכל כשרין לקרות את המגילה — חוץ מחרש שוטה וקטן, ר' יהודה מכשיר בקטן.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 שסבור כי \u0003חרש\u0004 אפילו ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יקרא? \u0003אמר רב מתנה:\u0004 שיטת \u0003ר' יוסי היא, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הקורא את שמע\u0004 בלחש \u0003ולא השמיע לאזנו — יצא, ר' יוסי אומר: לא יצא,\u0004 משמע שמי שאינו שומע אינו יוצא.","ושואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 יודע אתה שמשנתנו הפוסלת בחרש, כשיטת \u0003ר' יוסי היא,\u0004 ואתה מפרש אותה שאפילו ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יצא, \u0003דלמא\u0004 \u0005[שמא]\u0006 משנתנו כשיטת \u0003ר' יהודה\u0004 היא, \u0003ו\u0004יש להבינה כי \u0003לכתחלה הוא שלא\u0004 יקרא החרש, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003דיעבד,\u0004 שכבר קראה — \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 כשר הדבר\u0005]?\u0006","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה\u0006 הדבר \u0005על דעתך],\u0006 \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 במשנה: \u0003חרש דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שוטה וקטן,\u0004 ומצירוף הדברים יש להבין: \u0003מה שוטה וקטן\u0004 אם קראו \u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יצאו, \u0003אף חרש\u0004 אם קרא, \u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יצא.","ומקשים: \u0003ודלמא הא כדאיתא והא כדאיתא\u0004 \u0005[ושמא זה כמות שהוא וזה כמות שהוא],\u0006 שאף ששנה את כולם יחד הרי זה מפני שאסורים לקרוא לכתחילה, אבל יש ביניהם הבדל בדיעבד, ולכל אחד מהם דין לעצמו! ודוחים: אי אפשר לומר כן, שסתם משנתנו כר' יהודה היא, כי \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה בסופה]:\u0006 \u0003ר' יהודה מכשיר בקטן — מכלל\u0004 הדברים אתה למד \u0003דרישא לאו\u0004 \u0005[שראשה\u0006 של המשנה \u0005לא]\u0006 כשיטת \u0003ר' יהודה היא.\u0004","ומקשים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 כל המשנה \u0003כולה\u0004 שיטת \u0003ר' יהודה היא,\u0004 ויש להבין אותה כהמשך אחד, אלא שקודם נאמרו דברי המשנה בסתם, ובסופה מפורש שהם דברי ר' יהודה. ודוחים: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה],\u0006 הלא \u0003רישא — לפסולה, וסיפא — לכשירה\u0004 \u0005[ראשה\u0006 של המשנה בא \u0005לפסול וסופה\u0006 בא \u0005להכשיר]\u0006 ואי אפשר לקרוא דברים מנוגדים כהמשך אחד.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 כל המשנה \u0003כולה\u0004 כשיטת \u0003ר' יהודה היא ותרי גווני\u0004 \u0005[ושני מיני]\u0006 \u0003קטן קתני לה\u0004 \u0005[שנה בה]\u0006 \u0003וחסורי מיחסרא והכי קתני\u0004 \u0005[וחסרה\u0006 המשנה, \u0005וכך\u0006 יש \u0005לשנותה],\u0006 כלומר, יש להוסיף בה פרט קטן. ואז תוכל להיקרא כך: \u0003הכל כשרין לקרות את המגילה חוץ מחרש שוטה וקטן, במה דברים אמורים — בקטן שלא הגיע לחינוך\u0004 ואין מצוות שייכות בו, \u0003אבל בקטן שהגיע לחינוך\u0004 (שהוא בן תשע או בן עשר. ראה יומא פב, א), \u0003אפילו לכתחלה\u0004 רשאי לקרות, \u0003שר' יהודה מכשיר בקטן\u0004 שהגיע לחינוך.","ומקשים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 את משנתנו — \u0003כ\u0004שיטת \u0003ר' יהודה,\u0004 ושיטתו היא איפוא שחרש פסול לכתחילה וכשר \u0003בדיעבד.\u0004","\u0003אלא הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי\u0004 ברייתא זו: \u0003חרש המדבר ואינו שומע — תורם\u0004 תרומה אפילו \u0003לכתחלה,\u0004 אף שהוא צריך לברך ואינו שומע את הברכה, ונברר \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 הלכה זו? \u0003אי\u0004 \u0005[אם]\u0006 תאמר כשיטת \u0003ר' יהודה,\u0004 הלא הסברת את משנתנו לשיטתו, ולפיה חרש \u0003דיעבד — אין\u0004 \u0005[כן]\u0006 \u0003לכתחלה — לא,\u0004 ו\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 לשיטת \u0003ר' יוסי\u0004 — הרי לשיטתו אפילו \u0003בדיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא.\u0004 ואם כן מי הוא החכם המתיר בחרש לכתחילה?","את הקושיה הזו דוחים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 רצונך לומר — שמשנתנו כר' יוסי, ולשיטה זו \u0003ר' יהודה\u0004 מתיר בחרש \u0003ואפילו לכתחלה,\u0004 ור' יוסי אוסר בחרש אפילו בדיעבד? \u0003אלא הא דתניא\u0004 \u0005[\u0006ברייתא \u0005זו ששנינו]\u0006 בה: \u0003לא יברך אדם ברכת המזון בלבו\u0004 בלי להוציא קול מפיו, \u0003ואם בירך — יצא,\u0004 אם כן זו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003ר' יהודה ולא\u0004 כשיטת \u0003ר' יוסי,\u0004 כי \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה\u0004 היא, הלא הוא מתיר \u0003אפילו לכתחלה, אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 כשיטת \u0003ר' יוסי\u0004 היא, הוא \u0003אפילו דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 מתיר!"],["ומשיבים: \u0003לעולם\u0004 תפרש שהברייתא שאמר ר' יהודה בן ר' שמעון בן פזי כדעת \u0003ר' יהודה\u0004 היא, \u0003ואפילו לכתחילה\u0004 מתיר הוא בחרש, ומשנתנו כדעת ר' יוסי. \u0003ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 מי הוא התנא המתיר חרש בברכת המזון רק בדיעבד, כי גם זו אמר ר' יהודה, אלא \u0003הא\u0004 \u0005[זו]\u0006 המתירה לגמרי — \u0003דידיה\u0004 \u0005[\u0006דעתו \u0005שלו]\u0006 היא, \u0003והא\u0004 \u0005[וזו]\u0006 שמתירה רק בדיעבד — \u0003דרביה\u0004 \u0005[של רבו]\u0006 היא, האוסר לכתחילה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003ר' אלעזר בן עזריה: הקורא את שמע צריך שישמיע לאזנו, שנאמר: \"שמע ישראל ה' אלהינו ה' אחד\"\u0004 (דברים ו, ד), וכוונתו: \u0003השמע לאזניך מה שאתה מוציא מפיך.\u0004 הרי לנו שיטת ר' אלעזר בן עזריה שלכתחילה צריך להשמיע לאזנו. \u0003ר' מאיר אומר:\u0004 אינו צריך, שכן נאמר שם: \u0003\"אשר אנכי מצוך היום על לבבך\"\u0004 (דברים ו, ו), לומר: \u0003אחר כוונת הלב הן הן הדברים,\u0004 ואין צורך באמירה בפה.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 ומצויה בפנינו הברייתא האחרונה — \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ש\u0003ר' יהודה כרביה סבירא ליה\u0004 \u0005[כ\u0006שיטת \u0005רבו סבור הוא],\u0006 שחרש לכתחילה פסול ובדיעבד כשר. \u0003והא דתני\u0004 \u0005[וזו ששנה]\u0006 \u0003יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי\u0004 שמתיר בחרש אפילו לכתחילה, היא כשיטה הנוספת שמצאנו בברייתא — שיטת \u0003ר' מאיר היא,\u0004 שלדעתו הכל תלוי בכוונה ויש להתיר אף לכתחילה.","שנינו במשנה: \u0003ר' יהודה מכשיר בקטן. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה\u0004 ראיה לדבריו: \u0003קטן הייתי וקריתיה\u0004 (קראתי את המגילה) \u0003למעלה\u0004 (בפני) \u0003ר' טרפון וזקנים בלוד. אמרו לו: אין מביאים ראיה מן הקטן,\u0004 שהרי לדבריך קטן היית אז, ובאותה שעה לא יכולת להעיד כלל.","\u0003תניא\u0004 \u0005[שנויה ברייתא]\u0006 אחרת, \u0003אמר רבי: קטן הייתי וקריתיה למעלה\u0004 (בפני) \u0003מר' יהודה, אמרו לו: אין מביאין ראיה מן המתיר,\u0004 שהרי יודעים אנו, שר' יהודה מכשיר בקטן, ואין להביא ראיה להלכה ממה שעשה כך.","ושואלים: \u0003ולימרו ליה\u0004 \u0005[ושיאמרו לו]\u0006 כשם שאמרו לר' יהודה \u0003אין מביאים ראיה מן הקטן!\u0004 ומשיבים: תשובה \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003ועוד\u0004 אחרת \u0003קאמרו ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 שהלא \u0003קטן היית\u0004 באותה שעה ולא היית ראוי להעיד, \u0003ועוד: אפילו\u0004 אם באותו זמן \u0003גדול היית\u0004 והיית מעיד שראית שקרא בפניהם קטן אחר — \u0003אין מביאין ראיה מן המתיר.\u0004","\u0003אין קורין את המגילה, ולא מלין\u0004 את התינוק \u0003ולא טובלין\u0004 בכל טבילת מצוה \u0003ולא מזין\u0004 מי חטאת לטהר מטומאת המת, אלא ביום. \u0003וכן שומרת יום כנגד יום,\u0004 כלומר, אישה שראתה דם נדה יום אחד שלא בזמן ווסתה, שממתינה (\"שומרת\") יום טהור כנגד היום שראתה, ובסופו טובלת והיא טהורה — אף היא \u0003לא תטבול עד שתנץ החמה\u0004 ולא בלילה. ומוסיפים: \u0003וכולן\u0004 כל הדברים הללו שאמרנו שמצוותם ביום, אם \u0003עשו משעלה עמוד השחר — כשר\u0004 שאף זה נחשב כיום לענין זה.","שנינו במשנה שקורין את המגילה רק ביום, ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דין זה? ומשיבים: ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"והימים האלה נזכרים ונעשים\"\u0004 (אסתר ט, כח), משמע: \u0003ביום\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בלילה — לא.\u0004 ושואלים: \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר שתהא\u0006 זו \u0005קושיה חמורה]\u0006 על שיטת \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: חייב אדם לקרות את המגילה בלילה ולשנותה ביום,\u0004 ואילו במשנה שנינו שאין קוראים אותה אלא ביום! ודוחים: מכאן אין הוכחה, \u0003כי קתני אדיום\u0004 \u0005[כאשר שנינו\u0006 במשנה, הרי הוא \u0005על\u0006 קריאת \u0005היום],\u0006 ולא נדון כלל דין קריאתה בלילה.","שנינו במשנה: \u0003ולא מלין\u0004 בלילה. ומנין נלמד דין זה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וביום השמיני ימול\"\u0004 (ויקרא יב, ג).","עוד שנינו במשנה: \u0003ולא טובלין ולא מזין\u0004 אלא ביום, ודבר זה נלמד ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והזה הטהר על הטמא\u0004 ביום השלישי וביום השביעי וחיטאו \u0003ביום השביעי\u0004 וכיבס בגדיו ורחץ במים וטהר בערב\u0003\"\u0004 (במדבר יט, יט), משמע: ביום ולא בלילה, \u0003ו\u0004לגבי טבילה \u0003איתקש\u0004 \u0005[הוקשה,\u0006 הושוותה\u0005]\u0006 בכתוב \u0003טבילה להזיה\u0004 (שהרי נאמר באותו כתוב גם \"ורחץ במים\") ואם כן מה שאינו כשר בהזיה, אף אינו כשר בטבילה.","שנינו במשנה: \u0003וכן שומרת יום כנגד יום לא תטבול עד שתנץ החמה.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]!\u0006 \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003שומרת יום כנגד יום מכל\u0004 שאר \u0003חייבי טבילות,\u0004 והרי נאמר כבר שאין טובלים אלא ביום!","ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003תיהוי\u0004 \u0005[תהיה]\u0006 ראיית דם זו נדונה \u0003כראיה ראשונה\u0004 בפעם ראשונה \u0003של\u0004 זיבה שרואה ה\u0003זב,\u0004 שהרי איננו נטמא בה טומאה גמורה, ורק אם יראה שלוש פעמים — הריהו זב גמור, וכן אם תראה האשה דם שלושה ימים — הריהי זבה, \u0003וראיה ראשונה של זב איתקש\u0004 \u0005[הוקשה\u0006 הושוותה\u0005]\u0006 בכתוב \u0003לבעל קרי, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת תורת הזב ואשר תצא ממנו שכבת זרע\"\u0004 (ויקרא טו, לב), ונלמד מכאן: \u0003מה בעל קרי טובל ביום\u0004 בו ראה קרי \u0003האי נמי ליטבול ביומיה\u0004 \u0005[זה,\u0006 הזב, \u0005גם כן\u0006 \u0005יטבול ביומו],\u0006 באותו יום עצמו שהיתה הטומאה,","\u0003והא\u0004 \u0005[וזו]\u0006 שומרת יום כנגד יום \u0003ביממא לא מצי טבלה\u0004 \u0005[ביום איננה יכולה לטבול],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כל ימי זובה כמשכב נדתה יהיה לה\"\u0004 (ויקרא טו, כו), שכל אותו יום כולו שוה לטומאה, ולכן בו ביום אינה יכולה לטבול, אבל \u0003בליליא מיהת ליעביד\u0004 \u0005[בלילה על כל פנים שתעשה]\u0006 \u0003מקצת שימור,\u0004 כלומר, תבדוק שהיא טהורה בלילה, \u0003ותטבול\u0004 מיד בלילה ולא תמתין יום נוסף, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במשנה כי \u0003כיון דבעיא\u0004 \u0005[ש\u0006היא \u0005צריכה]\u0006 \u0003ספירה,\u0004 שכן בטומאה זו כשראתה דם יום אחד צריכה לספור יום אחד של טהרה —"],["\u0003ספירה\u0004 זו \u0003ביממא\u0004 \u0005[ביום]\u0006 בלבד \u0003היא\u0004 ולא בלילה כאמור \"וספרה לה שבעת ימים\" (ויקרא טו, כח).","שנינו במשנה: \u0003וכולן שעשו משעלה עמוד השחר\u0004 — \u0003כשר.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שמעמוד השחר כבר נחשב יום? \u0003אמר רבא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ויקרא אלהים לאור יום\"\u0004 (בראשית א, ה), ופירושו: \u0003למאיר ובא קראו יום.\u0004 כלומר, \"אור\" כאן אינו שם עצם, אלא הוא כעין פועל, וכוונתו מה שמאיר והולך נקרא \"יום\", מכיון שמעמוד השחר הולך האור ומתרבה, הרי זה כבר קרוי \"יום\".","ומקשים: \u0003אלא מעתה\u0004 לפי הסבר זה, הכתוב \u0003\"ולחשך קרא לילה\"\u0004 (בראשית א, ה), תצטרך לפרש: \u0003למחשיך ובא קרא לילה?\u0004 ואם כן יחשב לילה כבר משעות שאחרי הצהרים, \u0003הא קיימא לן\u0004 \u0005[\u0006ו\u0005הרי מוחזק בידינו]\u0006 כי \u0003עד צאת הכוכבים לאו\u0004 \u0005[לא]\u0006 \u0003לילה הוא!\u0004 ואם כן בהכרח יש לפרש חושך ממש, ואף בענין אור אמור שהכוונה לאור ממש.","\u0003אלא אמר ר' זירא: מהכא\u0004 \u0005[מכאן]\u0006 אפשר ללמוד דבר זה, שנאמר: \u0003\"ואנחנו עשים במלאכה וחצים מחזיקים ברמחים מעלות השחר ועד צאת הכוכבים\"\u0004 (נחמיה ד, טו), \u0003ואומר\u0004 בפסוק אחר: \u0003\"והיו לנו הלילה משמר והיום מלאכה\"\u0004 (נחמיה ד, טז), הרי שכבר מעלות השחר נחשב הדבר כיום.","ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 הצורך בתוספת זו של \u0003ואומר,\u0004 מדוע הוצרך להביא ראיה מפסוק שני? אלא ודאי בא לדחות את השאלה האפשרית: \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בכלל ש\u0003משעלה עמוד השחר\u0004 עדיין \u0003לאו יממא\u0004 \u0005[איננו יום]\u0006 \u0003ומכי ערבא שמשא\u0004 \u0005[ומ\u0006שנוטה \u0005השמש לערוב]\u0006 \u0003ליליא\u0004 \u0005[לילה]\u0006 הוא, אלא \u0003ואינהו מקדמי ומחשכי\u0004 \u0005[והם\u0006 שהיו \u0005מקדימים ומחשיכים],\u0006 שהתחילו את העבודה עוד לפני היום והמשיכו אותה גם בלילה — \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר בפסוק השני \u0003\"והיו לנו הלילה משמר והיום מלאכה\",\u0004 ללמד שהזמן שעבדו בו — זמן היום הוא, ומכאן ראיה שכבר מעמוד השחר נקרא יום.","אף שמלכתחילה כל המצוות שזמנן ביום יש להשתדל להקדים את עשייתן לתחילתו (\"זריזין מקדימין\"), אולם אין זה אלא מלכתחילה, ומצד הדין כל היום כשר להם; \u0003כל היום כשר לקריאת המגילה ולקריאת ההלל ולתקיעת שופר\u0004 בראש השנה, \u0003ולנטילת לולב\u0004 בסוכות \u0003ולתפלת המוספין\u0004 בימי חג ומועד \u0003ול\u0004קרבנות ה\u0003מוספין\u0004 במקדש,","\u0003ולוידוי הפרים\u0004 שמתוודים בית דין או הכהן הגדול כאשר הם מביאים פר לכפר על שגגתם בהוראה, \u0003ולוידוי מעשר,\u0004 שחובה להתוודות בשנה השלישית לשמיטה ולומר שאכן הפריש את כל המעשר כראוי (ראה דברים כו, יב-טו) \u0003ולוידוי יום הכפורים,\u0004 שמתוודה הכהן הגדול על קרבנות היום.","\u0003לסמיכה\u0004 על הקרבנות, \u0003לשחיטה\u0004 של הקרבנות, \u0003לתנופה\u0004 של אותן מנחות הצריכות תנופה (הגבהה) במקדש, \u0003להגשה\u0004 של מנחות הצריכות הגשה (שמקריבים אותן) אל המזבח, \u0003לקמיצה\u0004 להוצאת קומץ מן המנחה כדי להקריבו, \u0003ולהקטרה\u0004 של הקומץ על המזבח, \u0003למליקה\u0004 (צוארו של קרבן העוף), \u0003ולקבלה\u0004 של דם הקרבן \u0003ולהזיה\u0004 של הדם על המזבח, ועל הפרוכת,","\u0003ולהשקית סוטה\u0004 במים המרים, \u0003ולעריפת העגלה\u0004 הערופה בנחל (ראה דברים כא, א-ט), \u0003לטהרת המצורע\u0004 בכל הדברים שצריך לעשות כדי לטהרו (ראה ויקרא כ, יד). ולעומת זאת דברים שזמנם בלילה — כל הלילה כשר להם.","וכגון: \u0003כל הלילה כשר לקצירת העומר\u0004 שמצוותו בלילה, \u0003ולהקטר\u0004 (שריפה על המזבח של) \u0003חלבים\u0004 של חטאת ושלמים וקרבנות נוספים שנזרק דמם ביום, \u0003ואברים\u0004 של קרבן עולה. ובדרך \u0003כלל\u0004: \u0003דבר שמצותו ביום — כשר כל היום, דבר שמצותו בלילה — כשר כל הלילה.\u0004","ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שמצוות אלה מצוותן ביום דווקא? לגבי מגילה — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והימים האלה נזכרים ונעשים\"\u0004 (אסתר ט, כח). \u0003ולקריאת ההלל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]:\u0006 \u0003\"ממזרח שמש עד מבואו\u0004 מהולל שם ה'\u0003\"\u0004 (תהלים קיג, ג). \u0003ר' יוסי אומר\u0004 הראיה היא ממה שנאמר בהלל: \u0003\"זה היום עשה ה'\"\u0004 (תהלים קיח, כד), משמע ביום ולא בלילה.","\u0003ולנטילת לולב — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקחתם לכם ביום הראשון\u0004 פרי עץ הדר כפות תמרים...\u0003\"\u0004 (ויקרא כג, מ). \u0003ולתקיעת שופר\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יום תרועה יהיה לכם\"\u0004 (במדבר כט, א). \u0003ולמוספין — דכתיב\u0004 \u0005[שנאמר]\u0006 בקרבנות המוספים במועדים: \u0003\"\u0004להקריב אשה לה' עולה ומנחה זבח ונסכים \u0003דבר יום ביומו\"\u0004 (ויקרא כג, לז). \u0003ול\u0004גבי \u0003תפלת המוספין\u0004 — הרי \u0003כ\u0004קרבנות \u0003מוספין שויוה רבנן\u0004 \u0005[עשו\u0006 \u0005אותה החכמים],\u0006 שתיקנו חכמים את תפילת המוסף כנגד קרבנות המוספים.","\u0003ולוידוי פרים — דיליף\u0004 \u0005[שלומד]\u0006 בגזירה שווה מן המילים \u0003'כפרה' 'כפרה' מיום הכפורים. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 ל\u0003גבי יום הכפורים:\u0004 נאמר שם \u0003\"וכפר בעדו ובעד ביתו\"\u0004 (ויקרא טז, יא), ואנחנו אומרים: \u0003בכפרת דברים הכתוב מדבר,\u0004 כלומר, אין הכתוב מדבר בכפרה שיש בהקרבת הקרבן ומתן דמו, אלא לוידוי שהוא הכפרה הנזכרת לענין זה. \u0003וכפרה\u0004 של יום הכיפורים הלא \u0003ביממא\u0004 \u0005[ביום]\u0006 \u0003הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004כי \u0003ביום הזה יכפר עליכם\"\u0004 (ויקרא טז, ל).","\u0003ולוידוי מעשר — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואמרת לפני ה' אלהיך בערתי הקדש מן הבית\"\u0004 (דברים כו, יג) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 נאמר: \u0003\"היום הזה ה' אלהיך מצוך\u0004 לעשות\u0003\"\u0004 (דברים כו, טז),","משמע: ביום ולא בלילה. \u0003לסמיכה ולשחיטה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וסמך\u0004 את ידו על ראש קרבנו \u0003ושחט\"\u0004 (ויקרא ג, ח), להשוות סמיכה לשחיטה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בה בשחיטה \"ביום זבחכם\"\u0004 (ויקרא יט, ו), משמע: ביום ולא בלילה. \u0003ולתנופה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ביום הניפכם את העמר\"\u0004 (ויקרא כג, יב).","\u0003ולהגשה\u0004 — משום \u0003דאיתקש\u0004 \u0005[שהוקשה,\u0006 הושוותה\u0005]\u0006 הגשה \u0003לתנופה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולקח הכהן מיד האשה את מנחת הקנאת והניף\u0004 את המנחה לפני ה' \u0003והקריב\u0004 אותה אל המזבח\u0003\"\u0004 (במדבר ה, כה), והקרבה היא הגשה. \u0003ולמליקה ולקמיצה ולהקטרה ולהזיה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \"זאת התורה לעולה למנחה ולחטאת ולאשם ולמילואים ולזבח השלמים. אשר ציוה ה' את משה בהר סיני \u0003ביום צותו את בני ישראל\u0004 להקריב את קרבניהם\" (ויקרא ז, לז-לח), ומכאן למדים שכל מעשי הקרבנות ביום הם.","\u0003ולהשקית סוטה\u0004 שכשרה ביום — \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003'תורה' 'תורה': כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בסוטה \u0003\"ועשה לה הכהן את כל התורה הזאת\"\u0004 (במדבר ה, ל), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 במקום אחר: \u0003\"על פי התורה אשר יורוך ועל המשפט\u0004 אשר יאמרו לך\u0003\"\u0004 (דברים יז, יא),"],["\u0003מה משפט\u0004 (דין) אינו נעשה אלא \u0003ביום\u0004 כפי שלמדנו, \u0003אף כאן\u0004 השקיית סוטה אינה נעשית אלא \u0003ביום.\u0004","\u0003ולעריפת העגלה\u0004 שהיא ביום, \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 לשון \u0003\"כפרה\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה, כ\u0004פי שנאמר ב\u0003קדשים,\u0004 ובקדשים (בקרבנות) כבר למדנו שכל מעשיהם ביום. \u0003ולטהרת מצורע\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת תהיה תורת המצרע ביום טהרתו\"\u0004 (ויקרא יד, ב).","\u0003כל הלילה כשר לקצירת העומר — ש\u0004\u0003אמר מר\u0004 \u0005[החכם]\u0006 והוכיח את הדבר מן הכתובים במסכת מנחות, כי מצות \u0003קצירה וספירה — בלילה, והבאה\u0004 של קרבן העומר למקדש — \u0003ביום. ולהקטר חלבים ואברים,\u0004 מנין שזמן ההקטרה כל הלילה \u0003— דכתיב\u0004 \u0005[שנאמר]\u0006 בהם במפורש: \u0003\"\u0004העולה על מוקדה על המזבח \u0003כל הלילה עד הבקר\"\u0004 (ויקרא ו, ב).","שנינו במשנה: \u0003זה הכלל דבר שמצותו ביום\u0004 — \u0003כשר כל היום.\u0004 ושואלים: \u0003זה הכלל\u0004 הכלל הזה \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 להוסיף את \u0005מה]?\u0006 שהרי לכאורה כבר פירטנו את כל הדברים שמצוותם ביום! ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003סידור בזיכין\u0004 של לבונה ליד לחם הפנים במקדש \u0003וסלוק בזיכין\u0004 בסוף השבוע, שלא נאמר בכתוב מתי זמנם, \u0003וכ\u0004שיטת \u0003ר' יוסי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר:\u0004 אם \u0003סילק את הישנה,\u0004 כלומר, את מערכת לחם הפנים ובזיכי הלבונה הישנים ב\u0003שחרית\u0004 (בתחילת היום) \u0003וסידר את החדשה ערבית\u0004 (בסוף היום) — \u0003אין בכך כלום\u0004 ודי שיהא הדבר באותו יום, וזו משמעות הכלל שכשרים כל היום, אבל לדעת חכמים צריך לסדר את החדשים מיד כשמסלק הישנים.","","\u0003ומה אני מקיים\u0004 לשיטת רבי יוסי את מה שכתוב בלחם הפנים \u0003\"\u0004יערכנו \u0003לפני ה' תמיד\"\u0004 (ויקרא כד, ח), כוונתו — \u0003שלא יהא שולחן\u0004 יום שלם \u0003בלא לחם,\u0004 ואם יש בו לחם אף בחלק מן היום — יצא.","עוד שנינו במשנה: \u0003דבר שמצותו בלילה\u0004 — \u0003כשר כל הלילה,\u0004 ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 להוסיף את \u0005מה]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003אכילת פסחים,\u0004 והרי זה ש\u0003לא כ\u0004שיטת \u0003ר' אלעזר בן עזריה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ואכלו את הבשר בלילה הזה\"\u0004 (שמות יב, ח), \u0003אמר ר' אלעזר בן עזריה: נאמר כאן \"בלילה הזה\" ונאמר להלן \"ועברתי בארץ מצרים בלילה הזה\"\u0004 (שמות יב, יב), \u0003מה להלן\u0004 כאשר ה' עבר בארץ מצרים היה זה \u0003עד חצות\u0004 הלילה, \u0003אף כאן\u0004 אין הפסח נאכל אלא \u0003עד חצות,\u0004 וממשנתנו נראה שאין הדבר כן, אלא שעיקר המצווה היא עד הבוקר.","","","\u0003הקורא את המגילה —\u0004 יכול לקוראה כרצונו, גם כשהוא \u0003עומד ו\u0004גם כשהוא \u0003יושב. קראה\u0004 אדם \u0003אחד\u0004 או \u0003קראוה שנים\u0004 יחד — \u0003יצאו\u0004 ידי חובתם. \u0003מקום שנהגו לברך\u0004 על קריאתה — \u0003יברך, ו\u0004מקום שנהגו \u0003שלא לברך — לא יברך.\u0004 ואגב כך מביאים עוד דינים ביחס לקריאת התורה. \u0003ב\u0004ימים \u0003שני וחמישי\u0004 בשחרית \u0003ובשבת במנחה — קורין\u0004 (קוראים) \u0003שלשה\u0004 אנשים בתורה, \u0003אין פוחתין מהן\u0004 במספר \u0003ואין מוסיפין עליהן,\u0004 אלא שלושה דווקא. \u0003ואין מפטירין בנביא\u0004 בזמנים אלה. \u0003הפותח,\u0004 כלומר, האיש הקורא ראשון \u0003והחותם\u0004 הקורא אחרון \u0003בתורה — מברך לפניה ולאחריה.\u0004 אבל לא שאר העולים לתורה.","","\u0003בראשי חדשים ובחולו של מועד קורין ארבעה\u0004 אנשים, \u0003אין פוחתין מהן ואין מוסיפין עליהן ואין מפטירין בנביא.\u0004 ואף אז \u0003הפותח והחותם בתורה מברך לפניה ולאחריה.\u0004 ומביאים כלל לגבי מספר הקוראים בימים שונים.","\u0003זה הכלל: כל\u0004 יום \u0003שיש בו\u0004 במקדש קרבן \u0003מוסף ואינו יום טוב\u0004 (כראש חודש וחול המועד) — \u0003קורין ארבעה, ביום טוב\u0004 קוראים \u0003חמשה\u0004 אנשים, \u0003ביום הכפורים\u0004 — \u0003ששה\u0004 אנשים, \u0003בשבת\u0004 — \u0003שבעה\u0004 אנשים. ובאלה \u0003אין פוחתין מהן, אבל מוסיפין עליהם\u0004 קרואים כמה שירצו, \u0003ומפטירין\u0004 בימים אלה \u0003בנביא,\u0004 ואף אז \u0003הפותח והחותם בתורה מברך לפניה ולאחריה.\u0004","אמרנו שהקורא את המגילה יכול לקרותה כשהוא יושב, \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003מה שאין כן בתורה\u0004 שקוראים אותה בעמידה בלבד. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר ר' אבהו:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואתה פה עמד עמדי\u0004 ואדברה אליך את כל המצוה והחוקים\u0003\"\u0004 (דברים ה, כח), משמע שקבלת תורה אינה אלא בעמידה. \u0003ואמר ר' אבהו: אלמלא מקרא\u0004 זה \u0003כתוב\u0004 במפורש, \u0003אי אפשר לאומרו,\u0004 כלומר, לא היינו מעיזים לומר דבר זה. ש\u0003כביכול\u0004 אפשר ללמוד מכאן ש\u0003אף הקדוש ברוך הוא\u0004 באותה שעה \u0003בעמידה,\u0004 שהרי נאמר \"עמוד עמדי\" — משמע: כמוני. \u0003ואמר ר' אבהו: מנין לרב שלא ישב על גבי מטה וישנה\u0004 (ילמד) \u0003לתלמידו\u0004 היושב \u0003על גבי קרקע — שנאמר: \"ואתה פה עמד עמדי\",\u0004 משמע שהרב והתלמיד צריכים להיות באותו מצב. ולענין קבלת התורה בעמידה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מימות משה ועד רבן גמליאל לא היו למדין תורה\u0004 מפי הרב \u0003אלא מעומד,\u0004 שהמקבל מן הרב כמקבלה מסיני, \u0003משמת רבן גמליאל ירד חולי לעולם\u0004 ונחלשו הבריות \u0003והיו למדין תורה\u0004 גם \u0003מיושב. והיינו דתנן\u0004 \u0005[והוא ששנינו\u0006 במשנה\u0005]:\u0006 \u0003משמת רבן גמליאל בטל כבוד תורה,\u0004 שהרי העמידה בזמן הלימוד היא עצמה מתן כבוד לתורה.","","","ומעירים באותו ענין, \u0003כתוב אחד אומר: \"ואשב בהר\"\u0004 (דברים ט, ט) \u0003וכתוב אחד אומר: \"ואנכי עמדתי בהר\"\u0004 (דברים י, י)! ומיישבים: \u0003אמר רב: עומד\u0004 היה משה רבינו \u0003ולומד,\u0004 כלומר, מקבל את הדברים מפי הגבורה בעמידה, ולאחר מכן היה \u0003יושב\u0004 בהר \u0003ושונה\u0004 חוזר ומשנן את הדברים. \u0003ר' חנינא אמר:\u0004 משה היה \u0003לא עומד ולא יושב אלא שוחה\u0004 (מתכופף), שזה מעין עמידה ומעין ישיבה. \u0003ר' יוחנן אמר:\u0004 מעיקרו של דבר אין כאן קושיה, כי \u0003אין \"ישיבה\"\u0004 זו \u0003אלא לשון עכבה,\u0004 ש\"לשבת\" פירושו גם להתעכב, לשהות במקום, וכפי \u0003שנאמר: \"ותשבו בקדש ימים רבים\"\u0004 (דברים א, מו). \u0003רבא אמר\u0004 שיש לישב את הסתירה באופן אחר: \u0003רכות\u0004 (עניינים קלים) היה לומד כשהוא \u0003מעומד, וקשות\u0004 (נושאים קשים שצריך לעיין בהם בישוב הדעת) היה לומד כשהוא \u0003מיושב.\u0004","שנינו במשנה: שבין אם \u0003קראה אחד\u0004 ובין אם \u0003קראוה שנים\u0004 — \u0003יצאו\u0004 ידי חובה."],["\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מה שאין כן בתורה,\u0004 שקורא אותה אדם אחד בלבד. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בתורה — אחד קורא ואחד מתרגם\u0004 לקהל בארמית, \u0003ובלבד שלא יהיה אחד קורא ושנים מתרגמין\u0004 — ששני קולות אינם נשמעים. \u0003ובנביא\u0004 אפילו \u0003אחד קורא ושנים מתרגמין,\u0004 שאין לדקדק כל כך בתרגום זה שאין בו הלכה למעשה, \u0003ובלבד שלא יהו שנים קוראין ושנים מתרגמין. ובהלל ובמגילה — אפילו עשרה קוראין ועשרה מתרגמין\u0004 מותר.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שהתירו בהלל ובמגילה גם כשיש קוראים אחדים — \u0003כיון\u0004 שאמירת ההלל וקריאת המגילה \u0003חביבה\u0004 על השומעים — \u0003יהבי דעתייהו, ושמעי\u0004 \u0005[נותנים דעתם, ושומעים]\u0006 ואינם מתבלבלים בשל כמה הקולות.","שנינו במשנה: \u0003מקום שנהגו לברך\u0004 על קריאת המגילה — \u0003יברך,\u0004 ובמקומות אחרים — לא יברך. \u0003אמר אביי: לא שנו\u0004 שהדבר תלוי במנהג \u0003אלא\u0004 בברכה ש\u0003לאחריה, אבל\u0004 בברכה ש\u0003לפניה\u0004 — \u0003מצוה לברך\u0004 לכל הדעות. ש\u0003אמר רב יהודה אמר שמואל: כל המצות כולן מברך עליהן עובר\u0004 \u0005[קודם]\u0006 \u0003לעשייתן.\u0004","ושואלים בדרך אגב: \u0003מאי משמע\u0004 \u0005[מה המשמעות,\u0006 מה מקור לשימוש לשון זה\u0005]\u0006 \u0003דהאי\u0004 \u0005[שזה\u0006 הלשון\u0005]\u0006 \u0003\"עובר\" לישנא דאקדומי\u0004 \u0005[לשון הקדמה]\u0006 \u0003הוא? אמר רב נחמן בר יצחק: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וירץ אחימעץ דרך הככר ויעבר את הכושי\"\u0004 (שמואל ב' יח, כג), משמע ש\"יעבור\" הוא כמו להקדים. \u0003אביי אמר\u0004 ראיה \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"והוא עבר לפניהם\"\u0004 (בראשית לג, ג), \u0003ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור\u0006 ראיה \u0005מכאן]:\u0006 \u0003\"ויעבר מלכם לפניהם וה' בראשם\"\u0004 (מיכה ב, יג).","ושואלים: בקריאת מגילה \u0003לפניה מאי\u0004 \u0005[מה)\u0006 \u0003מברך?\u0004 ומספרים: \u0003רב ששת מ\u0004ן המקום \u0003קטרזיא איקלע לקמיה\u0004 \u0005[הזדמן לפני]\u0006 \u0003רב אשי ובריך\u0004 \u0005[וברך]\u0006 \u0003מנ\"ח,\u0004 והוא סימן לשלוש הברכות שיש לברך על המגילה; על \u0003מ\u0004קרא מגילה, ושעשה \u0003נ\u0004יסים לאבותינו, ושה\u0003ח\u0004יינו.","ושואלים: \u0003לאחריה מאי\u0004 \u0005[מה]\u0006 \u0003מברך\u0004 במקום שנהגו? ומשיבים שמברך ברכה זו: \u0003\"ברוך אתה ה' אלהינו מלך העולם האל הרב את ריבנו והדן את דיננו והנוקם את נקמתנו והנפרע לנו מצרינו והמשלם גמול לכל אויבי נפשנו, ברוך אתה ה' הנפרע לישראל מכל צריהם\". רבא אמר:\u0004 לא כך הוא מסיים, אלא מסיים: \u0003\"\u0004ברוך אתה ה' \u0003האל המושיע\". אמר רב פפא: הלכך\u0004 \u0005[לכן]\u0006 כיון שיש שתי דיעות בדבר — \u0003נימרינהו לתרוייהו\u0004 \u0005[נאמר את שניהם]\u0006 ונצא ידי חובת הכל, ונאמר בלשון זו: \u0003\"ברוך אתה ה' הנפרע לישראל מכל צריהם האל המושיע\".\u0004","שנינו במשנה: \u0003בשני ובחמישי\u0004 ו\u0003בשבת במנחה קוראים שלשה\u0004 אנשים. ושואלים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003שלשה\u0004 שקבעו, \u0003כנגד מי\u0004 קבעו מספר זה? \u0003אמר רב אסי: כנגד\u0004 שלושה חלקי המקרא; \u0003תורה נביאים וכתובים. רבא אמר: כנגד\u0004 שלושה המרכיבים של עם ישראל; \u0003כהנים לוים וישראלים.\u0004","ושואלים: \u0003אלא הא דתני\u0004 \u0005[זו\u0006 הברייתא \u0005ששנה]\u0006 \u0003רב שימי: אין פוחתין מעשרה פסוקין\u0004 כשקוראים בתורה \u0003בבית הכנסת,\u0004 וגם הפסוק \u0003\"וידבר\"\u0004 אף על פי שאין למדים ממנו דבר (לפי שרבות מן הפרשות מתחילות בפסוק פתיחה זה: \"וידבר ה' אל משה לאמור\"), אף הוא \u0003עולה מן המנין\u0004 של עשרה. \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003עשרה\u0004 פסוקים \u0003כנגד מי?\u0004","\u0003אמר ר' יהושע בן לוי: כנגד עשרה בטלנין שבבית הכנסת,\u0004 שהם אנשים הבטלים מעבודתם ועוסקים בצרכי הציבור, ויושבים בבית הכנסת, ולכן יש שם תמיד מנין. \u0003רב יוסף: אמר כנגד עשרת הדברות שנאמרו למשה בסיני, ר' לוי אמר: כנגד עשרה הילולין\u0004 (מזמורים שיש בהם \"תהילה\") \u0003שאמר דוד בספר תהלים. ור' יוחנן אמר: כנגד עשרה מאמרות שבהן נברא העולם.\u0004","ושואלים: \u0003הי נינהו\u0004 \u0005[מי הם]\u0006 אותם עשרה מאמרות? ודאי הם אותם לשונות \u0003\"ויאמר\"\u0004 שנאמרו בפסוקים העוסקים במעשה \u0003בראשית\u0004 שנאמר בהם \"ויאמר אלוהים...\", אולם אם נספור את מספרם המדוייק, הלא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003תשעה\u0004 בלבד \u0003הוו\u0004 \u0005[הם]\u0006 ולא עשרה! ומשיבים: המלה \u0003\"בראשית\" נמי\u0004 \u0005[גם כן]\u0006 \u0003מאמר הוא,\u0004 והוא מאמר הבריאה הכולל, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בדבר ה' שמים נעשו וברוח פיו כל צבאם\"\u0004 (תהלים לג, ו), כלומר, הדיבור הראשון של היצירה היה מאמר הבריאה הכללי לכל היקום.","\u0003אמר רבא\u0004 כיון שקוראים עשרה פסוקים ומחלקים אותם בין שלושה אנשים, הרי רק אחד מהם קורא ארבעה והשנים האחרים קוראים שלושה שלושה, ובענין זה כל סדר שעושים יש בו טעם, \u0003ראשון שקרא ארבעה\u0004 פסוקים — \u0003משובח, שני שקרא ארבעה\u0004 — \u0003משובח, שלישי שקרא ארבעה\u0004 — \u0003משובח.\u0004","והוא מבאר: \u0003ראשון שקרא ארבעה משובח\u0004 — לפי שיש מעלה ויתרון בראשון \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בשלש קופות\u0004 (סלים) \u0003של שלש סאין שבהן\u0004 היו \u0003תורמין את הלשכה,\u0004 שהיו מוציאים מן הלשכה (החדר שצברו בו את כל השקלים) שלושה סלים מלאים כסף לצרכי המקדש השוטפים, \u0003והיה כתוב עליהן\u0004 (על הסלים) \u0003א' ב' ג' לידע איזו מהן נתרמה ראשון\u0004 כדי \u0003להקריב ממנה ראשון, שמצוה בראשון,\u0004 הרי למדנו מעלתו של ראשון.","אולם גם \u0003אמצעי\u0004 (שני) \u0003שקרא ארבעה משובח\u0004 — שאף בכך יש מעלה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"אל מול פני המנורה יאירו\u0004 שבעת הנרות\u0003\"\u0004 (במדבר ח, ב) \"פני המנורה\" הוא גופה של המנורה, הקנה האמצעי שבה — \u0003מלמד שמצדד\u0004 (מפנה) \u0003פניהם כלפי נר מערבי\u0004 (אמצעי), \u0003ונר מערבי\u0004 פונה \u0003כלפי שכינה\u0004 — למערב, \u0003ואמר ר' יוחנן: מכאן שאמצעי משובח. ו\u0004אף","\u0003אחרון שקרא ארבעה משובח — משום\u0004 הכלל \u0003מעלין בקדש ואין מורידין,\u0004 ולפיכך אם האחרון מעולה מן הקודמים יש בכך עליה בקודש. מסופר: \u0003רב פפא איקלע לבי כנישתא\u0004 \u0005[הזדמן לבית הכנסת]\u0006 של המקום \u0003אבי גובר וקרא ראשון ארבעה, ושבחיה\u0004 \u0005[ושבחו]\u0006 \u0003רב פפא\u0004 על כך.","שנינו במשנה: \u0003אין פוחתין מהן ואין מוסיפין\u0004 עליהם, והפותח והחותם בתורה מברך. ו\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003הפותח\u0004 (הקורא ראשון) — \u0003מברך לפניה\u0004 (לפני הקריאה), \u0003והחותם\u0004 (הקורא אחרון) — \u0003מברך לאחריה,\u0004","ומעירים: \u0003והאידנא\u0004 \u0005[ועכשיו,\u0006 בזמננו\u0005]\u0006 \u0003דכולהו מברכי\u0004 \u0005[שכולם,\u0006 כל העולים לתורה \u0005מברכים]\u0006 \u0003לפניה ולאחריה — היינו טעמא דתקינו רבנן\u0004 \u0005[זה הטעם שתיקנו חכמים]:\u0006 \u0003גזירה משום הנכנסין\u0004 לבית הכנסת באמצע הקריאה ולא שמעו את הברכה הראשונה \u0003ומשום היוצאין\u0004 באמצעה ואינם שומעים את הברכה האחרונה, ויחשבו בטעות שאכן לא נאמרה אלא ברכה אחת ושדי בכך מצד הדין.","שנינו במשנה: \u0003בראשי חדשים ובחולו של מועד קורין\u0004 (קוראים) \u0003ארבעה. בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003עולא בר רב מרבא: פרשת ראש חודש\u0004 שקוראים בה שלוש פרשיות קטנות סמוכות (במדבר כח, א-ח, במדבר כח, ט-י, ובמדבר כח, יא-טו) \u0003כיצד קורין אותה\u0004 כאשר יש לחלק את קריאתה בין ארבעה אנשים? הפרשיה הראשונה \u0003\"צו את בני ישראל ואמרת אליהם את קרבני לחמי\"\u0004 (במדבר כח, ב) \u0003דהויין תמניא פסוקי\u0004 \u0005[שהן שמונה פסוקים],\u0006 \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006","\u0003ניקרי תרי תלתא תלתא\u0004 \u0005[נקרא\u0006 ל\u0005שני\u0006 הקרואים הראשונים \u0005שלושה שלושה]\u0006 \u0003פסוקים\u0004 — הרי \u0003פשו להו תרי\u0004 \u0005[נשארו להם\u0006 בפרשיה עוד \u0005שני\u0006 פסוקים\u0005]\u0006 \u0003ו\u0004כלל הוא: \u0003אין משיירין בפרשה\u0004 כאשר מפסיקים בקריאה \u0003פחות משלשה פסוקין.\u0004 אלא \u0003ניקרי\u0004 \u0005[נקרא]\u0006 \u0003ארבעה ארבעה\u0004 בפרשיה הראשונה, אם כן עד סוף הקריאה \u0003פשו להו\u0004 \u0005[נשארו להם]\u0006 \u0003שבעה\u0004 פסוקים, פרשיה שניה של \u0003\"וביום השבת\"\u0004 (במדבר כח, ט-י) \u0003הויין תרי\u0004 \u0005[הם שנים],\u0006 \u0003\"ובראשי חדשיכם\"\u0004 (במדבר כח, יא-טו) \u0003הויין\u0004 \u0005[הם]\u0006 \u0003חמשה,\u0004 ואם כן \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 אם \u0003נקרי תרי מהא וחד מהנך\u0004 \u0005[נקרא שתים מזו\u0006 מהפרשה של אותה השבת \u0005ואחד מאלה\u0006 מפרשת ראש חודש\u0005]\u0006 —"],["הלוא כלל הוא ש\u0003אין מתחילין בפרשה פחות משלשה פסוקים.\u0004 ואם נעשה כך: \u0003ליקרי תרי מהא ותלתא מהך\u0004 \u0005[שיקרא שתים מזו,\u0006 כל פרשיית השבת \u0005ושלושה מזו,\u0006 מפרשיית ראש חודש\u0005],\u0006 אם כן \u0003פשו להו תרי\u0004 \u0005[ישארו להם שני\u0006 פסוקים\u0005]\u0006 בפרשת ראש חודש, ואמרנו שאין משיירים בפרשה פחות משלושה פסוקים!","\u0003אמר לו\u0004 רבא: \u0003זו לא שמעתי,\u0004 כלומר, פתרון לבעיה זו במפורש לא שמעתי, אלא בבעיה \u0003כיוצא בה שמעתי, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 במעמדות קוראים \u0003ביום הראשון\u0004 את שתי הפרשיות, \u0003\"בראשית\"\u0004 (בראשית א, א-ה) \u0003ו\"יהי רקיע\"\u0004 (בראשית א, ו-ח), \u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005על כך]:\u0006 פרשת \u0003\"בראשית\"\u0004 קוראים \u0003בשנים,\u0004 פרשת \u0003\"יהי רקיע\"\u0004 — \u0003באחד.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים\u0006 ומתקשים\u0005]\u0006 \u0003בה\u0004 בהלכה זו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003\"יהי רקיע\"\u0004 קוראים \u0003באחד,\u0004 משום \u0003דתלתא פסוקי הוו\u0004 \u0005[ששלושה פסוקים הם],\u0006 \u0003אלא \"בראשית\" בשנים\u0004 כיצד? הלוא \u0003חמשה פסוקים הוו\u0004 \u0005[הם],\u0006 \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003הקורא בתורה לא יפחות משלשה פסוקים!\u0004","\u0003ואיתמר עלה\u0004 \u0005[ונאמר עליה]\u0006 בפתרון בעיה זו, שנחלקו בה האמוראים כיצד נוהגים; \u0003רב אמר: דולג,\u0004 כלומר, השני חוזר וקורא שוב את הפסוק האחרון שקרא קודמו. \u0003ושמואל אמר: פוסק,\u0004 כלומר, מחלקים פסוק אחד לשנים כאילו יש בפרשה שישה פסוקים, וכל אחד קורא שלושה מהם.","ומסבירים את שיטותיהם: \u0003רב אמר דולג, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 שבמקרה כזה \u0003פוסק\u0004 כשיטת שמואל? \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003כל פסוקא\u0004 \u0005[פסוק]\u0006 ש\u0003לא פסקיה\u0004 \u0005[פסק אותו]\u0006 \u0003משה אנן\u0004 \u0005[אנחנו]\u0006 \u0003לא פסקינן ליה\u0004 \u0005[פוסקים אותו].\u0006","ותוהים: \u0003ו\u0004אם כן, לשיטה זו \u0003שמואל אמר פסקינן ליה\u0004 \u0005[\u0006ש\u0005פוסקים אותו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' חנניא קרא\u0004 (מלמד התינוקות): \u0003צער גדול היה לי אצל ר' חנינא הגדול,\u0004 כלומר, פעמים רבות הייתי צריך לבקש ממנו שיתיר לי לחלק פסוק באמצעו ולהפסיק שם, \u0003ולא התיר לי לפסוק אלא לתינוקות של בית רבן, הואיל ולהתלמד עשויין,\u0004 וכיון שאינם יכולים ללמוד פסוק ארוך שלם, מוטב שיחלקו אותו, כדי שיוכלו ללמדו היטב.","ומשיבים: זה, אינו קושי; \u0003התם טעמא מאי\u0004 \u0005[שם מה טעם]\u0006 התירו — \u0003משום\u0004 ש\u0003לא אפשר\u0004 אלא כך, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003לא אפשר\u0004 אחרת, ובעל כרחנו יש לחצות פסוק.","ומבארים גם את הצד השני: \u0003ושמואל אמר פוסק,\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר דולג\u0004 כרב? ומשיבים \u0003גזירה משום הנכנסין ומשום היוצאין,\u0004 שהרי אם יכנס אדם באמצע או יצא באמצע, יחשוב שהתחילו פרשה או שהפסיקו באמצע פרשה בפחות משלושה פסוקים, ולכן מותר לפסוק באמצע שיבינו הכל מה עשו שם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו לענין קריאת התורה בכלל: \u0003פרשה של ששה פסוקים — קוראים אותה בשנים, ושל חמשה פסוקים — ביחיד. קרא ראשון שלשה\u0004 פסוקים מפרשה זו — \u0003השני קורא שנים מפרשה זו\u0004 ומסיימה \u0003ו\u0004עוד פסוק \u0003אחד מפרשה אחרת. ויש אומרים\u0004 שאין די בקריאת פסוק אחד מפרשה אחרת, אלא קורא \u0003שלשה\u0004 פסוקים, \u0003לפי שאין מתחילין בפרשה פחות משלשה פסוקים.\u0004","\u0003ואם איתא\u0004 \u0005[יש\u0006 מקום\u0005]\u0006 לפתרונות אלה של רב ושמואל, שדולג או פוסק, אם כן \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003דולג\u0004 — בפרשה של חמישה \u0003נדלוג, ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003פוסק\u0004 — \u0003נפסוק!\u0004","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אפשר בהכי\u0004 \u0005[בכך],\u0006 שאפשר להמשיך ולקרוא הלאה ולפתור את הבעיה בצורה טובה יותר, אבל בראש חודש שיש מספר פסוקים מצומצם המדברים בענין ראש חודש, אין מקום להמשיך ולפתור כך את הבעיה במחלוקת התנאים בקריאת פרשה קטנה.","\u0003אמר ר' תנחום אמר ר' יהושע בן לוי: הלכה כ\u0004שיטת \u0003יש אומרים\u0004 שקורא שלושה פסוקים מן הפרשה הבאה. \u0003ו\u0004עוד \u0003אמר ר' תנחום אמר ר' יהושע בן לוי: כשם שאין מתחילין בפרשה פחות משלשה פסוקים, כך אין משיירין בפרשה פחות משלשה פסוקים.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 \u0003השתא\u0004 \u0005[הרי]\u0006 \u0003ומה אתחלתא\u0004 \u0005[בתחילת\u0006 פרשה\u0005]\u0006 בפסוק אחד, \u0003דקא\u0004 \u0005[שבה]\u0006 \u0003מקיל\u0004 ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שאמר קודם שאפשר להוסיף מהפרשה הבאה עוד פסוק אחד בלבד — \u0003מחמירי\u0004 \u0005[מחמירים]\u0006 אותם \u0003יש אומרים\u0004 ולשיטתם אף אין מתחילים פרשה בפחות משלושה, אם כן ב\u0003שיור\u0004 בפרשה שבדבר זה \u0003מחמיר\u0004 גם ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שגם הוא אוסר להשאיר פחות משלושה פסוקים, \u0003לא כל שכן דמחמירי\u0004 \u0005[שמחמירים]\u0006 \u0003יש אומרים?!\u0004 וכיון שפסק כשיטת יש אומרים, מה טעם חזר ופסק בשיור?","ומשיבים: הדבר אינו פשוט כל כך, ומדוע — \u0003מהו דתימא\u0004 \u0005[שנאמר]:\u0006 \u0003נכנסין שכיחי\u0004 \u0005[מצויים],\u0006 שמצוי שיאחר אדם ויכנס באמצע קריאת התורה, ולכן יש מקום להחמיר כשמתחילים פרשה, אבל \u0003יוצאין לא שכיחי\u0004 \u0005[מצויים],\u0006 שאין זה מן הראוי \u0003דמנחי\u0004 \u0005[שמניחים]\u0006 \u0003ספר תורה ונפקי\u0004 \u0005[ויוצאים],\u0006 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' יהושע בן לוי, שגם יש אומרים חוששים ליוצאים ולכן אין משיירים בפרשה בפחות משלושה פסוקים.","\u0003ו\u0004שואלים אם כן, ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003מאי שנא שיורי\u0004 \u0005[במה שונה\u0006 ש\u0005לשייר]\u0006 בפרשה פחות משלושה פסוקים הוא ש\u0003לא\u0004 \u0005[שאינו]\u0006 מתיר — \u0003משום\u0004 שהוא חושש מפני ה\u0003יוצאין,\u0004 אם כן \u0003אתחולי נמי\u0004 \u0005[להתחיל גם כן]\u0006 לקרוא פרשה חדשה בפחות משלושה יש לחשוש, \u0003גזירה משום הנכנסין,\u0004 ומדוע אינו חושש לכך? \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003מאן דעייל שיולי שייל\u0004 \u0005[מי שנכנס\u0006 באמצע \u0005שואל]\u0006 כיצד קראו עד כאן, ומסבירים לו שהקורא התחיל עוד בפרשה הקודמת. ולכן לא יבוא לטעות ולחשוב שהפרשה הזו פסוקה באמצע.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב יוסף\u0004 באמצעות שליח, שאלה זו ביחס לקריאת פרשה קטנה בשנים: \u0003הלכתא מאי\u0004 \u0005[הלכה מהי\u0006 בזה\u0005]?\u0006 \u0003שלח ליה\u0004 \u0005[לו]:\u0006 \u0003הלכתא\u0004 \u0005[ההלכה\u0006 היא\u0005]:\u0006 \u0003דולג,\u0004 כרב, \u0003ו\u0004הקורא בתורה \u0003אמצעי\u0004 הוא ש\u0003דולגן\u0004 ולא האחרון, כדי שלא יצטרכו לשייר בפרשה.","שנינו במשנה: \u0003זה הכלל, כל שיש בו\u0004 קרבן \u0003מוסף\u0004 ואין בו איסור מלאכה קוראים שלושה וכו'. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003תענית צבור, בכמה\u0004 קוראים? וצדדי השאלה: \u0003ראש חדש ומועד דאיכא\u0004 \u0005[שיש\u0006 בהם\u0005]\u0006 \u0003קרבן מוסף\u0004 — קוראים \u0003ארבעה, אבל הכא\u0004 \u0005[כאן]\u0006 בתענית ציבור \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003קרבן מוסף — לא,\u0004 ויקראו רק שלושה. \u0003או דלמא הכא נמי\u0004 \u0005[שמא כאן גם כן]\u0006 הלא \u0003איכא\u0004 \u0005[יש]\u0006 \u0003מוסף תפלה,\u0004 שבתעניות הציבור הגדולות היו מוסיפים תפילת \"עננו\", וכיון שיש בה תוספת (\"מוסף\") זו, צריך לקרוא בארבעה.","ומנסים להביא ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר במשנתנו: \u0003בראשי חדשים ובחולו של מועד קורין ארבעה,\u0004 ונדייק מכאן \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בתענית צבור — שלשה\u0004 בלבד! ודוחים: \u0003אימא רישא\u0004 \u0005[אמור\u0006 את \u0005ראשה]\u0006 של המשנה, נאמר בה: \u0003בשני ובחמישי ובשבת במנחה קוראין שלשה,\u0004 ומכאן נדייק להיפך: \u0003הא\u0004 \u0005[הרי]\u0006 ב\u0003תענית צבור\u0004 קוראים \u0003ארבעה! אלא\u0004 יש לסכם כי \u0003מהא ליכא למישמע מינה\u0004 \u0005[מ\u0006משנה \u0005זו אין לשמוע ממנה\u0006 בדרך הדיוק\u0005],\u0006 שלא באה משנה זו למצות את כל המקרים לא בראשה ולא בסופה.","ומציעים פתרון אחר, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מעשה שהיה; ש\u0003רב איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבבל בתענית צבור, קם קרא בספרא\u0004 \u0005[עמד קרא בספר\u0006 התורה\u0005],\u0006 \u0003פתח בריך\u0004 \u0005[\u0006ו\u0005בירך\u0006 ברכה\u0005],\u0006 \u0003חתים\u0004 \u0005[חתם]\u0006 \u0003ולא בריך\u0004 \u0005[בירך],\u0006 \u0003נפול כולי עלמא אאנפייהו\u0004 \u0005[נפלו כל העם\u0006 בתחנון \u0005על פניהם]\u0006 כמנהג \u0003ורב לא נפל על אפיה\u0004 \u0005[פניו].\u0006","ומתוך מעשה זה ננסה לברר כיצד נהג רב; \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003רב ב\u0004עליה המיועדת ל\u0003ישראל\u0004 הוא ש\u0003קרא,\u0004 שלא היה לא כהן ולא לוי, ואם כן קראוהו לתורה שלישי, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אם כן \u0003חתם ולא בריך\u0004 \u0005[בירך]?\u0006 \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום דבעי למיקרי אחרינא בתריה\u0004 \u0005[ש\u0006היה \u0005צריך לקרוא אחר אחריו]?\u0006 וכיון שרק האחרון מברך — לא ברך רב בחתימה, ומכאן שבתענית ציבור קוראים ארבעה.","ודוחים: \u0003לא, רב בכהני\u0004 \u0005[ב\u0006פרשה המיועדת ל\u0005כהנים],\u0006 כלומר: ראשון \u0003קרא,\u0004 משום שהיה גדול הדור, והוא קודם לכהן. \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב הונא קרי\u0004 \u0005[\u0006היה \u0005קורא]\u0006 ראשון \u0003בכהני\u0004 \u0005[ב\u0006פרשה המיועדת ל\u0005כהן]\u0006 הוא שקרא (ראה גיטין נט,ב), וכמו כן נהג אף רב.","על כך מקשים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003רב הונא קרי בכהני\u0004 \u0005[\u0006היה \u0005קורא בכהן],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אפילו רב אמי ורב אסי דכהני חשיבי דארעא\u0004 \u0005[ש\u0006היו \u0005הכהנים החשובים של ארץ]\u0006 \u0003ישראל, מיכף כייפו ליה\u0004 \u0005[\u0006ו\u0005היו כפופים לו]\u0006 \u0003לרב הונא,\u0004 שהוא היה נחשב בזמנו כראש לכל ישראל. \u0003אלא רב — הא איכא\u0004 \u0005[הלא יש,\u0006 היה\u0005]\u0006 את \u0003שמואל דכהנא הוה, ודבר עליה\u0004 \u0005[שכהן היה, וגידל\u0006 אותו רב \u0005עליו,\u0006 על עצמו\u0005]\u0006 שיקדימו אותו בכל ענין של כבוד, ואם כן לא היה נחשב כיחיד שבדור, ובודאי לא היתה לו סיבה לקרוא ראשון ככהן!","ומשיבים: לאמיתו של דבר \u0003שמואל נמי מיכף הוה כייף ליה\u0004 \u0005[גם כן כפוף היה לו]\u0006 \u0003לרב,\u0004 שרב אכן באמת גדול הדור בבבל, \u0003ו\u0004אולם \u0003רב הוא דעבד ליה\u0004 \u0005[שעשה לו]\u0006 \u0003כבוד,\u0004 מפני שהיה לו טעם בכך, שרצה לפייסו, \u0003וכי עביד ליה\u0004 \u0005[וכאשר\u0006 היה \u0005עושה לו]\u0006 כבוד היה זה רק \u0003בפניו,\u0004 כשהיה שמואל נוכח שם, אך \u0003שלא בפניו לא עביד ליה\u0004 \u0005[עשה לו],\u0006 ולכן היה קורא ראשון בתורה כשלא היה שמואל נוכח שם.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005]\u0006 ש\u0003רב בכהני\u0004 \u0005[ב\u0006תור \u0005כהן]\u0006 ראשון \u0003קרא, דאי סלקא דעתך\u0004 \u0005[שאם עולה\u0006 על \u0005דעתך\u0006 לומר\u0005]\u0006 כי \u0003ב\u0004עליה המיועדת ל\u0003ישראל קרא\u0004 והיה שלישי, \u0003לפניה\u0004 לפני הקריאה \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003בריך\u0004 \u0005[בירך],\u0006 שהרי אמרנו שרק הקורא ראשון מברך! ודוחים: דבר זה היה \u0003לאחר\u0004 ה\u0003תקנה\u0004 שתיקנו שיהיו הכל מברכים לפני הקריאה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003לאחריה נמי לבריך\u0004 \u0005[גם כן יברך],\u0006 שהרי לפי תקנה זו הכל מברכים גם לפניה וגם לאחריה! ומשיבים: כיון שטעם תקנה זו שיברכו הכל לאחריה הוא משום היוצאים באמצע הקריאה, אם כן במקרה מסויים זה אין להקפיד על כך, כיון ש\u0003שאני היכא דיתיב\u0004 \u0005[שונה\u0006 הדבר \u0005במקום שישב]\u0006 בו \u0003רב\u0004 והיה נוכח בתפילה, \u0003דמיעל עיילי\u0004 \u0005[שלהכנס\u0006 היו \u0005נכנסים],\u0006"],["ואולם \u0003מיפק לא נפקי\u0004 \u0005[לצאת אין יוצאים]\u0006 מפני כבודו של רב, ולכן לא היה מקום לברך ברכה אחרונה. על כל פנים אין לנו מכאן פתרון לשאלה כמה אנשים קוראים בתורה בתענית ציבור.","על כן מביאים ראיה מברייתא, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו, \u0003זה הכלל: כל\u0004 יום \u0003ש\u0004מותר בעשיית מלאכה ואם יאריכו בתפילה \u0003יש בו ביטול מלאכה לעם, כגון תענית צבור ותשעה באב\u0004 — משתדלים לקצר בו בתפילה ובקריאת התורה ו\u0003קורין\u0004 (קוראים) בתורה רק \u0003שלשה, ו\u0004אולם ביום","\u0003שאין בו ביטול מלאכה לעם, כגון ראשי חדשים\u0004 (שנהגו הנשים שלא לעשות בו מלאכה) \u0003וחולו של מועד,\u0004 שנמנעים בו ממלאכה שאין הפסד בדחייתה — \u0003קורין ארבעה.\u0004 ומסכמים, אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבתענית ציבור קוראים שלושה.","\u0003אמר רב אשי: והא אנן לא תנן הכי\u0004 \u0005[והרי אנחנו לא שנינו כך\u0006 במשנה\u0005]\u0006, ששנינו: \u0003זה הכלל: כל יום שיש בו מוסף ואינו יום טוב קורין ארבעה,\u0004 וכלל זה \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 לרבות את \u0005מה],\u0006 \u0003לאו לאתויי\u0004 \u0005[האם לא להביא,\u0006 להוסיף בהם\u0005]\u0006 גם \u0003תענית ציבור ותשעה באב\u0004 שיש בהם מוסף תפילה, שאף בהם קוראים ארבעה!","ושואלים: אם הוא סבור שבימים אלו קוראים ארבעה, אם כן, \u0003לרב אשי מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]\u0006 שהרי היא \u0003לא\u0004 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ולא\u0004 שיטת \u0003ר' יוסי,\u0004 כפי שיבוארו שיטותיהם להלן, \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חל\u0004 תשעה באב \u0003להיות ב\u0004יום \u0003שני\u0004 או \u0003ב\u0004יום \u0003חמישי\u0004 שקוראים בהם תמיד שלושה בתורה — \u0003קורין\u0004 (קוראים) בתורה \u0003שלשה ומפטיר\u0004 הוא \u0003אחד\u0004 מהם. חל להיות \u0003בשלישי וברביעי — קורא\u0004 אדם \u0003אחד ומפטיר אחד\u0004 אותו אדם. \u0003ר' יוסי אומר: לעולם קורין שלשה ומפטיר אחד\u0004 מהם. הרי שלכל הדעות אין קוראים בימים אלה יותר משלושה!","ושואלים: \u0003ואלא\u0004 אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003\"זה הכלל\"\u0004 שבמשנתנו, שממנו דייק רב אשי שבתענית ציבור קוראים ארבעה! ומשיבים: \u0003לא\u0004 לענין תענית נאמר אלא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003ראש חודש ומועד\u0004 בא, שבהם קוראים ארבעה.","ותוהים: \u0003הא בהדיא קתני לה\u0004 \u0005[הרי במפורש שנה אותה],\u0006 שהרי שנינו במשנתנו: \u0003בראשי חדשים ומועד קורין ארבעה!\u0004","ומשיבים: מעיקרו של דבר לא נועד כלל זה להוסיף דברים על המפורשים כבר במשנה, אלא \u0003סימנא בעלמא יהיב\u0004 \u0005[סימן בלבד נתן]\u0006 לזכור את מספר הקרואים בכל יום. והוצרך לכך \u0003דלא תימא\u0004 \u0005[שלא תאמר]\u0006 \u0003יום טוב וחולו של מועד\u0004 מבחינת קדושתם \u0003כי הדדי נינהו\u0004 \u0005[זה כמו זה הם]\u0006 ויקראו גם בחולו של מועד כביום טוב, \u0003אלא נקוט האי כללא\u0004 \u0005[החזק כלל זה]\u0006 \u0003בידך\u0004 לזכרון: \u0003כל דטפי ליה מילתא מחבריה, טפי ליה גברא יתירא\u0004 \u0005[כל שנוסף לו דבר על חבירו, מוסיפים לו אדם יתר\u0006 בקוראים\u0005]\u0006.","\u0003הלכך\u0004 (על כן) \u0003בראש חדש ומועד דאיכא\u0004 \u0005[שיש\u0006 בהם\u0005]\u0006 \u0003קרבן מוסף — קורין ארבעה, ביום טוב\u0004 שבנוסף לכך גם \u0003אסור בעשיית מלאכה\u0004 — קוראים \u0003חמשה, ביום הכפורים\u0004 שעל עשיית מלאכה בו \u0003ענוש כרת\u0004 — קוראים \u0003ששה, שבת דאיכא\u0004 \u0005[שיש\u0006 בה\u0005]\u0006 \u0003איסור סקילה\u0004 על מלאכה — קוראים \u0003שבעה.\u0004","כיון שעסקנו בביקורו של רב בבית הכנסת בבבל, דנים בו \u0003גופא\u0004 \u0005[לגופו]\u0006 של אותו מעשה, סופר כי \u0003רב איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבבל בתענית צבור, קם\u0004 \u0005[עמד]\u0006 ו\u0003קרא בספרא\u0004 \u0005[בספר\u0006 תורה\u0005]\u0006 \u0003פתח בריך\u0004 \u0005[\u0006ו\u0005בירך],\u0006 \u0003חתם ולא בריך\u0004 \u0005[בירך],\u0006 \u0003נפול כולי עלמא אאנפייהו\u0004 \u0005[נפלו כל העם על פניהם]\u0006 \u0003ורב לא נפל על אנפיה\u0004 \u0005[פניו].\u0006 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003רב לא נפיל\u0004 \u0005[נפל]\u0006 \u0003על אפיה\u0004 \u0005[פניו]?\u0006","ומשיבים: שם, \u0003רצפה של אבנים היתה, ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 נאמר: \u0003\"ואבן משכית לא תתנו בארצכם להשתחות עליה\"\u0004 (ויקרא כו, א) ולמדו משם: \u0003\"עליה\",\u0004 על אבן משכית מכל סוג, \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה משתחוה בארצכם,\u0004 כלומר, בשאר מקומות, \u0003אבל אתה משתחוה על אבנים של בית המקדש. כ\u0004דברי \u0003עולא,\u0004 ש\u0003אמר עולא: לא אסרה תורה\u0004 להשתחויה \u0003אלא רצפה של אבנים בלבד,\u0004 ולכן לא נפל שם רב על פניו.","ושואלים: \u0003אי הכי \u0004 אם מפני האיסור שבדבר \u0003מאי איריא\u0004 \u0005[מדוע דווקא]\u0006 \u0003רב, אפילו כולהו נמי\u0004 \u0005[כולם גם כן]\u0006 אסור היה להם ליפול על פניהם! ומשיבים: רק \u0003קמיה\u0004 \u0005[לפניו]\u0006 לפני \u0003רב הואי\u0004 \u0005[היתה]\u0006 רצפה של אבן, ובשאר מקומות לא היה מרוצף.","ושואלים: אם כן, \u0003וליזיל לגבי ציבורא ולינפול\u0004 \u0005[שילך\u0006 רב \u0005אל הציבור ויפול]\u0006 שם \u0003על אפיה\u0004 \u0005[על פניו]!\u0006 ומשיבים: \u0003לא בעי למיטרח ציבורא\u0004 \u0005[רצה להטריח\u0006 את \u0005הציבור]\u0006 שיצטרכו לפנות לו מקום. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003רב פישוט ידים ורגלים הוה עביד\u0004 \u0005[היה עושה],\u0006 שכשהיה נופל על פניו היה נופל מלוא קומתו על הרצפה, ולא כפי שנהגו האחרים שרק היו מטים עצמם (כעין נפילה סמלית) על הצד. ולכן היה מותר להם ליפול על פניהם. \u0003וכ\u0004דברי \u0003עולא,\u0004 ש\u0003אמר עולא: לא אסרה תורה\u0004 בהשתחויה \u0003אלא\u0004 כשהיא \u0003בפישוט ידים ורגלים בלבד.\u0004","ושואלים: אם כן, \u0003וליפול\u0004 \u0005[ושיפול]\u0006 \u0003על אפיה\u0004 \u0005[פניו]\u0006 \u0003ולא ליעביד\u0004 \u0005[יעשה]\u0006 \u0003פישוט ידים ורגלים!\u0004 ומשיבים: \u0003לא\u0004 היה \u0003משני ממנהגיה\u0004 \u0005[משנה ממנהגו]\u0006 הקבוע לו בצורת נפילת אפים, ובאותו מקום לא יכול היה לעשות כן משום שהיתה שם רצפה של אבנים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר מדוע לא נפל על פניו: \u0003אדם חשוב שאני\u0004 \u0005[שונה]\u0006 \u0003וכ\u0004דברי \u0003ר' אלעזר.\u0004 ש\u0003אמר ר' אלעזר: אין אדם חשוב רשאי ליפול על פניו\u0004 בפני הרבים \u0003אלא אם כן\u0004 יודע שמעשיו רצויים לפני ה' ויהיה \u0003נענה\u0004 בתפילתו \u0003כיהושע בן נון\u0004 בזמנו, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ה' אל יהושע קם לך\u0004 למה זה אתה נופל על פניך\u0003\"\u0004 (יהושע ז, י), ומי שאינו בטוח שייענה מיד, הרי יש בכך פחיתות כבוד שהוא מתפלל ואינו נענה.","כיון שהזכרנו דרכי השתחויה, מביאים מה ששנו חכמים בענין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"קידה\"\u0004 שנאמרה בכל מקום, היא \u0003על אפים\u0004 שמתכופף על פניו, \u0003שנאמר: \"ותקד בת שבע אפים ארץ\"\u0004 (מלכים א' א, לא). \u0003\"כריעה\",\u0004 היא \u0003על ברכים, וכן הוא אומר: \"מכרע על־ברכיו\"\u0004 (מלכים א' ח, נד). \u0003\"השתחואה\"\u0004 — \u0003זו פישוט ידים ורגלים, שנאמר: \"הבוא נבוא אני ואמך ואחיך להשתחות לך ארצה\"\u0004 (בראשית לז, י), משמע שהמשתחוה שוכב כולו על הארץ.","מסופר, כי החכם \u0003לוי אחוי\u0004 \u0005[הראה]\u0006 \u0003קידה\u0004 כפי שהיה עושה כהן גדול, \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבי,\u0004 וקידה זו היתה מסובכת ביותר, שהיה הכהן הגדול נועץ אגודלי רגליו בקרקע ונשען עליהם ומתכופף מלוא קומתו עד שמגיעים פניו לקרקע ומזדקף בבת אחת בלא סיוע ידיו, ורצה להראות כיצד הדבר נעשה, \u0003ואיטלע\u0004 \u0005[נעשה צולע]\u0006 שנקע את ירכו מחמת המאמץ.","ושואלים: \u0003והא קא גרמא ליה\u0004 \u0005[וכי זו\u0006 הקידה שהראה היא ש\u0005גרמה לו]\u0006 שבגללה נעשה צולע? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: לעולם אל יטיח\u0004 (ישליך) \u0003אדם דברים כלפי מעלה,\u0004 כלומר, אל יאמר אדם דברים חריפים ודברי תרעומת בתפילתו, \u0003שהרי אדם גדול הטיח דברים כלפי מעלה ואיטלע\u0004 \u0005[נעשה צולע]\u0006 \u0003ומנו\u0004 \u0005[ומי הוא] —\u0006 \u0003לוי.\u0004 ואם כן, הלא צליעתו של לוי באה לו כעונש על מה שאמר בתפילתו (ראה תענית כה,א)! ומשיבים: \u0003הא והא גרמא ליה\u0004 \u0005[זו וזו גרמה לו],\u0006 שכיון שהטיח דברים היה ראוי לעונש, ולכן אירעה לו תקלה בשעת מאמץ.","\u0003אמר רב חייא בר אבין: חזינא להו\u0004 \u0005[ראיתי אותם]\u0006 את \u0003אביי\u0004"],["\u0003ורבא דמצלי אצלויי\u0004 \u0005[שהיו נוטים קצת\u0006 על צידיהם\u0005]\u0006 ולא היו נופלים על פניהם ממש, כפי שאמרנו שאין אדם חשוב נופל על פניו.","שנינו במשנה: \u0003ביום טוב\u0004 קוראים \u0003חמשה\u0004 בתורה, \u0003ביום הכפורים\u0004 — \u0003ששה,\u0004 ואין פוחתים ממספר קרואים זה, אבל מוסיפים עליהם כרצונם. ושואלים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 שהרי אינה \u0003לא\u0004 כשיטת \u0003ר' ישמעאל ולא\u0004 כשיטת \u0003ר' עקיבא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ביום טוב — חמשה, וביום הכפורים — ששה, ובשבת — שבעה, אין פוחתין מהן ואין מוסיפין עליהן,\u0004 אלו \u0003דברי ר' ישמעאל, ר' עקיבא אומר: ביום טוב — חמשה, וביום הכפורים — שבעה, ובשבת — ששה, אין פוחתים מהם אבל מוסיפין עליהן.\u0004","ומעתה נברר \u0003מני\u0004 \u0005[כ\u0006שיטת \u0005מי היא]\u0006 משנתנו? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שהיא כשיטת \u0003ר' ישמעאל\u0004 — אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003תוספת,\u0004 שהרי במשנתנו אמרו שמותר להוסיף על מנין הקרואים! \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' עקיבא קשיא\u0004 \u0005[קשה]\u0006 מההבדל בין שיטתו לשיטת המשנה לגבי הימים שבהם קוראים \u0003ששה ושבעה!\u0004","\u0003אמר רבא:\u0004 משנתנו כשיטת ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל היא. דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: ביום טוב\u0004 קוראים \u0003חמשה, ביום הכפורים\u0004 — \u0003ששה, בשבת\u0004 — \u0003שבעה, אין פוחתים מהם אבל מוסיפים עליהם,\u0004 אלו \u0003דברי ר' ישמעאל.\u0004","ומעירים: אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 משיטת \u0003ר' ישמעאל\u0004 כאן במשנתנו, על שיטת \u0003ר' ישמעאל\u0004 עצמו כפי שהיא מובאת בברייתא? ומשיבים: \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים\u0006 הם, ושניהם \u0005לשיטת]\u0006 \u0003ר' ישמעאל.\u0004","ושואלים: \u0003מאן תנא להא דתניא\u0004 \u0005[מי שנה את זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ביום טוב מאחרין לבוא\u0004 לבית הכנסת, לפי שמכינים לסעודה, \u0003וממהרין לצאת\u0004 לסעוד סעודת החג, \u0003ביום הכפורים ממהרין לבוא, ומאחרין לצאת, ובשבת ממהרין לבוא,\u0004 שהרי הכל כבר מוכן, \u0003וממהרין לצאת\u0004 לסעוד סעודת שבת. \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי זה כשיטת \u0003ר' עקיבא, דאית ליה גברא יתירא\u0004 \u0005[שיש לו אדם יתר\u0006 ביום הכיפורים\u0005]\u0006 ולכן ביום זה התפילה ארוכה יותר? ודוחים: אין מכאן הוכחה, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' ישמעאל,\u0004 ומה שמאריכים בבית הכנסת ביום הכיפורים — משום \u0003דנפיש סידורא דיומא\u0004 \u0005[שמרובה סדר היום],\u0006 שהרי התפילות והוידויים מרובים בו, ולכן מתארכת בו התפילה.","לענין מספרי הקרואים שואלים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003שלשה חמשה ושבעה\u0004 קרואים \u0003כנגד מי\u0004 קבעו אותם? \u0003פליגי\u0004 \u0005[חלוקים]\u0006 \u0003בה ר' יצחק בר נחמני וחד דעמיה\u0004 \u0005[ואחד ש\u0006היה \u0005עמו],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 — \u0003ר' שמעון בן פזי. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שגרסו את הדבר להיפך: ש\u0003ר' שמעון בן פזי וחד דעמיה\u0004 \u0005[ואחד ש\u0006היה \u0005עמו]\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]\u0006 זה \u0003ר' יצחק בר נחמני, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' שמואל בר נחמני. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהוא \u0003כנגד ברכת כהנים,\u0004 שבשלושת פסוקי ברכת כהנים יש לפי הסדר שלוש חמש ושבע מילים. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כנגד שלשה שומרי הסף\u0004 (מלכים ב' כה, יח), \u0003חמשה מרואי פני המלך\u0004 (מלכים ב' כה, יט) ו\u0003שבעה רואי פני המלך\u0004 (אסתר א, יד).","וכיוצא בו \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בברייתא: \u0003שלשה חמשה ושבעה\u0004 קרואים, כנגד מי — \u0003שלשה שומרי הסף, חמשה מרואי פני המלך, שבעה רואי פני המלך.\u0004 כאשר שנה רב יוסף דבר זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא פריש לן מר\u0004 \u0005[פירש לנו אדוני]\u0006 דבר זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא הוה ידענא\u0004 \u0005[ידעתי]\u0006 \u0003דצריכתו ליה\u0004 \u0005[שאתם נזקקים לו,\u0006 לדבר זה\u0005],\u0006 שהרי הדבר נוגע בענין המתחדש תמיד, \u0003ומי בעיתו מינאי מילתא\u0004 \u0005[וכי שאלתם ממני דבר]\u0006 \u0003ולא אמרי לכו\u0004 \u0005[אמרתי לכם]?!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003יעקב מינאה\u0004 \u0005[המין]\u0006 \u0003לרב יהודה: הני\u0004 \u0005[אותם]\u0006 \u0003ששה\u0004 קרואים של \u0003יום הכפורים, כנגד מי\u0004 הם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כנגד ששה שעמדו מימינו של עזרא וששה משמאלו, שנאמר: \"ויעמד עזרא הספר על מגדל עץ אשר עשו לדבר ויעמד אצלו מתתיה ושמע ועניה ואוריה וחלקיה ומעשיה על ימינו ומשמאלו פדיה ומישאל ומלכיה וחשם וחשבדנה זכריה משלם\"\u0004 (נחמיה ח, ד), ותוהים:","\u0003הני\u0004 \u0005[אלה]\u0006 שמשמאלו הרי \u0003שבעה הוו\u0004 \u0005[הם]\u0006 ולא שישה! ומשיבים: \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003זכריה היינו\u0004 \u0005[זהו]\u0006 \u0003משלם,\u0004 כלומר אין אלה שני אנשים שונים, אלא כינוי לאותו אדם עצמו, \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003קראו משלם — דמישלם בעובדיה\u0004 \u0005[שמושלם\u0006 היה \u0005במעשיו].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכל עולין\u0004 (נחשבים) \u0003למנין שבעה\u0004 קרואים \u0003ואפילו קטן, ואפילו אשה. אבל אמרו חכמים: אשה לא תקרא בתורה, מפני כבוד צבור.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: ה\u0003מפטיר, מהו שיעלה\u0004 ויחשב \u0003למנין שבעה\u0004 קרואים? נחלקו בכך \u0003רב הונא ורב ירמיה בר אבא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: עולה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אינו עולה. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהוא \u0003עולה\u0004 למנין שבעה קרואים — \u0003דהא קרי\u0004 \u0005[שהרי\u0006 הוא \u0005קורא]\u0006 גם בתורה עצמה,","\u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 ש\u0003אינו עולה\u0004 — סבור \u0003כ\u0004דברי \u0003עולא,\u0004 ש\u0003אמר עולא: מפני מה המפטיר בנביא צריך שיקרא בתורה תחלה,\u0004 למרות שהוא עולה כדי לקרוא בנביא — \u0003מפני כבוד תורה,\u0004 שלא יאמרו שכבוד הנביא וכבוד התורה שוים ועולה לבימה רק מפני כבוד הנביא, \u0003וכיון\u0004 שקריאתו רק \u0003משום כבוד תורה הוא — למנינא לא סליק\u0004 \u0005[למנין\u0006 הקרואים \u0005אינו עולה].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003המפטיר בנביא לא יפחות מעשרים ואחד פסוקים\u0004 של דברי נבואה שהם \u0003כנגד שבעה שקראו בתורה\u0004 שהרי אותם שבעה שקראו בתורה קראו גם הם לכל הפחות עשרים ואחד פסוקים, שלושה לכל אחד. \u0003ואם איתא\u0004 \u0005[יש]\u0006 אם אמנם המפטיר אינו ממנין שבעת הקרואים ונוסף הוא עליהם, הרי \u0003עשרים וארבעה הויין\u0004 \u0005[הם]\u0006 ולא עשרים ואחד! שהרי גם כנגדו צריך לקרוא שלושה פסוקים בהפטרה. ומשיבים: \u0003כיון\u0004 ש\u0003משום כבוד\u0004 ה\u0003תורה הוא\u0004 שקורא המפטיר בתורה"],["— \u0003כנגדו נמי לא בעי\u0004 \u0005[גם כן אינו צריך]\u0006 להוסיף בפסוקי ההפטרה.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על ברייתא זו \u0003רבא: והרי\u0004 ההפטרה המתחילה \u0003\"עלותיכם ספו\"\u0004 (ירמיהו ז, כא-כח) \u0003דלא הויין עשרין וחד, וקרינן\u0004 \u0005[שאין הם עשרים ואחד\u0006 פסוקים, \u0005ואנו קוראים\u0006 אותה\u0005]\u0006! ומשיבים: \u0003שאני התם דסליק עניינא\u0004 \u0005[שונה שם שנגמר הענין]\u0006 אחרי כן, ואין מוסיפים מנושא אחר רק כדי להשלים את מספר הפסוקים.","ושואלים: \u0003והיכא\u0004 \u0005[והיכן]\u0006 ש\u0003לא סליק עניינא\u0004 \u0005[נגמר הענין]\u0006 \u0003לא\u0004 מפסיקים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שמואל בר אבא: זמנין סגיאין הוה קאימנא קמיה\u0004 \u0005[פעמים רבות הייתי עומד לפני]\u0006 \u0003ר' יוחנן\u0004 כמתורגמן, \u0003וכי הוה קרינן\u0004 \u0005[וכאשר היינו קוראים]\u0006 \u0003עשרה פסוקי\u0004 \u0005[פסוקים]\u0006 \u0003אמר לן\u0004 \u0005[לנו]:\u0006 \u0003אפסיקו\u0004 \u0005[הפסיקו],\u0006 הרי שמפסיקים אף בפחות! ומשיבים: ב\u0003מקום שיש תורגמן\u0004 \u0005[מתורגמן]\u0006 \u0003שאני\u0004 \u0005[שונה],\u0006 שכיון שהמתרגם מאריך ומוסיף בדברים, מקצרים לעיתים מפני טורח הציבור. \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב תחליפא בר שמואל: לא שנו\u0004 שיש לקרוא בהפטרה עשרים ואחד פסוקים \u0003אלא במקום שאין תורגמן, אבל מקום שיש תורגמן — פוסק\u0004 אפילו בפחות.","\u0003אין פורסים על שמע,\u0004 שהמאחרים לבוא לבית הכנסת אחר שסיימו הציבור לומר קריאת שמע — הותר להם לדלג על חלק מברכותיה כדי שיוכלו להתפלל תפילת שמונה עשרה עם הציבור, ועומד אחד מהם ואומר קדיש ו\"ברכו\" וברכה ראשונה מברכות קריאת שמע, וכיון שאינם אומרים את כל הברכות נחשב הדבר כפרס (מחצית), \u0003ואין עוברים לפני התיבה\u0004 בתפילת שמונה עשרה, \u0003ואין\u0004 כהנים \u0003נושאים את כפיהם, ואין קוראין בתורה, ואין מפטירין בנביא,\u0004","\u0003ואין עושים מעמד ומושב\u0004 כאשר חוזרים מקבורת המת, \u0003ואין אומרים ברכת אבלים ותנחומי אבלים\u0004 לאבלים, \u0003ו\u0004כן אין אומרים \u0003ברכת חתנים, ואין מזמנים\u0004 בברכת המזון \u0003ב\u0004הזכרת \u0003שם\u0004 שמים — אם היה בכל אחד מאלה \u0003פחות מעשרה\u0004 אנשים. \u0003וב\u0004פדיון \u0003קרקעות\u0004 מן ההקדש צריך שיהיו שם \u0003תשעה\u0004 אנשים (אפילו שאינם כהנים) \u0003ו\u0004עוד \u0003כהן\u0004 אחד בנוסף להם (והרי הם עשרה יחד), \u0003ו\u0004כן ב\u0003אדם כיוצא בהן\u0004 בפדיונו, שכשיש לפדותו מן ההקדש, צריכים שיהיו תשעה וכהן.","שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שצריכים עשרה למנין? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונקדשתי בתוך בני ישראל\"\u0004 (ויקרא כב, לב), ללמדנו ש\u0003כל דבר שבקדושה לא יהא\u0004 ב\u0003פחות מעשרה\u0004 אנשים.","ושואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד למדים מפסוק זה שיש צורך במנין של עשרה? ומסבירים, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 מגזירה שווה של המילים \u0003'תוך' 'תוך', כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ונקדשתי בתוך בני ישראל\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בענין מות קורח וכל עדתו: \u0003\"הבדלו מתוך העדה\"\u0004 (במדבר טז, כא),","\u0003ואתיא\u0004 \u0005[ובאה,\u0006 נלמדת\u0005]\u0006 גזירה שווה \u0003'עדה' 'עדה', דכתיב התם\u0004 \u0005[שנאמר שם]\u0006 במרגלים: \u0003\"עד מתי לעדה הרעה הזאת\"\u0004 (במדבר יד, כז), \u0003מה להלן\u0004 במרגלים היו באותה עדה \u0003עשרה\u0004 אנשים (שהרי שנים עשר היו, ויהושע וכלב אינם בכלל העדה הרעה) \u0003אף כאן\u0004 \"העדה\" היא \u0003עשרה,\u0004 ואנחנו למדים ש\"בתוך בני ישראל\" הוא כמו \"מתוך העדה\", משמע שפחות מעשרה אינו קרוי קהל, ואין אומרים בו דבר שבקדושה (\"ונקדשתי\").","על ידי הסבר זה מובנים דברים רבים שנאמרו במשנה שיש בהם משום דברים שבקדושה הנאמרים בקהל. שנינו בה: \u0003ואין עושים מעמד ומושב פחות מעשרה,\u0004 והרי דבר זה אינו דבר שבקדושה, אלא טעמו \u0003כיון דבעי למימר\u0004 \u0005[ש\u0006הוא \u0005צריך לומר]\u0006 כפי הנוסח הרגיל של מעמד ומושב: \u0003\"עמדו יקרים עמודו, שבו יקרים שבו\", בציר\u0004 \u0005[\u0006ב\u0005פחות]\u0006 \u0003מעשרה לאו אורח ארעא\u0004 \u0005[לא דרך ארץ]\u0006 הוא לומר בסגנון מכובד רק למספר מועט של אנשים.","עוד שנינו: \u0003ואין אומרים ברכת אבלים וברכת חתנים,\u0004 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003ברכת אבלים — ברכת רחבה,\u0004 שהיו המלווים באים לרחבה מיוחדת ומברכים את האבלים שהמקום ינחם אותם. וכפי ש\u0003אמר ר' יצחק אמר ר' יוחנן: ברכת אבלים\u0004 נאמרת \u0003בעשרה, ואין\u0004 ה\u0003אבלים\u0004 עצמם נחשבים \u0003מן המנין,\u0004 שצריך עשרה מלבדם. ו\u0003ברכת חתנים\u0004 אף היא נאמרת \u0003בעשרה, ו\u0004אולם ה\u0003חתנים\u0004 עצמם נחשבים \u0003מן המנין.\u0004","עוד שנינו: \u0003ואין מזמנים על המזון ב\u0004הזכרת \u0003שם\u0004 שמים ב\u0003פחות מעשרה.\u0004 וטעמו: \u0003כיון דבעי למימר\u0004 \u0005[ש\u0006הוא \u0005צריך לומר]\u0006 את הנוסח \u0003\"נברך לאלהינו\", בציר\u0004 \u0005[\u0006ב\u0005פחות]\u0006 \u0003מעשרה לאו אורח ארעא\u0004 \u0005[לא דרך ארץ]\u0006 הוא להזכיר שם שמים למספר מועט של אנשים.","עוד שנינו במשנה: \u0003ו\u0004לפדיון \u0003הקרקעות\u0004 מן ההקדש צריך שיהיו \u0003תשעה\u0004 אנשים \u0003וכהן, ו\u0004פדיון \u0003אדם כיוצא בהן.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים האלו]\u0006 שצריך עשרה בפדיון קרקעות ואחד מהם כהן?","\u0003אמר שמואל: עשרה כהנים כתובים בפרשה,\u0004 כלומר, עשר פעמים נאמר בפרשה זו שהכהן מעריך את ההקדשות, ופירוט הדברים: \u0003חד לגופיה\u0004 \u0005[\u0006פעם \u0005אחת\u0006 נלמד \u0005לגופו]\u0006 שצריך שיהיה כהן אחד בפדיון זה, \u0003וחד למעוטי\u0004 \u0005[ואחד\u0006 כדי \u0005למעט]\u0006 שיהא זה רק כהן, \u0003ואידך\u0004 \u0005[ו\u0006יתר \u0005האחרים]\u0006 \u0003הוי\u0004 \u0005[הרי]\u0006 \u0003מיעוט אחר מיעוט,\u0004 וכלל הוא ש\u0003אין מיעוט אחר מיעוט אלא לרבות.\u0004 שכיון שמזכיר כמה וכמה פעמים \"כהן\", שמשמעו לכאורה להוציא ולמעט את הישראלים, אנו מפרשים שמיעוט אחר מיעוט בא לרבות כל אדם, ולכן אנו מרבים שיהיו \u0003תשעה ישראלים וחד\u0004 \u0005[ואחד]\u0006 \u0003כהן.\u0004","ושואלים: אם נלמד בדרך של מיעוט אחר מיעוט, אם כן \u0003ואימא\u0004 \u0005[ואמור]\u0006 באופן אחר שיש כאן מיעוט ואחריו שוב מיעוט, ושוב מוזכר כהן ושוב מיעוט, ואם כן יצטרכו שיהיו לפי חשבון זה \u0003חמשה כהנים וחמשה ישראלים!\u0004 ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה],\u0006 שאין ההסבר ברור דיו בנקודה זו.","שנינו: \u0003ואדם כיוצא בהן.\u0004 ושואלים: \u0003אדם מי\u0004 \u0005[האם]\u0006 הוא נעשה \u0003קדוש\u0004 שצריך לדון בפדיונו?","\u0003אמר ר' אבהו:\u0004 מדובר \u0003ב\u0004אדם ש\u0003אומר \"דמי עלי\",\u0004 כלומר, אני נודר למקדש את הכסף שאני שווה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר \"דמי עלי\" שמין\u0004 (מעריכים) \u0003אותו כעבד,\u0004 ולפי ערכו כעבד כך נותן למקדש. \u0003ועבד איתקש\u0004 \u0005[הוקש,\u0006 הושווה\u0005]\u0006 במקרא \u0003לקרקעות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והתנחלתם אתם לבניכם אחריכם לרשת אחזה\"\u0004 (ויקרא כה, מו), ולכן, כשם שפדיון קרקעות בעשרה — אף פדיון האדם בעשרה.","\u0003הקורא בתורה\u0004 — \u0003לא יפחות משלשה פסוקים, ו\u0004כשמתרגם — \u0003לא יקרא למתורגמן יותר מפסוק אחד,\u0004 כדי שלא יתבלבל."],["\u0003ובנביא\u0004 מתרגם \u0003שלשה\u0004 פסוקים כאחד, שכן בדברי תורה אם יתרגם שלא כראוי עלול הוא להטעות את השומעים בהלכה, מה שאין כן בנביא. \u0003היו שלשתן\u0004 שלושת הפסוקים \u0003שלש פרשיות,\u0004 שכל פסוק היא פרשיה בפני עצמה — \u0003קורין אחד אחד.\u0004","\u0003מדלגין בנביא\u0004 מקטע לקטע \u0003ואין מדלגין בתורה. ועד כמה הוא מדלג — עד כדי שלא יפסוק המתורגמן,\u0004 כלומר, אם יכול לגלול את המגילה או להפוך בדפי הספר כל עוד המתורגמן מתרגם, שלא ייראה הדבר כהפסקה, דבר היכול להתפרש כזילזול בכבוד הציבור.","שואלים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003שלשה פסוקים\u0004 שאין לפחות מהם בקריאת התורה, \u0003כנגד מי\u0004 קבעו? \u0003אמר רב אסי: כנגד תורה נביאים וכתובים.\u0004","שנינו במשנה: \u0003ולא יקרא למתורגמן יותר מפסוק אחד, ובנביא\u0004 — \u0003שלשה פסוקים, ואם היו שלשתן\u0004 שלושת הפסוקים \u0003שלש פרשיות\u0004 — \u0003קורא אחד אחד.\u0004 ומביאים דוגמא, \u0003כגון: \"כי כה אמר ה' חנם נמכרתם\"\u0004 (ישעיהו נב, ג), ואחריו: \u0003\"כי כה אמר ה' אלהים מצרים ירד עמי בראשנה\"\u0004 (ישעיהו נב, ד), ואחריו: \u0003\"ועתה מה לי פה נאם ה'\"\u0004 (ישעיהו נב, ה), שהם שלושה פסוקים סמוכים, שכל אחד מהם הוא פרשיה בפני עצמה.","שנינו במשנה: \u0003מדלגין בנביא ואין מדלגין בתורה. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו, שהכהן הגדול ביום הכיפורים \u0003קורא\u0004 פרשת \u0003\"אחרי מות\"\u0004 (ויקרא ט״ז:א׳), \u0003ו\u0004קורא בפרשת \u0003\"אך בעשור\"\u0004 (ויקרא כג, כז), \u0003והא קא\u0004 \u0005[והרי\u0006 בקריאה זו \u0005הוא]\u0006 \u0003מדלג\u0004 בתורה, שהרי אין אלו פרשיות סמוכות!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה],\u0006 כי \u0003כאן\u0004 שאמרו שלא ידלג, הרי זה \u0003בכדי שיפסוק\u0004 (שיצטרך לעשות הפסקה) \u0003המתורגמן, וכאן\u0004 שהתירו לדלג הוא \u0003בכדי שלא יפסוק המתורגמן.\u0004","ומקשים: \u0003והא עלה קתני\u0004 \u0005[והרי עליה\u0006 על משנה זו \u0005שנינו]:\u0006 \u0003מדלגין בנביא ואין מדלגין בתורה, ועד כמה הוא מדלג — עד כדי שלא יפסוק המתורגמן,\u0004 ו\u0003מכלל\u0004 הדברים אתה למד ש\u0003בתורה כלל כלל לא\u0004 ידלג!","\u0003אלא אמר אביי:\u0004 יש לחזור מן התירוץ הקודם ו\u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 ויש לתרץ באופן אחר: \u0003כאן\u0004 שאמרו שמותר לדלג, הוא \u0003בענין\u0004 (בנושא) \u0003אחד, כאן\u0004 שלא התירו לדלג, הרי זה \u0003בשתי עניינות\u0004 בשני נושאים שונים. \u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003מדלגין בתורה בענין אחד, ובנביא\u0004 אפילו \u0003בשני עניינין, כאן וכאן,\u0004 בתורה ובנביא, מדלגים רק \u0003בכדי שלא יפסוק המתורגמן.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מדלגין מנביא לנביא\u0004 אפילו באותו ענין, אבל \u0003בנביא של שנים עשר\u0004 (בספרי תרי עשר) כיון שהוא נחשב כספר אחד — \u0003מדלג, ובלבד שלא ידלג\u0004 בכל מקרה \u0003מסוף הספר לתחילתו,\u0004 שלא יקדים את הפסוק המאוחר, שאז הדבר נראה לכל כדילוג, ואם רוצה לדלג — יקרא בכל אופן לפי הסדר.","\u0003המפטיר בנביא הוא\u0004 זה שמכבדים אותו להיות ה\u0003פורס על שמע\u0004 (מברך בקול ברכות קריאת שמע) \u0003והוא עובר לפני התיבה\u0004 בתפילת שמונה עשרה, \u0003והוא נושא את כפיו,\u0004 אם כהן הוא. \u0003ואם היה\u0004 המפטיר \u0003קטן,\u0004 שהרי למפטיר אפשר לקרוא גם ילד קטן שאינו ראוי להיות שליח ציבור — הרי \u0003אביו או רבו עוברים על ידו\u0004 (במקומו, בשבילו).","\u0003קטן קורא בתורה ו\u0004כן \u0003מתרגם\u0004 את הדברים לארמית, \u0003אבל אינו פורס על שמע ואינו עובר לפני התיבה ואינו נושא את כפיו.\u0004","\u0003פוחח\u0004 (מי שאינו לבוש כהלכה ובשרו מגולה) — \u0003פורס את שמע ומתרגם, אבל אינו קורא בתורה\u0004 מפני כבוד התורה, \u0003ו\u0004כן \u0003אינו עובר לפני התיבה, ואינו נושא את כפיו\u0004 בברכת כהנים מפני כבוד הציבור.","\u0003סומא\u0004 (עיוור) — \u0003פורס את שמע ומתרגם. ר' יהודה אומר: כל שלא ראה מאורות\u0004 השמש הירח והכוכבים \u0003מימיו,\u0004 כלומר: עיוור מלידה — \u0003אינו פורס על שמע,\u0004 שהרי הברכה הראשונה לפני קריאת שמע היא ברכה על המאורות, וכיצד יברך מי שלא ראה אותם.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מדוע]\u0006 המפטיר בנביא נותנים לו את כל שאר התפקידים הללו? \u0003רב פפא אמר: משום כבוד\u0004 עושים זאת, שכיון שההפטרה היתה ניתנת גם לילדים קטנים, היה הדבר נחשב כזלזול בכבודו של אדם שאינו עולה לקרוא בתורה כאחד הקרואים, אלא להפטרה בלבד, וכדי לפצותו נותנים לו זכות לשמש בתפקידים המכובדים בבית הכנסת. \u0003רבה בר שימי אמר\u0004 טעם אחר: \u0003משום דאתי לאינצויי\u0004 \u0005[שיבואו להתקוטט],\u0006 שמא יאמר אדם לחבירו: אני קיבלתי רק תפקיד שאינו חשוב כקריאת ההפטרה, ואתה תעבור לפני התיבה?! ולכן נותנים זאת לאדם אחד.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 אם זהו הטעם או זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 באופן \u0003דעביד\u0004 \u0005[ש\u0006העובר לפני התיבה \u0005עושה]\u0006 \u0003בחנם,\u0004 ואין איש מן המתפללים מקבל שכר, שעדיין יש כאן משום כבוד, אבל משום קטטה אין כאן.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003ואם היה קטן — אביו או רבו עוברים על ידו\u0004 (בשבילו, במקומו)\u0003. אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שהטעם הוא \u0003משום נצויי\u0004 \u0005[קטטה]\u0006 — וכי ה\u0003קטן בר נצויי\u0004 \u0005[בן קטטה]\u0006 \u0003הוא?\u0004 שהרי ודאי לא ישימו לב אליו, ואין איפוא חשש לקטטה, ואם כן נראה שאין חוששים לטעם זה!","ודוחים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר — שהטעם הוא \u0003משום כבוד —\u0004 וכי \u0003קטן בר\u0004 \u0005[בן]\u0006 \u0003כבוד הוא,\u0004 וצריך הוא שיכבדוהו כפיצוי לקריאת ההפטרה? \u0003אלא — איכא\u0004 \u0005[יש]\u0006 \u0003כבוד אביו וכבוד רבו\u0004 הנוגעים בדבר, ובשלהם עשו תקנה זו,"],["\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר \u0003איכא נצויי\u0004 \u0005[יש קטטה]\u0006 של \u0003אביו ונצויי\u0004 \u0005[וקטטה]\u0006 של \u0003רבו.\u0004","שנינו במשנה: \u0003פוחח\u0004 (מי שאינו לבוש כהלכה ובשרו מגולה) — \u0003פורס על שמע\u0004 ומתרגם, אבל אינו קורא בתורה. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003עולא בר רב מאביי: קטן פוחח מהו שיקרא בתורה?\u0004 האם יש מקום לומר שכיון שקטן אינו מוזהר על \"ולא ייראה בך ערוות דבר\" (דברים כג, טו), אין למונעו בשל כך מלקרוא בתורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: לפי דרך מחשבה זו \u0003ותבעי לך\u0004 \u0005[ותישאל\u0006 תסתפק \u0005לך]\u0006 אם כן על קטן \u0003ערום,\u0004 שמכיון שהוא קטן אין בו משום \"ערות דבר\", אלא \u0003ערום מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 יקרא — \u0003משום כבוד\u0004 ה\u0003צבור, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לא יקרא פוחח \u0003משום כבוד\u0004 ה\u0003צבור.\u0004","שנינו במשנה ש\u0003סומא פורס על שמע\u0004 ור' יהודה חולק, ולדעתו כל שלא ראה מאורות מימיו (עיוור מלידה) אינו יכול לברך. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו לר' יהודה:\u0004 אין צורך שאדם יראה דבר בעיניו על מנת שיוכל לברך עליו ברכה, וכיוצא בזה \u0003הרבה צפו לדרוש ב\u0004מעשה ה\u0003מרכבה\u0004 של ה' בעולמות העליונים, \u0003ו\u0004אף על פי ש\u0003לא ראו אותה מימיהם,\u0004 משמע שהראיה אינה מעכבת.","\u0003ור' יהודה\u0004 משיב על כך: יש לחלק, כי \u0003התם באבנתא דליבא תליא מילתא, והא קא מיכוין וידע\u0004 \u0005[שם\u0006 במעשה המרכבה, \u0005בהבנת הלב תלוי הדבר, והרי הוא מכוון ויודע]\u0006 אף על פי שאינו רואה בעצמו, אולם \u0003הכא\u0004 \u0005[כאן]\u0006 בברכת המאורות \u0003משום הנאה הוא, והא לית ליה\u0004 \u0005[הרי אין לו]\u0006 לעיוור \u0003הנאה\u0004 מן המאורות, ולכן אינו יכול לברך עליהם.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה טעמם — לדעתם \u0003אית ליה\u0004 \u0005[יש לו]\u0006 לעיוור \u0003הנאה\u0004 מן המאורות, ו\u0003כ\u0004דברי \u0003ר' יוסי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יוסי: כל ימי הייתי מצטער על מקרא זה\u0004 שלא הבנתי את פירושו, שנאמר: \u0003\"והיית ממשש בצהרים כאשר ימשש העור באפלה\"\u0004 (דברים כח, כט), והייתי תוהה: \u0003וכי מה אכפת ליה\u0004 \u0005[לו]\u0006 \u0003לעור בין אפילה לאורה,\u0004 אם אינו מרגיש בהבדל שביניהם? ואם כן מדוע מדבר הכתוב על העיוור באפילה דווקא?","\u0003עד שבא מעשה לידי. פעם אחת הייתי מהלך באישון\u0004 (בחשכת) \u0003לילה ואפלה, וראיתי סומא שהיה מהלך בדרך ואבוקה\u0004 (לפיד) \u0003בידו. אמרתי לו: בני, אבוקה זו למה לך?\u0004 הלא עיוור אתה! \u0003אמר לי: כל זמן שאבוקה בידי, בני אדם רואים אותי ומצילים אותי מן הפחתין\u0004 (בורות) \u0003ומן הקוצין ומן הברקנין.\u0004 הרי שאף שהעיוור איננו נהנה במישרין מראיית האור, מכל מקום מציאות האור מועילה לו. ומשום כך יכול גם הוא לברך על המאורות.","\u0003כהן שיש בידיו מומין — לא ישא את כפיו\u0004 לברך, שכיון שיש בהן מומים הרי זה גורם לאנשים להסתכל בו, ואסור להסתכל בידי הכהנים כשמברכים את העם לפי שהשכינה שורה עליהם באותה שעה. \u0003ר' יהודה אומר: אף מי שהיו ידיו צבועות\u0004 ב\u0003סטיס\u0004 (צבע כחול) — \u0003לא ישא את כפיו\u0004 מאותו טעם, \u0003מפני שהעם מסתכלים בו.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003מומים שאמרו\u0004 שפוסלים את הכהן מלברך, הכוונה למומים ש\u0003בפניו, ידיו ורגליו,\u0004 ולא מומים שבסתר. \u0003אמר ר' יהושע בן לוי:\u0004 כהן שהיו \u0003ידיו בוהקניות\u0004 (מלאות כתמים לבנים) — \u0003לא ישא את כפיו. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ידיו בוהקניות — לא ישא את כפיו.\u0004 היו כפיו \u0003עקומות\u0004 או \u0003עקושות\u0004 (מעוותות) — \u0003לא ישא את כפיו.\u0004","בדומה לכך \u0003אמר רב אסי: חיפני\u0004 (אדם מהעיר חיפה) \u0003ובשיני\u0004 (בית שאני, אדם מהעיר בית שאן) — \u0003לא ישא את כפיו,\u0004 שלא ידעו בני אותם המקומות לבטא את האותיות הגרוניות כראוי. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין מורידים לפני התיבה לא אנשי בית שאן ולא אנשי בית חיפה ולא אנשי טבעונין — מפני ש\u0004הם \u0003קורין לאלפין עיינין ולעיינין אלפין,\u0004 ועל ידי כך משבשים את משמעות הדברים בתפילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא לר' שמעון בר רבי\u0004 תוך כדי שיחתם: \u0003אלמלי אתה\u0004 (אילו היית) \u0003לוי — פסול אתה מן הדוכן\u0004 לשיר \u0003משום דעבי קלך\u0004 \u0005[שקולך עבה]\u0006 ואינך ראוי לשירה. נפגע ר' שמעון, \u0003אתא\u0004 \u0005[בא]\u0006 ו\u0003אמר ליה לאבוה\u0004 \u0005[לו ל\u0006רבי \u0005אביו]\u0006 את תוכן דברי רבי חייא\u0005.\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי: \u0003זיל אימא ליה\u0004 \u0005[לך אמור לו]\u0006 דבר כיוצא בכך: \u0003כשאתה מגיע אצל\u0004 הפסוק \u0003\"וחכיתי לה'\"\u0004 (ישעיהו ח, יז) \u0003לא נמצאת מחרף ומגדף?!\u0004 שכן ר' חייא שהיה מבבל לא היה יכול להבדיל בין חי\"ת לה\"א.","\u0003אמר רב הונא, זבלגן\u0004 מי שעיניו זולפות דמעה תמיד \u0003לא ישא את כפיו\u0004 מפני שמסתכלין בו. והא ההוא דהוה בשיבבותיה \u0005[והרי אותו\u0006 כהן בעל מום \u0005שהיה בשכנותו]\u0006 של \u0003רב הונא והוה פריס ידיה\u0004 \u0005[והיה פורס,\u0006 נושא \u0005את כפיו]!\u0006 ומשיבים: \u0003ההוא דש בעירו הוה\u0004 \u0005[היה],\u0006 כלומר, היה מצוי במקום והתרגלו אליו בני עירו, וכיון שהם רגילים בו, שוב אין מסתכלים במומו. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003זבלגן\u0004 — \u0003לא ישא את כפיו, ואם היה דש בעירו — מותר.\u0004","\u0003אמר ר' יוחנן: סומא באחת מעיניו\u0004 — \u0003לא ישא את כפיו\u0004 מפני שהעם מסתכלים במומו. ושואלים: \u0003והא ההוא דהוה בשיבבותיה\u0004 \u0005[והרי אותו\u0006 כהן שהיה עיוור באחת מעיניו \u0005שהיה בשכנותו]\u0006 של \u0003ר' יוחנן דהוה פריס ידיה\u0004 \u0005[שהיה פורס,\u0006 נושא \u0005את כפיו]!\u0006 ומשיבים: הכהן \u0003ההוא דש בעירו הוה\u0004 \u0005[היה].\u0006 \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003סומא באחת מעיניו לא ישא את כפיו, ואם היה דש בעירו — מותר.\u0004","שנינו במשנה, \u0003ר' יהודה אומר: מי שהיו ידיו צבועות\u0004 — \u0003לא ישא את כפיו. תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: מכל מקום, \u0003אם רוב אנשי העיר מלאכתם בכך\u0004 בצביעה — \u0003מותר,\u0004 שבודאי אין שמים לב לכך.","\u0003האומר: \"איני עובר לפני התיבה ב\u0004בגדים \u0003צבועין\"\u0004 אלא בלבנים בלבד — \u0003אף בלבנים לא יעבור,\u0004 שכן יש חשש מינות במי שמקפיד על צבע הבגד בתפילה ולכן ראוי לפוסלו מכל תפילה. וכן מי שאומר: \u0003\"בסנדל איני עובר\" — אף יחף לא יעבור,\u0004 שאף הוא נוהג שלא על דעת חכמים.","\u0003העושה תפלתו\u0004 (התפילין שלו) \u0003עגולה\u0004 — הרי זו \u0003סכנה,\u0004 בכל מקום וזמן שגוזרים על הנחת תפילין, ואף ששינו ועשו תפילין עגולות, הסכנה עדיין קיימת, \u0003ואין בה מצוה,\u0004 שהרי המצוה היא לעשותה מרובעת דווקא. \u0003נתנה\u0004 את התפילה של ראש \u0003על מצחו\u0004 ולא במקומה על קצה שערותיו, \u0003או\u0004 תפילה של יד \u0003על פס ידו\u0004 (כף ידו) — \u0003הרי זו דרך המינות,\u0004 כפירה במסורת חכמים ביחס למקום הנחת תפילין. \u0003ציפן\u0004 (את התפילין) \u0003זהב,\u0004 או ש\u0003נתנה\u0004 את התפילין של יד \u0003על בית אונקלי\u0004 (השרוול) \u0003שלו\u0004 מבחוץ — \u0003הרי זו דרך החיצונים,\u0004 כלומר, דרך היוצאים אל מחוץ למנהגי ישראל.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שפוסלים את הרוצה להתפלל בבגדים לבנים או כשהוא יחף — \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא מינות נזרקה בו,\u0004 שכן דרך לבושם של עובדי עבודה זרה, ולכן אין אנו מניחים לו להתפלל כלל.","שנינו במשנה: \u0003העושה תפלתו עגולה — סכנה ואין בה מצוה.\u0004 ומעירים: \u0003לימא תנינא להא דתנו רבנן\u0004 \u0005[האם נאמר ששנינו\u0006 כבר במשנה \u0005את זו ששנו חכמים\u0006 בברייתא\u0005],\u0006 ש\u0003תפלין מרובעות הלכה למשה מסיני! ואמר רבא:\u0004 \"מרובעות\" פירושו \u0003בתפרן ובאלכסונן,\u0004 כלומר, שצריכות להיות מרובעות מכל צד, ולכאורה כבר נאמר הדבר במשנתנו כשפסלה תפילה עגולה!","\u0003אמר רב פפא:\u0004 אין מכאן הוכחה, שאפשר לפרש ש\u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת באופן \u0003דעבידא כי אמגוזא\u0004 \u0005[שעשויה כמו אגוז],\u0006 כלומר, עגולה כולה ככדור, אבל אין הוכחה מן המשנה שבתי התפילין צריכים להיות מרובעים, שהרי אפשר לפרש שאף צורה מעוגלת, כל שאינה כצורת כדור — כשרה.","\u0003האומר\u0004"],["בנוסח תפילתו: \u0003\"יברכוך טובים\" — הרי זו דרך המינות\u0004 שהמינים מחלקים את העולם לשתי רשויות: של טוב ושל רע, ובאמת צריך לכלול את הכל בכלל הברכה. האומר בתפילתו \u0003\"על קן צפור יגיעו רחמיך\",\u0004 כלומר, רחם עלינו כשם שריחמת על ציפור הדוגרת על הביצים, שלא לקחת אם על הבנים, או האומר \u0003\"על טוב יזכר שמך\",\u0004 שמכך משתמע שמודה על הטובות בלבד, או האומר בתפילה \u0003'מודים' 'מודים'\u0004 (פעמיים) — \u0003משתקין אותו,\u0004 משום שאומר דברים שיש בהם חשש כפירה.","\u0003המכנה בעריות,\u0004 שאינו קורא את הדברים בפרשת עריות כפי שהם כתובים מפני הנימוס — \u0003משתקין אותו,\u0004 וכן \u0003האומר\u0004 ומתרגם את הכתוב \u0003\"ומזרעך לא תתן להעביר למלך\"\u0004 (ויקרא יח, כא) באופן זה: \"מזרעך \u0003לא תתן לאעברא בארמיותא\u0004 \u0005[לעבר את הארמית,\u0006 הגויה\u0005]\u0006\" — \u0003משתקין אותו בנזיפה\u0004 על שאומר דבר שאינו כדין.","דנים בהלכות שהובאו במשנה, ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שהאומר פעמיים \u0003'מודים' 'מודים'\u0004 משתקים אותו — משום \u0003דמיחזי\u0004 \u0005[שנראה]\u0006 כאילו מודה ל\u0003שתי רשויות,\u0004 וצריך להיזהר אפילו שלא להישמע כאילו מקבל דבר זה. והאומר: \u0003\"על טוב יזכר שמך\", נמי\u0004 \u0005[גם כן]\u0006 מובן, כי \u0003משמע על טוב\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 יזכר שם ה', \u0003על רע — לא, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003חייב אדם לברך על הרעה כשם שהוא מברך על הטובה. אלא \"על קן צפור יגיעו רחמיך\", מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין אומרים דבר זה?","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בבעיה זו \u0003תרי אמוראי במערבא\u0004 \u0005[שני אמוראים בארץ ישראל]:\u0006 \u0003ר' יוסי בר אבין ור' יוסי בר זבידא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מפני שמטיל קנאה במעשה בראשית,\u0004 שהוא מציג את הדברים כאילו אין הקדוש ברוך הוא נוהג ברחמים כלפי כל בריותיו ומפלה חלק מהם, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: מפני שעושה מדותיו של הקדוש ברוך הוא רחמים\u0004 ומפרש את טעמן בצורה פשטנית \u0003ו\u0004באמת \u0003אינן אלא גזירות,\u0004 שמשמען עמוק יותר.","מסופר: \u0003ההוא דנחית קמיה\u0004 \u0005[\u0006אדם \u0005אחד ירד\u0006 לעבור לפני התיבה \u0005בפני]\u0006 \u0003רבה,\u0004 ו\u0003אמר\u0004 בתוך תפילתו: \u0003אתה חסת על קן צפור\u0004 — \u0003אתה חוס ורחם עלינו! אתה חסת על \"אותו ואת בנו\"\u0004 (ויקרא כב, כח) שלא ישחטו ביום אחד — \u0003אתה חוס ורחם עלינו. אמר רבה: כמה ידע האי מרבנן לרצויי למריה\u0004 \u0005[כמה יודע תלמיד חכם זה לרצות לאדוניו,\u0006 לקדוש ברוך הוא\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003\"משתקין אותו\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ואין ראוי לומר כן!","ומעירים: \u0003ורבה\u0004 עצמו, שבודאי ידע משנה זו \u0003לחדודי\u0004 \u0005[לחדד]\u0006 את \u0003אביי הוא דבעא\u0004 \u0005[שרצה],\u0006 שבכוונה אמר לו דבר שאינו נכון על מנת לבדוק את ידיעותיו ואת הבנתו.","בנושא דומה מסופר: \u0003ההוא דנחית קמיה\u0004 \u0005[\u0006אדם \u0005אחד ירד\u0006 לפני התיבה \u0005לפני]\u0006 \u0003ר' חנינא,\u0004 ו\u0003אמר\u0004 בתפילתו: \u0003\"האל הגדול הגבור והנורא האדיר והחזק והאמיץ\".\u0004","לאחר מכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003סיימתינהו לשבחיה דמרך\u0004 \u0005[\u0006וכי \u0005סיימת את\u0006 כל \u0005השבחים של אדונך],\u0006 כלומר, האם בכך שהוספת כמה מילים כבר סיימת את כל שבחי הקדוש ברוך הוא? \u0003השתא הני תלתא\u0004 \u0005[עכשיו,\u0006 הרי \u0005אותם שלושה]\u0006 שבחים שאנו אומרים בתפילה: \"הגדול הגיבור והנורא\" \u0003אי לאו דכתבינהו\u0004 \u0005[אם לא שכתבם]\u0006 \u0003משה\u0004 רבינו \u0003באורייתא\u0004 \u0005[בתורה]\u0006 (דברים י, יז) \u0003ואתו\u0004 \u0005[ובאו]\u0006 אנשי \u0003כנסת הגדולה ותקנינהו\u0004 \u0005[ותיקנום\u0006 בנוסח התפילה\u0005]\u0006 (שאמרו בתפילתם: \"האל הגדול הגיבור והנורא... אל ימעט לפניך את כל התלאה אשר מצאתנו\" וכו'. נחמיה ט, לב), \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003לא אמרינן להו\u0004 \u0005[\u0006היינו מעזים \u0005לומר אותם],\u0006 \u0003ואת אמרת כולי האי\u0004 \u0005[ואתה אמרת כל כך].\u0006 \u0003משל לאדם שהיו לו אלף אלפי אלפים דינרי זהב והיו מקלסין\u0004 (משבחים) \u0003אותו באלף דינרי כסף\u0004 וכי \u0003לא גנאי הוא לו?\u0004","כיון שהזכרנו את דברי ר' חנינא, מביאים עוד מה ש\u0003אמר ר' חנינא: הכל בידי שמים חוץ מיראת שמים,\u0004 שדבר זה תלוי באדם עצמו, \u0003שנאמר: \"ועתה ישראל מה ה' אלהיך שאל מעמך כי אם ליראה\u0004 את ה' אלהיך\" (דברים י, יב).","על אותו פסוק תוהים: האם \u0003מכלל\u0004 הדברים אתה למד ש\u0003יראה מילתא זוטרתי\u0004 \u0005[דבר קטן]\u0006 \u0003היא?!\u0004 שהרי מלשון הפסוק נראה שאין ה' שואל מן האדם אלא דבר קטן — יראה בלבד! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003לגבי משה רבינו מילתא זוטרתא\u0004 \u0005[דבר קטן]\u0006 \u0003היא,\u0004 ולכן הוא אכן מדבר עליה כעל דבר קטן. \u0003משל לאדם שמבקשים\u0004 ממנו \u0003כלי גדול ויש לו\u0004 — הרי זה \u0003דומה עליו ככלי קטן,\u0004 ואם שואלים ממנו כלי \u0003קטן ואין לו — דומה עליו ככלי גדול.\u0004","\u0003אמר ר' זירא: האומר 'שמע' 'שמע'\u0004 (פעמיים) — הריהו \u0003כאומר 'מודים' 'מודים' דמי\u0004 \u0005[נחשב].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003הקורא את שמע וכופלה — הרי זה מגונה,\u0004 ונלמד מכאן: \u0003מגונה הוא דהוי\u0004 \u0005[שהוא],\u0006 אבל \u0003שתוקי\u0004 \u0005[להשתיק] —\u0006 \u0003לא משתקינן ליה\u0004 \u0005[משתקים אותו]\u0006 והרי ר' זירא משווה זאת לאומר 'מודים' 'מודים' שמשתקים אותו?! ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שמגונה הוא, מדובר באופן \u0003דאמר מילתא מילתא ותני לה\u0004 \u0005[כשאומר מלה מלה ושונה אותה],\u0006 \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 שאמרנו שמשתקים אותו, הרי זה באופן \u0003דאמר פסוקא פסוקא ותני לה\u0004 \u0005[שאומר פסוק פסוק ושונה אותו],\u0006 שזה נראה כמאמין בשתי רשויות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: ודלמא מעיקרא\u0004 \u0005[ושמא מתחילה]\u0006 \u0003לא כיון דעתיה\u0004 \u0005[דעתו]\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 \u0003כיון דעתיה\u0004 \u0005[דעתו]\u0006 ומשום כך הוא חוזר ואומר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי נוהגים \u0003חברותא\u0004 \u0005[\u0006ב\u0005חברות]\u0006 \u0003כלפי שמיא\u0004 \u0005[שמים],\u0006 שמדבר אל ה' כאילו היה מדבר לחבירו ואינו מכוון במה שאומר בתפילה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא מכוין דעתיה\u0004 \u0005[דעתו],\u0006 \u0003מחינא ליה בארזפתא דנפחא\u0004 \u0005[מכים אותו במקבת של נפחים]\u0006 \u0003עד דמכוין דעתיה\u0004 \u0005[שיכוין דעתו].\u0006 כלומר, צריך להקפיד ולהחמיר עליו שלא ינהג קלות ראש בדבריו לפני המקום.","שנינו במשנה: \u0003המכנה בעריות\u0004 — \u0003משתקים אותו. תנא\u0004 \u0005[שנה]\u0006 \u0003רב יוסף:\u0004 הכוונה היא, שבמקום לומר במפורש ובלשון נוכח \"ערות אביך\", הריהו מדבר מענין \u0003קלון אביו וקלון אמו,\u0004 שמוציא את הפסוק מידי פשוטו ומפרשו אל תגלה כל דבר קלון שבהם.","עוד שנינו במשנה: \u0003האומר\u0004 שכוונת הכתוב \u0003\"מזרעך לא תתן להעביר\u0004 למולך \u0003\"\u0004היא — \"מזרעך לא תיתן לעבר את הגויה\", משתקים אותו בנזיפה. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 המתרגם כך סבור כי \u0003בישראל הבא על הגויה והוליד ממנה בן לעבודה זרה הכתוב מדבר.\u0004","\u0003מעשה ראובן,\u0004 שנאמר בו: \"וישכב את בלהה פילגש אביו\" (בראשית לה, כב) — \u0003נקרא\u0004 אמנם בתורה אבל \u0003לא מתרגם\u0004 בציבור, שלא להביא את עמי הארצות לבזותו. \u0003מעשה תמר\u0004 (בראשית פרק לח) — \u0003נקרא ומתרגם. מעשה עגל הראשון,\u0004 כלומר, מה שמסופר בתורה על מעשה העגל — \u0003נקרא ומתרגם, והשני,\u0004 שאהרן מספר על עשייתו — \u0003נקרא ולא מתרגם.\u0004 פסוקי \u0003ברכת כהנים\u0004 ו\u0003מעשה דוד ואמנון\u0004 (שמואל ב' פרק יג) — \u0003נקראין ולא מתרגמין.\u0004","\u0003אין מפטירין ב\u0004מעשה \u0003מרכבה\u0004 שביחזקאל (פרק א), כדי שלא לפרסם דברים נסתרים, \u0003ור' יהודה מתיר. ר' אליעזר אומר: אין מפטירים ב\"הודע את ירושלים\u0004 את תועבותיה\u0003\"\u0004 (יחזקאל ט״ז:ב׳), מפני שהוא גנותם של ישראל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יש\u0004 כתובים שהם \u0003נקרין ומתרגמין, ויש\u0004 שהם \u0003נקרין ולא מתרגמין, ויש\u0004 שהם \u0003לא נקרין ולא מתרגמין. אלו נקרין ומתרגמין,\u0004 ו\u0003בל\"ת עק\"ן נשפ\"ה,\u0004 הוא ה\u0003סימן\u0004 להם (\u0003ב\u0004ראשית, \u0003ל\u0004וט, \u0003ת\u0004מר, \u0003ע\u0004גל, \u0003ק\u0004ללות, אזהרות ועו\u0003נ\u0004שים, אמ\u0003נ\u0004ון, אב\u0003ש\u0004לום, \u0003פ\u0004ילגש, \u0003ה\u0004ודע):","\u0003מעשה בראשית נקרא ומתרגם.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 מדוע לא יקראו אותו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003אתו לשיולי\u0004 \u0005[יבואו\u0006 אנשים \u0005לשאול]\u0006 שאלות שאין ראוי לשאול, וכגון: \u0003מה למעלה ומה למטה,\u0004"],["\u0003ומה לפנים ומה לאחור,\u0004 כלומר, על מה שקדם לבריאה ועל מה שיהיה אחר כך, וכולם דברים שאין ראוי לעסוק בהם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך.","שנינו: \u0003מעשה לוט ושתי בנותיו נקרא ומתרגם.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ומדוע לא? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003לכבודו\u0004 של \u0003אברהם,\u0004 שהרי לוט היה בן אחיו, ובזיון הוא גם לאברהם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך.","שנינו ש\u0003מעשה תמר ויהודה נקרא ומתרגם.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש\u0004 \u0005[נחשוש]\u0006 \u0003לכבודו\u0004 של \u0003יהודה,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי אדרבא \u0003שבחיה\u0004 \u0005[שבחו]\u0006 \u0003הוא דאודי\u0004 \u0005[שהודה]\u0006 על חטאו. שנינו כי \u0003מעשה עגל ראשון נקרא ומתרגם.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש\u0004 \u0005[לחשוש]\u0006 \u0003לכבודם של ישראל,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כל שכן דניחא להו\u0004 \u0005[שנוח להם]\u0006 שיתפרסם הדבר, \u0003דהויא להו\u0004 \u0005[שתהיה להם]\u0006 \u0003כפרה\u0004 על ידי בזיונם. שנינו בברייתא: \u0003קללות וברכות נקראין ומתרגמין.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחוש דלמא פייגא דעתייהו דצבורא\u0004 \u0005[נחשוש שמא תפוג\u0006 תיחלש \u0005דעתו של הציבור]\u0006 שיבהל מחמת ריבוי הקללות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך. שנינו כי \u0003אזהרות ועונשין נקראין ומתרגמין.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ניחוש דלמא אתו למעבד\u0004 \u0005[נחשוש שמא יבואו לעשות]\u0006 \u0003מיראה,\u0004 מפני העונש ולא מאהבת ה', על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לחשוש לכך.","","","","עוד שנינו, כי \u0003מעשה אמנון ותמר נקרא ומתרגם,\u0004 וכן \u0003מעשה אבשלום נקרא ומתרגם.\u0004 ושואלים \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש ליקריה\u0004 \u0005[נחשוש לכבודו]\u0006 של \u0003דוד,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לחשוש לכך.","עוד שנינו, כי \u0003מעשה פילגש בגבעה נקרא ומתרגם.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש\u0004 \u0005[נחשוש]\u0006 \u0003לכבודו\u0004 של \u0003בנימין,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך. שנינו כי \u0003\"הודע את ירושלים את תועבותיה\"\u0004 (יחזקאל טז, ב) \u0003נקרא ומתרגם.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי ר' \u0003אליעזר\u0004 שאסר. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה באדם אחד שהיה קורא למעלה\u0004 (בפני) \u0003מר' אליעזר\u0004 בהפטרה של \u0003\"הודע את ירושלים את תועבותיה\". אמר לו\u0004 רבי אליעזר: \u0003עד שאתה בודק בתועבות ירושלים צא ובדוק בתועבות אמך.\u0004 ומסופר: \u0003בדקו\u0004 בו, \u0003ומצאו בו שמץ\u0004 (חשש־מה) של \u0003פסול,\u0004 שאכן היה באמו פסול זנות, וממזר היה. עוד שנינו בברייתא, \u0003ואלו נקראין ולא מתרגמין,\u0004 ו\u0003רעבד\"ן\u0004 הוא \u0003סימן\u0004 להם (\u0003ר\u0004 אובן, \u0003ע\u0004 גל, \u0003ב\u0004רכת כהנים, \u0003ד\u0004וד ואמ \u0003נ\u0004 ון): \u0003מעשה ראובן נקרא ולא מתרגם. ומעשה בר' חנינא בן גמליאל שהלך ל\u0004כפר \u0003כבול, והיה קורא חזן\u0004 בית \u0003הכנסת \"ויהי בשכן ישראל\u0004 בארץ ההיא וילך ראובן וישכב את בלהה פילגש אביו וישמע ישראל ויהיו בני יעקב שנים עשר\u0003\"\u0004 (בראשית לה, כב), \u0003ואמר לו למתורגמן: הפסק, אל תתרגם אלא אחרון\u0004 (סוף הפסוק), \u0003ושיבחוהו חכמים\u0004 על כך.","","","שנינו כי \u0003מעשה עגל השני נקרא ולא מתרגם.\u0004 ומסבירים: \u0003איזה מעשה עגל השני\u0004 — \u0003מן \"ויאמר משה\u0004 אל אהרן \u0003\"\u0004וכו' (שמות לב, כא) \u0003עד \"וירא משה\"\u0004 (שמות לב, כה).","וכהסבר לזה מביאים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: לעולם יהא אדם זהיר בתשובותיו,\u0004 שלפעמים התשובה גרועה יותר מן ההאשמה, \u0003שמתוך תשובה שהשיבו אהרן למשה פקרו\u0004 (כפרו) \u0003המינין, שנאמר\u0004 בדברי אהרן: \u0003\"ואשלכהו באש ויצא העגל הזה\"\u0004 (שמות לב, כד), ומלשונו נראה שהעגל יצא מעצמו ויש בו ממש.","עוד שנינו כי פסוקי \u0003ברכת כהנים נקרין ולא מתרגמין\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 ומסבירים: \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"ישא\u0004 ה' פניו אליך\u0003\"\u0004 (במדבר ו, כו), ועלולים אנשים לתהות שיש כביכול משוא פנים לפני הקדוש ברוך הוא.","שנינו כי \u0003מעשה דוד ואמנון לא נקרין ולא מתרגמין.\u0004 ומקשים: \u0003והא אמרת\u0004 \u0005[והרי אמרת]\u0006 ש\u0003מעשה אמנון ותמר נקרא ומתרגם!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין קוראים, הוא דווקא במקום \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 בו \u0003\"אמנון בן דוד\",\u0004 שלא לבזות את דוד, \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 שאמרנו שקוראים, הוא במקום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אמנון\" סתמא\u0004 \u0005[סתם].\u0006 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל המקראות הכתובים בתורה לגנאי\u0004 שיש בהם מלה שאינה בלשון נקיה, \u0003קורין אותן\u0004 בתורה \u0003לשבח\u0004 ויש בזה איפוא כתיב וקרי שונים. \u0003כגון\u0004 מה שכתוב \u0003\"ישגלנה\"\u0004 (דברים כח, ל), שקוראים \u0003\"ישכבנה\". \"בעפלים\"\u0004 (דברים כח, כז) — קוראים \u0003\"בטחורים\". \"חריונים\"\u0004 (מלכים ב' ו, כה) — קוראים \u0003\"דביונים\". \"לאכל את חוריהם ולשתות את מימי שיניהם\"\u0004 (מלכים יח, כז) — קוראים: \u0003\"לאכול את צואתם ולשתות את מימי רגליהם\".\u0004 וכן \u0003\"\u0004ויתצו את בית הבעל וישימוהו \u0003למחראות\"\u0004 (מלכים י, כז) — קוראים \u0003\"למוצאות\". ר' יהושע בן קרחה אומר: \"למחראות\"\u0004 קוראים \u0003כשמן\u0004 כפי שנכתב, \u0003מפני שהוא גנאי לעבודה זרה,\u0004 ומותר להשתמש בלשון שאינה נקיה לשם זה.","","","וכיוצא בו \u0003אמר רב נחמן: כל ליצנותא\u0004 \u0005[ליצנות\u0006 ומילים מגונות\u0005]\u0006 \u0003אסירא\u0004 \u0005[אסורה],\u0006 \u0003בר מליצנותא\u0004 \u0005[חוץ מליצנות]\u0006 של \u0003עבודה זרה דשריא\u0004 \u0005[ש\u0006היא \u0005מותרת].\u0006 וראיה לדבר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כרע בל קרס נבו\"\u0004 (ישעיהו מו, א), שאנחנו מבינים אותו שהנביא מתאר שהבעל כורע לעשות צרכיו. וכעין זה מפרשים \u0003\"קרסו כרעו יחדו לא יכלו מלט משא\"\u0004 (ישעיהו מו, ב), באותו מובן. \u0003ר' ינאי אמר מהכא\u0004 \u0005[מכאן]\u0006 מכתוב זה למדים שמותר להתלוצץ על עבודה זרה — שנאמר: \u0003\"לעגלות בית און יגורו שכן שמרון כי אבל עליו עמו וכמריו עליו יגילו על כבודו כי גלה ממנו\"\u0004 (הושע י, ה), \u0003אל תקרי\u0004 (תקרא) \u0003\"כבודו\" אלא \"כבידו\",\u0004 כלומר, כאילו הוא אינו יכול להמנע מלעשות צרכיו.","\u0003אמר רב הונא בר מנוח משמיה\u0004 \u0005[בשמו]\u0006 \u0003של רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: שרי ליה\u0004 \u0005[מותר לו]\u0006 \u0003לבר\u0004 \u0005[לבן]\u0006 \u0003ישראל למימר ליה\u0004 \u0005[לומר לו]\u0006 \u0003לגוי: שקליה\u0004 \u0005[קח אותו]\u0006 את ה\u0003עבודה זרה ואנחיה בשין תיו שלו\u0004 \u0005[והנח אותו בשת שלך],\u0006 כלומר, באחוריו. \u0003אמר רב אשי: האי מאן דסנאי שומעניה\u0004 \u0005[מי ששמועתו רעה],\u0006 שידוע שהוא נואף — \u0003שרי ליה לבזוייה\u0004 \u0005[מותר לבזותו]\u0006 \u0003בגימ\"ל ושי\"ן,\u0004 שהם ראשי תיבות של בן \u0003ג\u0004 ירתא \u0003ס\u0004 ריא (= בן זונה מסריחה). \u0003האי מאן דשפיר שומעניה\u0004 \u0005[\u0006ו\u0005מי שטובה שמועה עליו]\u0006 — \u0003שרי לשבוחיה\u0004 \u0005[מותר לשבח אותו]\u0006 בפרהסיא, \u0003ומאן דשבחיה\u0004 \u0005[ומי שמשבח אותו]\u0006 — \u0003ינוחו לו ברכות על ראשו.\u0004","","\u0003בני העיר שמכרו רחובה של עיר\u0004 לצורך אחר, ואין משתמשים עוד ברחבה הזאת לצרכי ציבור (שיש בהם גם דברים שבקדושה) — \u0003לוקחין\u0004 (קונים) \u0003בדמיו\u0004 (במחירו) של הרחוב \u0003בית הכנסת.\u0004 מכרו \u0003בית הכנסת\u0004 — \u0003לוקחין תיבה\u0004 (ארון קודש). מכרו \u0003תיבה — לוקחים מטפחות\u0004 לעטוף בהם את ספרי הקודש. מכרו \u0003מטפחות\u0004"]]};
